INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('telangana-economy-te-ch3-macro-economics', 'telangana-economy-te', 3, 'స్థూల ఆర్థిక (Macro Economics)', '[{"a":"రూ.17,82,198 కోట్లు","e":"ఇది 2024-25 (FRE)తో పోలిస్తే 10.7% వృద్ధి రేటును సూచిస్తుంది, ఇది జాతీయ వృద్ధి రేటు 8.0% కంటే గణనీయంగా ఎక్కువ. పూర్తి ప్రస్తుత/స్థిర ధరల పోలిక కోసం దిగువ పట్టిక చూడండి.","table":{"headers":["వివరణ","2024-25 (ప్రస్తుత ధరలు, రూ. కోట్లు)","2025-26 (ప్రస్తుత ధరలు, రూ. కోట్లు)","వృద్ధి రేటు% (ప్రస్తుత)","2024-25 (స్థిర ధరలు, రూ. కోట్లు)","2025-26 (స్థిర ధరలు, రూ. కోట్లు)","వృద్ధి రేటు% (స్థిర)"],"rows":[["తెలంగాణ","16,09,902","17,82,198","10.7","8,20,197","8,89,582","8.5"],["అఖిల భారత","3,30,68,145","3,57,13,886","8.0","1,87,96,955","2,01,89,919","7.4"]]},"type":"mcq","options":{"a":"రూ.8,89,582 కోట్లు","b":"రూ.17,82,198 కోట్లు","c":"రూ.18,21,340 కోట్లు","d":"రూ.16,09,902 కోట్లు"},"answer":"b"},{"a":"8.5%","e":"","table":null,"type":"mcq","options":{"a":"10.7%","b":"8.5%","c":"7.4%","d":"8.0%"},"answer":"b"},{"a":"4.99%","e":"","table":null,"type":"mcq","options":{"a":"4.99%","b":"5.24%","c":"5.10%","d":"4.92%"},"answer":"a"},{"a":"రూ.4,18,931","e":"ఇది అదే సంవత్సరానికి జాతీయ సగటు తలసరి ఆదాయం రూ.2,19,575 కంటే దాదాపు రెట్టింపు, ఇది 10.2% వృద్ధి రేటును ప్రతిబింబిస్తుంది. పూర్తి ప్రస్తుత/స్థిర ధరల పోలిక కోసం దిగువ పట్టిక చూడండి.","table":{"headers":["వివరణ","2024-25 (ప్రస్తుత ధరలు, రూ.)","2025-26 (ప్రస్తుత ధరలు, రూ.)","వృద్ధి రేటు% (ప్రస్తుత)","2024-25 (స్థిర ధరలు, రూ.)","2025-26 (స్థిర ధరలు, రూ.)","వృద్ధి రేటు% (స్థిర)"],"rows":[["తెలంగాణ","3,80,031","4,18,931","10.2","1,88,436","2,04,022","8.3"],["అఖిల భారత","2,05,324","2,19,575","6.9","1,14,710","1,21,968","6.3"]]},"type":"mcq","options":{"a":"రూ.4,18,931","b":"రూ.2,19,575","c":"రూ.3,80,031","d":"రూ.4,76,679"},"answer":"a"},{"a":"8.3%","e":"","table":null,"type":"mcq","options":{"a":"6.3%","b":"8.3%","c":"10.2%","d":"5.5%"},"answer":"b"},{"a":"6.9%","e":"","table":null,"type":"mcq","opt