INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-1-satavahanas', 'telangana-history-te', 1, 'శాతవాహనులు', '[{"a":"ఐతరేయ బ్రాహ్మణం","e":"క్రీస్తుకు పూర్వం వెయ్యి సంవత్సరాల నాటిదిగా పేర్కొనబడింది.","table":null},{"a":"గణతంత్ర రాజ్యాలు","e":"","table":null},{"a":"శ్రీముఖుడు","e":"","table":null},{"a":"క్రీ.పూ. 225","e":"","table":null},{"a":"శాలివాహనులు, శాతకర్ణులు","e":"","table":null},{"a":"450 సంవత్సరాలు","e":"","table":null},{"a":"శ్రీకృష్ణుడు","e":"","table":null},{"a":"నాసిక్","e":"","table":null},{"a":"ఉజ్జయిని","e":"తర్వాత విదిశ నగరాన్ని కూడా ఆక్రమించారు.","table":null},{"a":"ప్రతిష్ఠానపురం","e":"దీనినే పైఠాన్ అని కూడా అంటారు, ఔరంగాబాద్ జిల్లాలో గోదావరి నదికి ఉత్తర తీరాన ఉంది.","table":null},{"a":"అమరావతి","e":"దీన్ని ధాన్యకటకమని కూడా పిలిచేవారు.","table":null},{"a":"శకులు","e":"","table":null},{"a":"సుశర్మ","e":"ఇతన్ని శాతవాహన శ్రీముఖుడు యుద్ధంలో ఓడించి, వధించి మగధరాజ్యాన్ని ఆక్రమించుకున్నాడు.","table":null},{"a":"19 మంది","e":"","table":null},{"a":"300 సంవత్సరాలు","e":"","table":null},{"a":"అరేబియా సముద్రం","e":"","table":null},{"a":"కయిన్స్ ఆఫ్ ఆంధ్ర","e":"ఇందులో భారతీయ క్షత్రియుల రాజ్యాలను గురించి పేర్కొన్నాడు.","table":null},{"a":"ముప్పయి పట్టణాలు","e":"క్రీస్తుకు పూర్వం 300 సంవత్సరాల క్రితం పేర్కొన్నాడు.","table":null},{"a":"కొండాపురం","e":"","table":null},{"a":"గౌతమీపుత్ర పులోమావి","e":"","table":null},{"a":"బుద్ధం, ధర్మం, సంఘం","e":"","table":null},{"a":"హీనయాన బౌద్ధం","e":"","table":null},{"a":"గౌతమీపుత్రుడు","e":"","table":null},{"a":"పులోమావి","e":"","table":null},{"a":"కోటిలింగాల","e":"","table":null},{"a":"డైనేజి పద్ధతి","e":"","table":null},{"a":"విక్రమశకం, శాలివాహనశకం","e":"విక్రమశకం క్రీ.పూ. 58 నుండి, శాలివాహనశకం క్రీ.శ. 76 నుండి లెక్కకు వస్తాయి.","table":null},{"a":"శాలివాహనశకం","e":"","table":null},{"a":"ప్రాకృతం","e":"","table":null},{"a":"పాళీ భాష","e":"","table":null},{"a":"శర్వవర్మ","e":"","table":null},{"a":"కాతంత్ర వ్యాకరణము","e":"","table":null},{"a":"5 సంవత్సరాలు","e":"క్రీ.పూ. 19 నుండి 24 వరకు.","table":null},{"a":"గాధా సప్తశతి","e":"ఇందులో 700 శృంగార గాథలున్నాయి.","table":null},{"a":"కవివత్సలుడు","e":"","table":null},{"a":"అపర బుద్ధుడు","e":"","table":null},{"a":"మహాయాన బౌద్ధం","e":"","table":null},{"a":"శ్రీపర్వతం","e":"కృష్ణా నదీ తీరంలో ఉంది.","table":null},{"a":"బృహత్కథ","e":"","table":null},{"a":"కామసూత్రాలు","e":"","table":null},{"a":"ప్రాజ్ఞ పారమిత సూత్రం, సుహృల్లేఖ","e":"","table":null},{"a":"కందుక క్రీడ","e":"","table":null},{"a":"ఏనుగులు, గుర్రాలు, రథాలు, సైనికులు","e":"","table":null},{"a":"మాతృభక్తి","e":"పేరుకు ముందు తల్లిపేరు చెప్పుకునేవారు.","table":null},{"a":"ధాన్యకటకం, జగ్గయ్యపేట, భట్టిప్రోలు, ఘంటసాల, నాగార్జునకొండ","e":"","table":null},{"a":"బౌద్ధ, వైదిక మతాలు","e":"శాతవాహనుల మతసహనానికి నిదర్శనం.","table":null},{"a":"506 సంవత్సరాలు","e":"క్రీ.పూ. 833 నుండి క్రీ.శ. 327 వరకు అని మూలంలో పేర్కొనబడింది.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-10-nizam-chapter-1', 'telangana-history-te', 10, 'నిజాం 1', '[{"a":"ఆసఫ్‌జాహీ నిజాం వంశం","e":"","table":null},{"a":"మీర్ ఖమ్రుద్దీన్‌ఖాన్","e":"","table":null},{"a":"తుర్కీస్తాన్","e":"","table":null},{"a":"షాజహాన్","e":"","table":null},{"a":"చీన్‌ఖులిచ్‌ఖాన్","e":"","table":null},{"a":"షాహబొద్దీన్","e":"","table":null},{"a":"అల్లామీ షహీదుల్లాఖాన్ కుమార్తె","e":"ఇతను షాజహాన్ కాలంలో ప్రధానమంత్రిగా పనిచేశాడు.","table":null},{"a":"1671 ఆగస్టు 11","e":"","table":null},{"a":"బీజాపూర్ గవర్నరు","e":"","table":null},{"a":"పంచ్‌హజారీ","e":"","table":null},{"a":"1707 ఫిబ్రవరి 20","e":"","table":null},{"a":"గజనీ నుండి చట్గాన్ వరకు, కాశ్మీర్ నుండి కర్నాటక వరకు","e":"","table":null},{"a":"ఔరంగజేబు","e":"","table":null},{"a":"వారసత్వ యుద్ధాలు","e":"","table":null},{"a":"ఆజమ్, మొహజమ్‌ల మధ్య","e":"","table":null},{"a":"మొహజమ్ (బహదూర్‌షా)","e":"","table":null},{"a":"ఖాన్‌దౌరాన్, బహదూర్‌ఖాన్","e":"సైద్ (అయోధ్య) ప్రాంతానికి సుబేదారుగాను, లక్నో విభాగానికి ఫౌజ్దారు (సేనాని)గాను నియమించాడు.","table":null},{"a":"ఐదు సంవత్సరాలు, 1712లో","e":"","table":null},{"a":"జహందార్‌షా","e":"","table":null},{"a":"సయ్యద్ సోదరులు (అమీరుల్ ఉమ్రాహసేన్ అలీఖాన్, కుతుబుల్ ముల్క్ అబ్దుల్లాఖాన్)","e":"","table":null},{"a":"దక్షన్","e":"నిజాంకు ఫతేజంగ్, నిజాముల్‌ముల్క్ బిరుదునిచ్చి సత్కరించాడు.","table":null},{"a":"ముబారిజ్‌ఖాన్","e":"","table":null},{"a":"1724 అక్టోబరు 11","e":"ఔరంగాబాద్ సమీపంలోని పెక్కర్‌ఖేడా వద్ద జరిగింది.","table":null},{"a":"1724 అక్టోబరు 11 (ముబారిజ్‌ఖాన్‌ను చంపిన రోజే)","e":"","table":null},{"a":"మహమ్మద్‌షా","e":"దక్షను సుబేదారుగా నియమిస్తున్నట్లు అధికార పత్రం జారీ చేశాడు.","table":null},{"a":"నిజాం ప్రభువుల వంశనామానికి","e":"","table":null},{"a":"విహార భూమి","e":"నాదిర్షా, అహమద్‌షా అబ్దాలీ వంటివారికి ఇది విహారభూమిగా మారింది.","table":null},{"a":"ఢిల్లీ","e":"మహమ్మద్‌షా కబురుపై దక్షనులో స్థిర స్థాపనలో నిమగ్నుడైన నిజాం ఢిల్లీకి బయలుదేరాడు.","table":null},{"a":"ఇరాన్","e":"","table":null},{"a":"మహమ్మద్‌షా అవమానం చేసినందుకు","e":"నాదిర్షాను ఒక అల్పజ్ఞాని కింద తీసుకుని మహమ్మద్‌షా సమాధానాలు పంపలేదు.","table":null},{"a":"2 కోట్ల రూపాయలు","e":"","table":null},{"a":"నాదిర్షాను చంపివేశారనే పుకార్లు","e":"ఈ ఊచకోతలో లక్షాయాభైవేలమంది చనిపోయారు.","table":null},{"a":"నెమలి సింహాసనం","e":"15, 20 కోట్ల విలువైన ధనరాసులు, వజ్ర వైడూర్యాలతో పాటు నెమలి సింహాసనాన్ని సమర్పించారు.","table":null},{"a":"1774","e":"","table":null},{"a":"తిరుచనాపల్లి","e":"మద్రాసు పరిపరచుకున్నాడు, ఆనాడు ఔరంగాబాద్ దక్షన్ రాజధాని.","table":null},{"a":"బాలకొండ","e":"తెలంగాణాలోని బాలకొండ పాలకుడు స్వాతంత్ర్యం ప్రకటించుకోవడంతో జయించాడు.","table":null},{"a":"ఫ్రెంచివారు, బ్రిటీష్‌వారు","e":"","table":null},{"a":"దక్షన్‌లో నిజాం ఆస్థానంలో","e":"","table":null},{"a":"ఢిల్లీ సింహాసనం","e":"","table":null},{"a":"బురహాన్‌పూర్ వద్ద, 1748లో","e":"","table":null},{"a":"ఖుల్దాబాద్ సమీపంలోని ఫకీరు","e":"","table":null},{"a":"ఏడు కుల్చాలు, ఐదు తిన్నాడు","e":"దీని ఆధారంగా ఫకీరు నిజాం వంశం ఐదు తరాలు అంతరించిపోతుందని జోస్యం చెప్పాడు.","table":null},{"a":"ఆశీర్వదించి పంపించాడు","e":"ఆనాటి పసుపు పచ్చబట్ట మధ్య గుండ్రటి రొట్టెముక్క నిజాం ప్రభుత్వ పతాకమైంది.","table":null},{"a":"శ్వేతవర్ణంలో","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-11-nizam-chapter-2', 'telangana-history-te', 11, 'నిజాం- 2', '[{"a":"1761","e":"","table":null},{"a":"సదాశివరావు పీష్వా","e":"","table":null},{"a":"అహమద్‌షా అబ్దాలీ","e":"ఇతను ఇరాన్ దేశపువాడు.","table":null},{"a":"మల్హర్‌రావు హోల్కర్","e":"","table":null},{"a":"ఒకే దెబ్బతో శత్రువులను నాశనం చేయటం ప్రయోజనకారి అని భావించడం","e":"","table":null},{"a":"చిన్న సహాయం చేసి ఊరుకున్నాడు","e":"దీనితో అతి శ్రేష్ఠమైన హిందూ సైన్యం పూర్తిగా ఓడిపోయి సర్వనాశనం అయిపోయింది.","table":null},{"a":"దురాక్రమణదారుడు (అహమద్‌షా అబ్దాలీ)","e":"","table":null},{"a":"హైదర్ అలీ","e":"","table":null},{"a":"గుంటూరు మండలం","e":"","table":null},{"a":"1782","e":"","table":null},{"a":"జాన్సన్","e":"","table":null},{"a":"గుంటూరు మండలం","e":"","table":null},{"a":"1778","e":"","table":null},{"a":"మీర్ ఆలమ్","e":"","table":null},{"a":"టిప్పుసుల్తాన్","e":"ఈ యుద్ధంలో కర్నూలు నవాబు నిజాంకు ఎదురు తిరిగాడు.","table":null},{"a":"సర్దేశ్‌ముఖీ, చౌత్","e":"","table":null},{"a":"మోషేరేమాండ్","e":"ఇతను ఫ్రెంచ్ సేనాని.","table":null},{"a":"బేగమ్‌ల మాటలు విని మధ్యలోనే యుద్ధం ఆపివేయడం","e":"","table":null},{"a":"36 లక్షల ఆదాయంవచ్చే ఇలాకాను, 2 లక్షల రూపాయల నగదును","e":"సతారా, బీదరు, బీజాపూర్, దౌలతాబాద్ మొదలైన ఇలాకాలు, తన ప్రధాని అరస్తూజాను కూడా సమర్పించుకున్నాడు.","table":null},{"a":"హైదరాబాద్","e":"","table":null},{"a":"ఫ్రెంచ్ సేనలు","e":"","table":null},{"a":"అలీజా","e":"","table":null},{"a":"టిప్పుసుల్తాన్","e":"","table":null},{"a":"1798లో లార్డ్ వెల్లస్లీ","e":"ఇతను గవర్నరు జనరల్‌గా వచ్చాడు.","table":null},{"a":"నిజాం","e":"","table":null},{"a":"మీర్ ఆలమ్","e":"","table":null},{"a":"టిప్పుసుల్తాన్","e":"","table":null},{"a":"సీడెడ్ జిల్లాలు","e":"","table":null},{"a":"1803","e":"43 సంవత్సరాల సుదీర్ఘ పరిపాలన జరిపాడు.","table":null},{"a":"40 వేల రూపాయలు","e":"సాలీన కైంకర్యాలకు మంజూరు చేశాడు.","table":null},{"a":"The treaty of subsidiary","e":"","table":null},{"a":"సికిందరాబాద్","e":"","table":null},{"a":"భవన నిర్మాణ పథకం","e":"","table":null},{"a":"\"నీకు ఎంత భవనం కావాలో అంతే పథకం తయారు చేసుకోవచ్చు\" అని","e":"","table":null},{"a":"కోడి గుడ్డంతనో, పోస్టుకార్డంతనో పథకం తయారు చేసుకొమ్మని","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-12-nizam-chapter-3', 'telangana-history-te', 12, 'నిజాం- 3', '[{"a":"మీర్ మహబూబ్ అలీఖాన్ బహదూర్","e":"","table":null},{"a":"రెండు సంవత్సరాల వయస్సులో, 1869లో","e":"","table":null},{"a":"సాలార్‌జంగ్","e":"","table":null},{"a":"షమ్‌ఘుల్ ఉమ్రాను","e":"","table":null},{"a":"బ్రిటీష్ వారికి బాకీ ఉన్న 8 మిలియన్ పౌండ్ల డబ్బును సమకూర్చిపెట్టుకున్నాడు","e":"","table":null},{"a":"1883","e":"","table":null},{"a":"18 ఏళ్ళు","e":"","table":null},{"a":"లార్డ్ రిప్పన్","e":"చౌమహల్లా రాజ ప్రాసాదంలో దర్బారు జరిగింది, ఈ సమావేశంలోనే నిజాంకు సమస్త అధికారాలు దత్తమైనాయి.","table":null},{"a":"ముల్కీ-నాన్ ముల్కీ సమస్యలు","e":"","table":null},{"a":"జాయింట్ అడ్మినిస్ట్రేటర్‌గా","e":"","table":null},{"a":"ఉర్దూ భాష","e":"","table":null},{"a":"1887 ఏప్రిల్‌లో","e":"","table":null},{"a":"అస్మాన్‌జా, సర్ వికారుల్ ఉమ్రా, మహారాజా సర్ కిషన్ ప్రసాద్","e":"","table":{"headers":["ప్రధాని పేరు","పదవీకాలం"],"rows":[["అస్మాన్‌జా","1893 వరకు"],["సర్ వికారుల్ ఉమ్రా","1901 వరకు"],["మహారాజా సర్ కిషన్ ప్రసాద్","1912 వరకు (11 సంవత్సరాలు)"]],"unit":"ప్రధాని పదవీకాలం"}},{"a":"''ఖానూన్-చె-ముబారక్''","e":"అందులో మంత్రివర్గం, విధాన సభ మొదలైనవి చేర్చబడ్డాయి, కానీ ప్రజలకు రాజ్యాంగపరమైన హక్కులేవీ లభించలేదు.","table":null},{"a":"అఫ్గన్ యుద్ధాలు","e":"నిజాం 60 లక్షల రూపాయల నగదు, పెద్ద సంఖ్యలో సైన్యం పంపి బ్రిటీష్ వారిని ఆదుకున్నాడు.","table":null},{"a":"బిరారు","e":"నిజాంకు జి.సి.బి. (నైట్ ఆఫ్ గ్రాండ్ క్రాస్) బిరుదు ప్రదానం చేశారు.","table":null},{"a":"\"గేవ్ కర్జన్ బిరార్\" (జి-అనగా గేవ్, సి-అనగా కర్జన్, బి-అనగా బిరారు)","e":"","table":null},{"a":"శ్రీపాద దామోదర్ సాత్వాలేకర్, ఆర్యసమాజ్ నాయకుడు కేశవరావుతో","e":"","table":null},{"a":"లెక్చర్లివ్వడం మానుకో, పాటకచ్చేరీలు జరుపు, చిత్రలేఖనంతో డబ్బు సంపాదించుకో అన్న షరతును అంగీకరించనందుకు","e":"","table":null},{"a":"సంస్థానం నుంచి","e":"","table":null},{"a":"తుఫాను, భారీ వర్షాలవల్ల మూసీనది వరదలు","e":"","table":null},{"a":"19000 ఇళ్ళు, దాదాపు 15000 మంది","e":"మూడు కోట్ల రూపాయలు నష్టం వాటిల్లినట్లు అంచనావేశారు.","table":null},{"a":"సర్ మోక్షగుండం విశ్వేశ్వరయ్య","e":"హైదరాబాద్ నగరానికి వరద, మురుగు నీటి నుంచి శాశ్వతంగా రక్షణ కల్పించే పథకం రూపొందించే బాధ్యత అప్పగించారు.","table":null},{"a":"ధర్మాత్ముడు","e":"హిందూ-ముస్లిం భేదభావం లేకుండా పాలన సాగించాడు.","table":null},{"a":"మాణిక్య ప్రభువు","e":"అందుకే ఆయన పేరు వచ్చేవిధంగా తమ పిల్లల పేర్లు పెట్టుకున్నారు (మహబూబ్‌రాయ్, మహబూబ్ కరన్, మహబూబ్ పర్షాద్, మహబూబ్ రెడ్డి).","table":null},{"a":"అఘోరనాథ్ చట్టోపాధ్యాయ","e":"","table":null},{"a":"అఘోరనాథ్","e":"","table":null},{"a":"హైదరాబాద్ నుండి బహిష్కరణ శిక్ష","e":"1888లో వైస్రాయ్‌కు అపీలు చేసుకోగా రెసిడెంటును బయటికి పంపివేసి తిరిగి ఉద్యోగంలో తీసుకున్నారు.","table":null},{"a":"అఘోరనాథుడు","e":"","table":null},{"a":"1911 ఏప్రిల్ 3, ఫలక్‌నుమా రాజభవనంలో","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-13-nizam-chapter-4', 'telangana-history-te', 13, 'నిజాం- 4', '[{"a":"1911 ఆగస్టు 11","e":"ఆరవ నిజాం మీర్ మహబూబ్ అలీఖాన్ బహదూర్ చనిపోయిన అదేరోజు చివర ఉస్మాన్ అలీఖాన్ తన 21వ యేట గద్దెనెక్కాడు.","table":null},{"a":"ఢిల్లీకి","e":"","table":null},{"a":"లక్నో","e":"1916లో డిసెంబరు నెలలో అంబికా చరణ్ మజుందార్ అధ్యక్షతన జరిగాయి.","table":null},{"a":"అంబికా చరణ్ మజుందార్","e":"","table":null},{"a":"70 శాతం","e":"హైదరాబాద్ ముస్లిం సంస్థానమైనప్పటికీ అక్కడ దాదాపు 70 శాతం జనాభా హిందువులే.","table":null},{"a":"నిన్ను నేను చూసావు కదా, నాలో ఏ భేదం కనిపిస్తుందని","e":"నిజాం సింహాసనం అధిరోహించగానే సరోజినీనాయుడుతో \"నువ్వు నన్ను, మా నాన్నగారిని చూసావు కదా, మాలో నీకు ఏ భేదం కనిపించింది\" అని ప్రశ్నించాడు.","table":null},{"a":"దేవుడు దివంగతరాజుకు ''దిల్'' ఇచ్చాడు, మీకు ''దిమాగ్'' ఇచ్చాడు","e":"''దిల్'' అంటే ఔదార్యం, ''దిమాగ్'' అంటే బుద్ధి అని అర్థం.","table":null},{"a":"1914","e":"","table":null},{"a":"తన రాజ్యంలో మంత్రివర్గాన్ని రద్దుచేసి పరిపాలనా బాధ్యతలను తానే స్వీకరించాడు","e":"","table":null},{"a":"ప్రభువులకు ఇచ్చే కానుక","e":"నేటి పరిభాషలో నజరానా అంటే లంచం.","table":null},{"a":"అపరిమితంగా ధన సహాయం చేశాడు","e":"తన జనం దగ్గర లంచాలు తీసుకుంటూ బ్రిటిష్ వారికి తాను లంచమిచ్చాడు.","table":null},{"a":"1918","e":"","table":null},{"a":"25 తుపాకీగుళ్ల సైనిక వందనం","e":"ఈ అత్యున్నతమైన గౌరవం పొందిన సంస్థానాధీశుడు నిజాం నవాబు ఒక్కడే.","table":null},{"a":"సర్ అలీ ఇమామ్","e":"","table":null},{"a":"నజరానా పద్ధతి","e":"సమర్థులకే ఉద్యోగాలిచ్చాడు, అధికారులలో లంచగొండితనాన్ని నిర్మూలించడానికి చర్యలు తీసుకున్నాడు.","table":null},{"a":"ఖిలాఫత్ ఉద్యమం","e":"మలబార్‌లోని మాప్లా జాతివారిని రప్పించి పరిశ్రమలు, అభివృద్ధి కార్యక్రమాలు వారికి అప్పగించాడు.","table":null},{"a":"1922 సెప్టెంబర్ 5","e":"ఒప్పందం ప్రకారం నెలకు ఏడేసి వేల రూపాయల చొప్పున రెండు సంవత్సరాల వేతనం ఇమామ్‌కు ముట్టజెప్పారు.","table":null},{"a":"ఫరీదున్ ముల్క్, వలీ ఉద్దౌలా","e":"","table":null},{"a":"బ్రిటిష్ వారు","e":"ఇతడు ఐదేళ్లు ఆ పదవిలో కొనసాగాడు.","table":null},{"a":"సర్ అక్బర్ హైదరీ","e":"ఆయన 1941 వరకు ప్రధానిగా ఉన్నాడు.","table":null},{"a":"1400 ఎకరాలు","e":"","table":null},{"a":"ఉర్దూలో","e":"అత్యున్నత స్థాయిలో అత్యున్నత ప్రమాణాలతో ఉర్దూలో బోధన జరిగింది.","table":null},{"a":"దారుల్ తర్జుమా","e":"దారుల్ తర్జుమా అంటే అనువాద విభాగం.","table":null},{"a":"ఉస్మాన్‌సాగర్, హిమాయత్ సాగర్","e":"","table":null},{"a":"ఏడు లక్షల (7,00,000) ఎకరాలు","e":"","table":null},{"a":"పోలేరు, వైరా, తుంగభద్ర, రాజోలిబండ, కడెం, మూసీ, మానేరు","e":"ఈ ప్రాజెక్టులకు రూపకల్పన చేసిన ఇంజనీరు నవాబు అలీ నవాజ్ జంగ్.","table":null},{"a":"నవాబు అలీ నవాజ్ జంగ్","e":"","table":null},{"a":"ఆసియా ఖండంలోనే పెద్దది","e":"","table":null},{"a":"నిజాం మొగలు చక్రవర్తుల డిజైన్‌ను అనుసరించారు","e":"ఉస్మానియా విశ్వవిద్యాలయం, ఉస్మానియా దవాఖానా, హైకోర్టు, స్టేట్ సెంట్రల్ లైబ్రరీ, అసెంబ్లీ భవనాలు నిజాం కట్టించినవి.","table":null},{"a":"నిజాం గ్యారెంటీడ్ కంపెనీ","e":"","table":null},{"a":"1930","e":"ఆ కంపెనీకి పదికోట్ల రూపాయలు చెల్లించాడు.","table":null},{"a":"నిజాం స్టేట్ రైల్వే (ఎస్.ఎస్.ఆర్.)","e":"","table":null},{"a":"1932","e":"","table":null},{"a":"హైదరాబాద్ సంస్థానం","e":"","table":null},{"a":"82,698 చదరపు మైళ్లు","e":"","table":null},{"a":"59.21 శాతం","e":"","table":null},{"a":"సర్ఫేఖాస్ 8,100 చ.మై, జాగీర్లు 1,100 చ.మై","e":"","table":{"headers":["విభాగం","విస్తీర్ణం (చ.మై)","శాతం"],"rows":[["దివానీ","మిగతాది","59.21"],["సర్ఫేఖాస్","8,100","-"],["జాగీర్లు","1,100","-"]],"unit":"చదరపు మైళ్లు"}},{"a":"50 లక్షల ఎకరాలు, ఆదాయం 3 కోట్లు","e":"","table":null},{"a":"లేదు","e":"పైగా ఈ ఆదాయం కాకుండా నవాబుకు ప్రభుత్వ ఖజానా నుంచి ఏటా యాభై లక్షలు చెల్లించవలసి వచ్చేది.","table":null},{"a":"ఆస్మాన్‌జాకు 30 లక్షలు","e":"ఖుర్షీద్‌జాకు 20 లక్షలు, సర్ వికారుల్ ఉమ్రాకు 15 లక్షల రూపాయల ఆదాయంవచ్చే భూములు లభించాయి.","table":null},{"a":"రైత్వారీ పద్ధతి","e":"","table":null},{"a":"దేశ్‌ముఖ్, దేశ్‌పాండ్యా, ముఖ్తేదారు, బంజర్‌దార్, ఇజారాదార్","e":"","table":null},{"a":"ప్లేటో, అరిస్టాటిల్ వంటి మేధావి","e":"","table":null},{"a":"ఎ-జమాన్, ముజఫర్ ఉల్-ముల్క్, నిజాం ఉద్దౌలా, నిజాం ఉల్ముల్క్","e":"","table":{"headers":["బిరుదు","అర్థం/సందర్భం"],"rows":[["ఎ-జమాన్","-"],["ముజఫర్ ఉల్-ముల్క్","-"],["నవాబు మీర్ ఉస్మాన్ అలీఖాన్ బహదూర్ ఫతేజంగ్","-"],["సిప్పేసాలార్","-"],["లెఫ్టెనెంట్-జనరల్","-"],["ఫెయిత్‌ఫుల్ టు బ్రిటిష్ గవర్నమెంట్","-"],["నిజాం ఉద్దౌలా","-"],["నిజాం ఉల్ముల్క్","-"],["ఏడవ నిజాం","-"]],"unit":"బిరుదులు"}},{"a":"ఆలాహజ్రత్","e":"","table":null},{"a":"14 సంస్థానాలు","e":"గద్వాల, వనపర్తి, జటప్రోలు, అమరచింత, పాల్వంచ సంస్థానాలకు మాత్రమే పాలనాధికారాలు ఉండేవి.","table":null},{"a":"దోమకొండ, గోపాలపేట, ఆనెగొంది, రాజాపేట, దుబ్బాక, నారాయణపేట, పాపన్నపేట, సిర్నాపల్లి, గురుగుంట","e":"ఇవి రాయచూరు జిల్లాలోని సంస్థానాలు, సంస్థానాధీశులు ఇష్టం వచ్చిన విధంగా పన్నులు విధించేవారు.","table":null},{"a":"120 గ్రామాలు, 97 శివారు గ్రామాలు","e":"","table":null},{"a":"విరాళపు పన్ను, నుజుల్, సీసు బంచరాయి, ఆయగాళ్ల పన్ను, ఏనుగు పన్ను","e":"","table":{"headers":["పన్ను పేరు","విధించే విధానం"],"rows":[["విరాళపు పన్ను","కార్తీకమాసం పూజలపేర, మాఘమాసం దానాల పేర రైతులపై; అబ్కారీపై ఒకరూపాయి, మహాసిలిపై 1 అణా 3 పైసలు"],["నుజుల్ (ఇండ్లపన్ను)","ఇంటిస్థలంపై గజానికి అణా, భవనాలపై రూపాయి నుంచి 2 రూపాయల చొప్పున"],["సీసు బంచరాయి","శాలి ఒక్కంటికి 4 పైసలు; ఆవు, ఎద్దు, పడ్డలకు అణా; బర్లకు రెండణాలు; వంద గొర్రెలకు 5 రూ.; వంద మేకలకు 25 రూ."],["ఆయగాళ్ల పన్ను","శేరు మొదలుకొని 5 శేర్ల చొప్పున వడ్ల/జొన్నల వసూలు"],["ఏనుగు పన్ను","ఏనుగులు లేకున్నా సంస్థానం వారి ఎల్లకోసం రైతుల వద్ద వసూలు"]],"unit":"గద్వాల సంస్థాన పన్నులు"}},{"a":"బీరారు","e":"బీరారుపై ఎలాంటి ఆశలు పెట్టుకోవద్దని తెలియజేశాడు, రానున్న వైస్రాయ్‌ల విధానం కూడా అదేనని ఖండితంగా చెప్పాడు.","table":null},{"a":"పోరు మానలేదు","e":"","table":null},{"a":"1926","e":"","table":null},{"a":"నిజాం ఆఫ్ హైదరాబాద్ అండ్ బీరారు","e":"","table":null},{"a":"నిజాం పతాకం","e":"","table":null},{"a":"నిజాంను","e":"","table":null},{"a":"నిజాం","e":"","table":null},{"a":"బీరారులో","e":"","table":null},{"a":"తన ఏజెంట్లను","e":"","table":null},{"a":"ప్రిన్స్ ఆఫ్ బీరారు","e":"","table":null},{"a":"25 లక్షల రూపాయలు","e":"","table":null},{"a":"ఏమీ లేదు","e":"సనదులు, గౌరవాలు తప్ప నిజాంకు కొత్తగా పొందిందేమీ లేదు.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-14-nizam-chapter-5', 'telangana-history-te', 14, 'నిజాం- 5 (సాలార్‌జంగ్ సంస్కరణలు)', '[{"a":"నిజాముల కాలంలో","e":"మొగలాయి పరిపాలనను అంతమొందించి రాష్ట్రంలో నూతన పద్ధతిలో పరిపాలన ప్రారంభించిన ఘనత ఇతనికే దక్కుతుంది.","table":null},{"a":"1857","e":"","table":null},{"a":"తాహుత్తు / సర్బరస్తా","e":"దీనికే బిల్మక్తా అని కూడా పేరు ఉండేది.","table":null},{"a":"దేశముఖ్, దేశపాండ్య, దేశాయి, సర్దేశాయి","e":"","table":null},{"a":"3668 మంది","e":"","table":null},{"a":"60 నుండి 70 శాతం","e":"500 ఎకరాలకు పైబడిన భూస్వాములు ఈ భూమిని తమ చేతుల్లో ఉంచుకున్నారు.","table":null},{"a":"ఇజారా లేక కౌలు పద్ధతి","e":"","table":null},{"a":"1908","e":"","table":null},{"a":"20 సంవత్సరాల నుండి 15కు","e":"","table":null},{"a":"20, 25 రూపాయలు","e":"దుక్కి భూములకంటే ఇది 10, 12 రూపాయలు ఎక్కువ; ఆంధ్రప్రదేశ్ ఏర్పడిన తరువాత ఈ పన్ను రద్దయింది.","table":null},{"a":"1868","e":"","table":null},{"a":"కలెక్టరు","e":"","table":null},{"a":"బోర్డ్ ఆఫ్ రెవిన్యూ","e":"","table":null},{"a":"5 డివిజన్లు, 16 జిల్లాలు, 114 తాలూకాలు","e":"ఈ విభజన బొంబాయి పద్ధతిననుసరించి చేయబడింది, ఇది మద్రాసు పద్ధతికి వ్యతిరేకం.","table":{"headers":["డివిజన్","జిల్లాలు","తాలూకాల సంఖ్య"],"rows":[["ఉత్తర డివిజన్","మెదక్, ఇందూరు (నిజామాబాద్), ఎల్లందల్ (కరీంనగర్)","23"],["తూర్పు డివిజన్","ఖమ్మం, వరంగల్, నల్గొండ, నాగర్ కర్నూలు","26"],["పశ్చిమ డివిజన్","బీదర్, నాందేడ్, నల్దుర్గ్","25"],["దక్షిణ డివిజన్","రాయచూరు, షోలాపూర్, గుల్బర్గా","14"],["వాయవ్య డివిజన్","ఔరంగాబాద్, పర్భణీ","26"]],"unit":"తాలూకాల సంఖ్య"}},{"a":"1846","e":"","table":null},{"a":"నలుగురు","e":"వీరిలో ఒకరు ప్రధాన న్యాయమూర్తి.","table":null},{"a":"దివానీ, ఫౌజ్దారీ కేసులు","e":"","table":null},{"a":"మదరుల్-మొహం","e":"దీని అర్థం ప్రధానమంత్రి.","table":null},{"a":"నలుగురు","e":"","table":null},{"a":"1874","e":"","table":null},{"a":"వైద్యం, మింటు, ముద్రణశాల, పి.డబ్ల్యూ.డి.","e":"","table":null},{"a":"5 శాతం","e":"ఎగుమతి, దిగుమతులపై ఈ డ్యూటీని సాలార్జంగ్ ఆచరణలో పెట్టాడు.","table":null},{"a":"నాణేల మార్పిడి లాభం","e":"పాత సిక్కాలను కొత్త సిక్కాలుగా మార్చడం వల్ల లభించే 10 శాతం లాభాన్ని ప్రభుత్వ ఖజానాలో జమ చేసేవారు.","table":null},{"a":"1883","e":"","table":null},{"a":"1777 నుండి 1802 వరకు","e":"","table":null},{"a":"ఎనిమిదవ భాగం","e":"","table":null},{"a":"22 లక్షలు","e":"","table":null},{"a":"6 లక్షలు","e":"","table":null},{"a":"16వ భాగం","e":"","table":null},{"a":"బ్రిటిష్ రెసిడెంట్ జనరల్ ఫ్రేయిజర్","e":"","table":null},{"a":"14 వేలకు","e":"","table":null},{"a":"హిందువులు 4919, ముస్లింలు 2882","e":"","table":{"headers":["హోదా","హిందువులు","ముస్లింలు"],"rows":[["కార్యాలయ కార్యదర్శులు","37","164"],["రెవిన్యూ సిబ్బంది","2306","347"],["అడవుల శాఖ","25","27"],["కరోడ్గిరి","1300","58"],["ఆబ్కారీ","62","29"],["స్టాంపులు","12","5"],["టంకశాల","15","12"],["తపాలశాఖ","83","118"],["అకౌంటెంట్ జనరల్ కార్యాలయం","141","58"],["న్యాయశాఖ","234","378"],["పోలీసు శాఖ","479","1435"],["విద్యాశాఖ","114","117"],["వైద్యశాఖ","7","26"],["ముద్రణాలయము","10","27"],["పి.డబ్ల్యూ.డి","110","55"],["మునిసిపాలిటీలు","10","35"],["అనువాదశాఖ","2","0"]],"unit":"ఉద్యోగుల సంఖ్య (1885)"}}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-15-modati-swatantra-samaram', 'telangana-history-te', 15, 'మొదటి స్వతంత్ర సమరం', '[{"a":"1857","e":"నవాబ్ అఫ్జలుద్దౌలా సింహాసనం అధిష్టించిన నాలుగు మాసాలకే ఈ సమరం మొదలైంది.","table":null},{"a":"1857","e":"ఇతడు నవాబ్ నసీరుద్దౌలా కుమారుడు.","table":null},{"a":"1849 జనవరి 12","e":"ఇతడు తన 35వ ఏట ఈ పదవి చేపట్టాడు.","table":null},{"a":"మూడు రకాలు","e":"స్వతంత్ర రాజ్యాలు, ఆధార రాజ్యాలు, అధీన రాజ్యాలు అనేవి ఆ మూడు రకాలు.","table":null},{"a":"జాన్‌షిప్ పద్ధతి రద్దు (నిర్వారసత్వ సిద్ధాంతం)","e":"డల్హౌసీ ఈ సిద్ధాంతం ద్వారా అనేక రాజ్యాలను కబళించాడు.","table":null},{"a":"వారసీన్, జాన్‌షిప్","e":"వారసీన్ పద్ధతిలో రాజు కొడుకులకు లేదా సమీప రక్త సంబంధీకులకు రాజ్యం లభించేది, జాన్‌షిప్ పద్ధతిలో దత్తత ద్వారా అధికారం లభించేది.","table":null},{"a":"బర్మా, సిక్కిం, పంజాబ్","e":"ఇవి స్వతంత్ర రాజ్యాలుగా ఉన్నవి.","table":null},{"a":"అయోధ్య","e":"ఇది అధీన రాజ్యాలలో ఒకటి.","table":null},{"a":"కర్నాటక, తంజావూరు","e":"వీరి పింఛన్లు రద్దయ్యాయి.","table":null},{"a":"1856 మార్చి 5","e":"ఇతడు హృదయ భారంతో వెళ్ళిపోయాడు.","table":null},{"a":"1866 డిసెంబరు 19","e":"ఇతడు అతిదీనావస్థలో మరణించాడు.","table":null},{"a":"క్రిస్సన్","e":"ఇతను రష్యా చరిత్రకారుడు.","table":null},{"a":"1858","e":"ఝాన్సీ రాష్ట్రం అప్పటికి పీష్వాల పాలనలో ఉండేది.","table":null},{"a":"సంతానం లేనందున దత్తతను ఆమోదించలేదు","e":"గంగాధరరావు భార్య ఝాన్సీ లక్ష్మీబాయి పెట్టుకున్న దరఖాస్తును డల్హౌసీ తిరస్కరించాడు.","table":null},{"a":"మహమ్మద్‌గార్","e":"అతని వారసునికి పింఛను అర్హత లేదని ఉత్తర్వులు వచ్చాయి.","table":null},{"a":"1851","e":"ఇతను పీష్వా.","table":null},{"a":"8 లక్షల రూపాయలు","e":"బాజీరావు జీవించి ఉండగా ఈ పింఛను ఏర్పాటు చేశారు.","table":null},{"a":"నానాసాహెబ్","e":"దత్తపుత్రుడైన నానాసాహెబ్‌కు పింఛను వర్తించదని బ్రిటిష్ వారు ఆపుచేశారు.","table":null},{"a":"1851","e":"మరణానికి ముందు తన రెండవ కూతుర్ని వారసురాలిగా ప్రకటించాడు.","table":null},{"a":"స్త్రీలకు తండ్రివైపు ఆస్తిపై అర్హత లేదని","e":"రాజు కూతురిని వారసురాలిగా ప్రకటించినా బ్రిటిష్ వారు అంగీకరించలేదు.","table":null},{"a":"మీరట్","e":"అక్కడి నుంచి ఈ జ్వాలలు హైదరాబాద్ చేరుకోవడానికి సమయం పట్టింది.","table":null},{"a":"తంతి ద్వారా","e":"ఐదవ నిజాం అఫ్జలుద్దౌలా పట్టాభిషేకోత్సవంలో పాల్గొన్న సమయంలో ఈ వార్త తెలిసింది.","table":null},{"a":"సాలార్ జంగ్","e":"ఇతను విప్లవకారులను అణచివేయడంలో బ్రిటిష్ వారికి సహాయపడ్డాడు.","table":null},{"a":"1857 జూన్","e":"మూడు అశ్విక దళాలను ఔరంగాబాద్ మీదుగా పంపారు.","table":null},{"a":"వెయ్యి రూపాయలు","e":"వీరు తిరుగుబాటుకు నాయకత్వం వహించారు.","table":null},{"a":"చీదాఖాన్","e":"ఇతన్ని పట్టి ఇచ్చినవారికి 3 వేల రూపాయల బహుమతి ప్రకటించారు.","table":null},{"a":"తుర్రేబాజ్‌ఖాన్","e":"ఇతను రెసిడెన్సీపై దాడికి నాయకత్వం వహించాడు.","table":null},{"a":"1857 జూలై 17","e":"500 మంది రోహిల్లా వీరులతో ఈ దాడి జరిగింది.","table":null},{"a":"32 మంది","e":"సాలార్ జంగ్ పంపిన అశ్విక దళాలు వీరిపై మెరుపుదాడి చేశాయి.","table":null},{"a":"మౌల్వీ అల్లాఉద్దీన్","e":"వీరిద్దరిని బంధించి దీవ్యాంతరవాస శిక్ష విధించారు.","table":null},{"a":"1884, అండమాన్ దీవులు","e":"ఇతడు ఖైదీగా ఉంటూ మరణించాడు.","table":null},{"a":"సాలార్ జంగ్ సైనికులు","e":"తుర్రేబాజ్‌ఖాన్ శవాన్ని రెసిడెన్సీ ప్రధాన ద్వారానికి వేలాడతీశారు.","table":null},{"a":"1861","e":"విప్లవాన్ని అణచివేయడంలో సహాయం చేసినందుకు బ్రిటిష్ ప్రభుత్వం కృతజ్ఞతతో ఈ బిరుదు ఇచ్చింది.","table":null},{"a":"జహంగీర్‌ఖాన్","e":"ఇతని కాల్పు గురితప్పి పక్కనున్న నిజాం అధికారికి తగిలింది.","table":null},{"a":"50 లక్షలు","e":"ఇది నిజాంకు బ్రిటిష్ వారు చూపిన కృతజ్ఞతలో భాగం.","table":null},{"a":"షమ్షుల్ ఉమ్రా","e":"1877లో అతను చనిపోతే వికారుల్ ఉమ్రాను నియమించారు.","table":null},{"a":"పోలాపూర్ సంస్థానాధీశుడు","e":"తర్వాత ఆ సంస్థానాన్ని తిరిగి నిజాంకు ఇచ్చివేశారు.","table":null},{"a":"నియాజ్‌మంద్, మాబ్‌దౌలత్","e":"గవర్నర్-జనరల్‌ను నియాజ్‌మంద్ (విన్నవించు విధేయుడు) అని, నిజాంను మాబ్‌దౌలత్ (దేవరవారు) అని పిలిచేవారు.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-16-paripalana-vyavastha', 'telangana-history-te', 16, 'పరిపాలనా వ్యవస్థ', '[{"a":"బాబ్-ఎ-హుకుమత్","e":"ఇది రాష్ట్ర పరిపాలన కోసం ఏర్పాటైన కార్యనిర్వాహక సభ.","table":null},{"a":"సదరె-ఎ-ఆజమ్","e":"ఇతన్ని ప్రధానమంత్రి అని కూడా అనేవారు.","table":null},{"a":"9","e":"మొదట 7గురు మంత్రులు ఉండేవారు.","table":null},{"a":"5 వేలు","e":"దీనితోపాటు నూరు రూపాయల అలవెన్స్ కూడా లభించేది.","table":null},{"a":"4 వేల రూపాయలు","e":"ఇది కల్దారు సిక్కాలో వేతనం.","table":null},{"a":"సర్ ఎం. విశ్వేశ్వరయ్య","e":"దేశంలోని నలుమూలల నుంచి నిపుణులైనవారిని నిజాం రప్పించేవాడు.","table":null},{"a":"ఉస్మాన్ అలీఖాన్","e":"ఇతను ఐదవ నిజాం.","table":null},{"a":"జాబితె-అక్లాక్","e":"ఇందులోని రెండు ఫర్మానాలు పరిపాలనా క్రమశిక్షణను తెలియజేస్తాయి.","table":null},{"a":"పాలమూరు","e":"పాలమూరు అనే పెద్ద గ్రామాన్ని అనుకుని ఈ జిల్లా కేంద్రం ఏర్పడింది.","table":null},{"a":"మహబూబ్ అలీఖాన్","e":"ఇతను ఆరవ నిజాం.","table":null},{"a":"మహబూబాబాద్","e":"పూర్వం దీని పేరు మానుకోట.","table":null},{"a":"పోచంచర్ల","e":"కరీంనగర్ సమీపంలోని ఎలగందల గ్రామానికి చారిత్రక ప్రాధాన్యత ఉంది.","table":null},{"a":"యలగందల నారయ","e":"ఇతను ఎలగందల గ్రామవాసి అని ఒక అభిప్రాయం ఉంది.","table":null},{"a":"నిజామాబాద్","e":"పూర్వం ఇందూరు అనే పెద్ద గ్రామం ఉండేది.","table":null},{"a":"అసిఫాబాద్","e":"దీని అసలు పేరు జనగామ.","table":null},{"a":"జిల్లా జనగామ","e":"ఈ చిన్న పట్టణాన్ని ప్రజలు ఇటీవలి దాకా ఈ పేరుతో పిలిచేవారు.","table":null},{"a":"పాడు (పల్లె అని అర్థం)","e":"దీనిని కొన్నిచోట్ల పహాడ్‌గా మార్చారు.","table":null},{"a":"బూర్గంపహాడ్","e":"పహాడ్ అనే పదానికి కొండ అని అర్థం.","table":null},{"a":"ఉస్మాన్‌సాగర్, హిమాయత్ సాగర్","e":"ఇవి రూపుదిద్దుకున్నవే ఈనాడు హైదరాబాద్‌కు మంచినీటిని అందిస్తున్నాయి.","table":null},{"a":"భూగర్భ మురుగు నీటి పారుదల పథకం","e":"ఇది ఆధునిక హైదరాబాద్ నగర నిర్మాణానికి పునాదులు వేసింది.","table":null},{"a":"హైదరాబాద్","e":"హైదరాబాద్ సంస్థానానికి మాత్రమే ప్రత్యేక కరెన్సీలు చెలామణిలో ఉండేవి.","table":null},{"a":"83 రూపాయల 5 అణాల 3 పైసలు","e":"ఇది కల్దారు మారకం రేటు.","table":null},{"a":"1894","e":"అంతకుముందు 1883 వరకు చేతితోనే నాణేలు తయారు చేసేవారు.","table":null},{"a":"172.5 గ్రెయిన్లు","e":"ఈ నాణెం ఉస్మానియా సిక్కా ఆకారంలోను, సైజులోను ఉండేది.","table":null},{"a":"1905","e":"చార్మినార్‌లో ప్రధానమైన కమానుభాగంలో అప్పటి పరిపాలకుని పేరులోని మొదటి అక్షరం ఎం అని చేర్చారు.","table":null},{"a":"మొదటి అక్షరం ''మీం'' వల్ల","e":"ఉస్మాన్ అలీఖాన్ పరిపాలన రాగానే ''మీం'' అక్షరం స్థానంలో ''అయిన్'' అనే అక్షరం మార్చారు.","table":null},{"a":"1918","e":"1939 వరకు ఈ నోట్లు ఇంగ్లీషులో అచ్చువేయాలని ప్రభుత్వం నిర్ణయించింది.","table":null},{"a":"నాసిక్","e":"సెక్యూరిటీ ప్రింటింగ్ ప్రెస్‌లో నోట్లు అచ్చువేయటానికి ఏర్పాట్లు చేశారు.","table":null},{"a":"5, 10 రూపాయలు","e":"తరువాత సంవత్సరం నూరు రూపాయల నోటు, రెండేళ్లకు వేయి రూపాయల నోటు వచ్చాయి.","table":null},{"a":"1943","e":"ఈ రూపాయి నోటు అజమాయిషీలో నెంబరింగ పనులు జరిగాయి.","table":null},{"a":"1955 ఏప్రిల్ 1","e":"ఇదే హాలీసిక్కా రద్దయిన తేదీ.","table":null},{"a":"52 వేలమంది","e":"ఈ ఆరు పెద్ద బట్టల మిల్లుల్లో వీరు పనిచేసేవారు.","table":null},{"a":"బొగ్గు","e":"సింగరేణి గనులు మాత్రమే ఈ ఖనిజ నిక్షేపాలకు ప్రసిద్ధి.","table":null},{"a":"వెయ్యి ఔన్సులు","e":"ఇది హట్టి బంగారు గనుల ఉత్పత్తి.","table":null},{"a":"1928","e":"ఇది బేగంపేటలో ఏర్పాటైంది.","table":null},{"a":"వజీర్ సుల్తాన్ అండ్ కో సిగరెటు ఫ్యాక్టరీ","e":"ఈ ఫ్యాక్టరీ సిగరెట్ల ఉత్పత్తి చేసింది.","table":null},{"a":"ప్రధాన న్యాయమూర్తి (మూడువేలు, అంతకు ఎక్కువ వేతనం)","e":"ఉద్యోగులను వేతన శ్రేణుల ప్రకారం నాలుగు తరగతులుగా వర్గీకరించారు.","table":{"headers":["మూడువేలు అంతకు ఎక్కువ","2,500 వేతనం","2,250 వేతనం","2,000 వేతనం"],"rows":[["ప్రధాన న్యాయమూర్తి","అకౌంటెంట్ జనరల్","కార్యదర్శి","జాయింట్ సెక్రటరి"],["జుడిషియల్ కమిటీ సభ్యులు","ఐ.జి.పి","సూబేదార్లు","సెక్రటరీలు"],["అసెంబ్లీ చైర్మన్","వైస్‌చాన్సలర్, పబ్లిక్ సర్వీస్ కమీషన్ సభ్యులు, హైకోర్టు న్యాయమూర్తులు, సెక్రటరీ కో ఆర్డినేషన్","చీఫ్ ఇంజనీర్, ఎక్సైజ్ సూపరింటెండెంట్, కన్జర్వేటర్ ఆఫ్ ఫారెస్ట్స్, ఆదాయపు పన్ను, విద్య, వైద్య శాఖల డైరెక్టర్లు","డైరెక్టర్లు"]],"unit":"వేతన శ్రేణి (కల్దారు రూపాయలు)"}}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-17-andhra-janasangham-mahasabhalu', 'telangana-history-te', 17, 'ఆంధ్ర జనసంఘం & మహాసభలు', '[{"a":"1921 నవంబరు 12","e":"హైదరాబాద్‌లోని వివేకవర్ధనీ థియేటర్‌లో జరిగిన హిందూ సంస్కార సభలో జరిగిన అవమానం తర్వాత ఈ సంఘం ఏర్పడింది.","table":null},{"a":"ధోండే కేశవ్ కార్వే","e":"","table":null},{"a":"మాడపాటి హనుమంతరావు, ఆలంపల్లి వెంకటరామారావు","e":"ఇద్దరూ హైకోర్టు న్యాయవాదులు.","table":null},{"a":"సంఘం స్థాపనకు నిర్ణయం","e":"ఆ రాత్రికి రాత్రి తేకుమాల రంగారావు గారింట్లో సమావేశమై ఆంధ్రుల అభిమాన సంరక్షణ కోసం సంఘం స్థాపించాలని నిశ్చయించుకున్నారు.","table":null},{"a":"నిజాంరాష్ట్ర ఆంధ్రజన కేంద్ర సంఘం","e":"","table":null},{"a":"రావు బహద్దూర్ శ్యామలరెడ్డి","e":"","table":null},{"a":"మాడపాటి హనుమంతరావు","e":"","table":null},{"a":"తేకుమళ్ల రంగారావు తదితరులు","e":"మొత్తం 11 మంది ప్రముఖులు ఈ సంఘాన్ని స్థాపించారు.","table":null},{"a":"1923 జూలై 27, హైదరాబాద్","e":"మాడపాటి హనుమంతరావు నివాసగృహంలో జరిగింది.","table":null},{"a":"రాజా బహద్దూర్ వెంకటరామారెడ్డి","e":"","table":null},{"a":"గ్రంథాలయాలు స్థాపించాలి","e":"గ్రంథాలయాలు, పఠన మందిరాలు, పాఠశాలలు స్థాపించడంతో పాటు విద్యార్థులకు సహాయం, భాషాభివృద్ధి, అనాథలకు సహాయం వంటి ఆశయాలు కూడా నిర్దేశించారు.","table":null},{"a":"1924 మార్చి 21","e":"","table":null},{"a":"నిజాం రాష్ట్ర ఆంధ్రనిధి","e":"నిజాం రాష్ట్రంలో ఆంధ్రోద్యమ వ్యాప్తి కోసం ఈ నిధిని ఏర్పాటు చేయాలని నిర్ణయించారు.","table":null},{"a":"లక్ష్మణరాయ పరిశోధక మండలి","e":"దీనిని ''ఆంధ్ర పరిశోధక మండలి''గా మార్చాలని నిర్ణయించారు.","table":null},{"a":"బంగారు, వెండి పతకాలు","e":"హెచ్.ఎస్.ఎస్.సి. ఉస్మానియా విశ్వవిద్యాలయం నిర్వహించిన పరీక్షల్లో విజేతలకు ఈ పతకాలు ఇవ్వాలని నిర్ణయించారు.","table":null},{"a":"1925 ఫిబ్రవరి 21, వరంగల్లు జిల్లా","e":"పింగళి వెంకటరామారెడ్డి కార్యాగారపు ఆవరణలో జరిగింది.","table":null},{"a":"ప్రొఫెసర్ శిరుగూరి హనుమంతరావు","e":"","table":null},{"a":"ఆదిరాజు వీరభద్రరావు","e":"","table":null},{"a":"25 రూపాయలు","e":"","table":null},{"a":"1928 మే 28, 29, 30, సూర్యాపేట","e":"","table":null},{"a":"కోదాటి రామకృష్ణారావు","e":"","table":null},{"a":"బీడీలు, సిగరెట్లు","e":"సభాస్థానంలో చుట్టలు, బీడీలు, సిగరెట్లు తాగరాదని, నిషేధ వస్తువులు సేవించరాదని నియమం విధించారు.","table":null},{"a":"50","e":"","table":null},{"a":"90","e":"","table":null},{"a":"తెలంగీ బెధంగీ","e":"తెలుగు భాషకు ఒక క్రమ పద్ధతి లేదని అర్థంలో ఈ మాటతో అపహసించేవారు.","table":null},{"a":"శ్రీకృష్ణదేవరాయ, రాజరాజనరేంద్ర, వేమన ఆంధ్ర భాషానిలయాలు","e":"","table":null},{"a":"వెంకటరామయ్య","e":"","table":null},{"a":"ఆంధ్ర మహాసభ","e":"హైదరాబాద్ రాష్ట్రంలో కాంగ్రెస్ సంస్థ ఆవిర్భావానికి ఆంధ్ర మహాసభ మూలవ్యవస్థగా పనిచేసింది.","table":null},{"a":"నాన్‌ముల్కీ కాకూడదు","e":"సభాధ్యక్షుడు హైదరాబాద్ రాష్ట్ర నివాసి అయి ఉండాలని ప్రభుత్వం షరతు విధించింది.","table":null},{"a":"రాజకీయ ప్రస్తక్తి ఉండకూడదు","e":"సభలో ఇతర మతస్థులకు అవమానం కలిగే విషయాలు కూడా ఉండరాదని షరతు పెట్టారు.","table":null},{"a":"1930, జోగిపేట","e":"మెదక్ జిల్లా అందోలు తాలూకాలోని జోగిపేటలో ఆంధ్రోద్యమం రెండవదశ ప్రారంభమైంది.","table":null},{"a":"జోగిపేట వర్తకులు","e":"","table":null},{"a":"ప్రధాన స్థలం","e":"జోగిపేట హైదరాబాద్ నుండి శంకరపల్లి స్టేషను నుండి 28 మైళ్ళ దూరంలో ఉంది.","table":null},{"a":"కాకతీయ ప్రతాపరుద్ర చక్రవర్తి కాలం నాటి ''తేకుంబెడ్డ'' శాసనాలు","e":"ఈ పేరు తరువాత నిజాం పాలనలో ఉర్దూ ఉచ్చారణలో తేకుంబెడ్డ-తేకుమాలగా రూపాంతరం చెందింది.","table":null},{"a":"''తిర్సన్''","e":"ఈ జి.వో.కు లోబడి సభ జరుపుటకు ప్రభుత్వం అనుమతించింది.","table":null},{"a":"సురవరం ప్రతాపరెడ్డి","e":"బి.ఎ., బి.ఎల్. పట్టభద్రుడు, గోల్కొండ పత్రిక సంపాదకుడు, బహుగ్రంథకర్త, తెలంగాణ ప్రజల వైతాళికుడు.","table":null},{"a":"''ఆంధ్రదేశపు మట్టి అది మాకు కనకము''","e":"''మేము ఆంధ్రులము, ఆంధ్రుల చరిత్ర, సంస్కృతి, నాగరికత మాకు గర్వకారణమైనవి'' అనే భావాన్ని ఏదోవిధంగా కలుగజేయడమే మొదటి దశలో ముఖ్య దృక్పథంగా ఉండేది.","table":null},{"a":"చీటికి మాటికి కలహించుకుంటూ కోర్టుకు వెళ్లడం","e":"","table":null},{"a":"స్త్రీల పరదా పద్ధతి","e":"","table":null},{"a":"గస్తీ నిషాన్ 53","e":"బహిరంగ సభల విషయంలో వ్యక్తి స్వేచ్ఛకు ఆటంకం ఉందని దీనిని రద్దు చేయాలని మహాసభ కోరింది.","table":null},{"a":"మద్యపాన దురభ్యాసం","e":"","table":null},{"a":"నడింపల్లి సుందరమ్మ","e":"","table":null},{"a":"వివాహ సమస్య, పాతివ్రత్యము, కళావంతులు, వితంతువుల స్థితి","e":"ప్రాచీన స్త్రీల జ్ఞానము, నేటి హీన స్థితి కూడా చర్చకు వచ్చాయి.","table":null},{"a":"1931 మార్చి 3,4,5, దేవరకొండ","e":"","table":null},{"a":"బూర్గుల రామకృష్ణారావు","e":"","table":null},{"a":"పుల్లమరాజువారు","e":"పూణేలో న్యాయవాద విద్య చదువుకునే రోజుల్లో మహారాష్ట్రుల సంప్రదాయం ప్రకారం ఆ పేరు ''రాంకిషన్‌రావు బూర్గుల్'' అయింది.","table":null},{"a":"మహబూబ్‌నగర్ జిల్లా, పాడ్ నగర్ తాలూకా, బూర్గుల గ్రామం","e":"","table":null},{"a":"దక్కనుకు ప్రథమాంధ్ర ముఖ్యమంత్రి","e":"","table":null},{"a":"ప్రథమాంధ్ర మహాసభకు హాజరైన వ్యక్తి","e":"ఆయన మత, సాంఘిక విషయాలలో కొంచెం సనాతనుడు, గుంటూరులోని శారద నికేతన్‌కు ధనసహాయం చేశాడు.","table":null},{"a":"కేశవరావు","e":"వామన్‌నాయక్ సనాతన ప్రభావం వలన ఆయన ప్రయత్నం ఫలించలేదు.","table":null},{"a":"శ్రీమతి టి. వరలక్ష్మమ్మ","e":"","table":null},{"a":"మాతృభాష ద్వారా","e":"","table":null},{"a":"మూడు సంవత్సరాలు","e":"దీనికి కారణం ప్రభుత్వ అనుమతిలో జాప్యం.","table":null},{"a":"జట్‌ప్రోలు సంస్థానం, పెంట్లవల్లి గ్రామం","e":"మహబూబ్‌నగర్ జిల్లా జట్‌ప్రోలు సంస్థానంలో మూడవ సభ జరపాలని పెంట్లవల్లి గ్రామంలోని ప్రముఖ వకీలు చక్రపాణి నరసరాజు ప్రయత్నాలు ప్రారంభించారు.","table":null},{"a":"జట్‌ప్రోలు ఒక సంస్థానం కావడం వలన","e":"సంస్థాన ప్రభుత్వాన్ని కోరితే ఆ అధికారం తమకు లేదని, నిజాం ప్రభుత్వం నుండి పొందాలని లిఖితపూర్వకంగా తెలియజేశారు.","table":null},{"a":"ప్రధానమంత్రి మహారాజా సర్ కిషన్ పర్షాద్ బహాదుర్","e":"","table":null},{"a":"కర్నల్ ట్రెంచ్","e":"ఆరు మాసాలకు ముందుగా తెలియజేయాలని కోరాడు.","table":null},{"a":"కేవలం రాజకీయేతరము","e":"గ్రంథాలయాలకు సంబంధించినది, విజ్ఞాన వ్యాప్తికి సంబంధించినదని వాదించారు.","table":null},{"a":"నల్లగొండ, పులిజాల రంగారావు అధ్యక్షతన","e":"","table":null},{"a":"రాజకీయ, సాంఘిక విషయాలు","e":"దీనితో మహాసభ రైతు సమస్యల మీద తీర్మానాలు ఆమోదించింది.","table":null},{"a":"రైతు","e":"","table":null},{"a":"ఎల్లాప్రగడ సీతాకుమారి","e":"","table":null},{"a":"1935 జనవరి 26,27,28, సిరిసిల్ల","e":"కరీంనగర్ జిల్లా సిరిసిల్లలో మాడపాటి హనుమంతరావు అధ్యక్షతన జరిగింది.","table":null},{"a":"మాడపాటి మాణిక్యాంబ","e":"ఆమె మాడపాటి హనుమంతరావు సతీమణి.","table":null},{"a":"తెలుగులోనే మాట్లాడటానికి","e":"","table":null},{"a":"నియమావళి","e":"ఇంతకు ముందు మహాసభకు ఒక నియమావళి ఈ సభలోనే రూపొందించబడింది.","table":null},{"a":"12","e":"విద్యాపునర్నిర్మాణం, నిర్బంధ ప్రాథమిక విద్య, బాల్యవివాహాల నిరసన, జాగీరు ప్రజల హక్కులు వంటి అంశాలపై మార్పులు తెచ్చే తీర్మానాలు ఆమోదించారు.","table":null},{"a":"అలియావర్ జంగ్","e":"ప్రభుత్వ ప్రచురణల శాఖ అధ్యక్షుడైన ఆయనతో మాట్లాడిన సందర్భంలో ఆంధ్రోద్యమం ఉద్దేశం రాజ్యంలోని ఆంధ్ర జిల్లాలను మద్రాసులోని ఆంధ్ర జిల్లాలతో కలపడమేనని ప్రభుత్వానికి తప్పుడు అభిప్రాయం ఏర్పడింది.","table":null},{"a":"1936, షాద్‌నగర్","e":"","table":null},{"a":"కొండా వెంకటరంగారెడ్డి","e":"","table":null},{"a":"కిషన్ ప్రసాద్ బహదూర్ జాగీరు","e":"ఇంతవరకు జరిగిన నాలుగు సభలు జాగీర్లలోగానీ, సంస్థానాలలోగానీ, పాయిగాలలోగానీ జరుగలేదు; ఇదే మొదటిసారి.","table":null},{"a":"మంత్రి పదవి, ఆంధ్రప్రదేశ్ ఉపముఖ్యమంత్రి పదవి","e":"స్వరాజ్యానంతరం మంత్రిపదవిని, ఆంధ్రప్రదేశ్ ఉపముఖ్యమంత్రిపదవిని అలంకరించాడు; తరువాత ఆయన పేరున ''రంగారెడ్డి జిల్లా'' ఏర్పడింది.","table":null},{"a":"లేరు","e":"కొండా వెంకటరంగారెడ్డి ఎన్నికయ్యే ముందు హైదరాబాద్ శాసన సభలో ఆంధ్రుడనే వాడు లేడు.","table":null},{"a":"వల్లూరి బసవరాజు","e":"","table":null},{"a":"హైదరాబాద్‌లో ఇంజనీరింగు వృత్తిలో స్థిరపడ్డవాడు","e":"ఇదే ఆయన మొదటిసారి ఆంధ్ర మహాసభలకు రావడం; నాటి యౌవనంలో ఉన్నాడు.","table":null},{"a":"బూర్గుల అనంత లక్ష్మీదేవి","e":"","table":null},{"a":"మతాంతరీకరణ ఉద్యమం","e":"","table":null},{"a":"ప్రజల మాతృభాష ద్వారా","e":"","table":null},{"a":"మద్యపాన నిషేధం","e":"","table":null},{"a":"1935, నిజామాబాద్","e":"","table":null},{"a":"మందుముల నరసింగరావు","e":"","table":null},{"a":"''రయ్యత్''","e":"ఇది ఉర్దూలో విశిష్టమైన శైలిగల దినపత్రిక, ఆంధ్రోద్యమానికి ఎంతో సేవ చేసింది.","table":null},{"a":"రైతు సమస్యలు","e":"","table":null},{"a":"రామకృష్ణారావు ప్రభుత్వంలో ల్యాండ్ కమీషన్ అధ్యక్షుడు","e":"ఆంధ్రప్రదేశ్ ఏర్పడిన తరువాత మంత్రి అయ్యాడు.","table":null},{"a":"బ్రిటిష్ ఇండియా పద్ధతిలో","e":"","table":null},{"a":"ఆంధ్రప్రజల ఆశలు, ఆశయాలు బహిర్గతమయ్యాయి","e":"రాష్ట్రంలో రాజకీయంగా తొలికోడి కూసింది ఈ ఆంధ్ర మహాసభ వేదిక మీదనే.","table":null},{"a":"1938, మల్కాపురం","e":"","table":null},{"a":"మందుముల రామచంద్రరావు","e":"","table":null},{"a":"ఎకరానికి 15 నుండి 22 రూపాయల వరకు పన్ను","e":"బ్రిటిష్ ఇండియాలో ఇది 5 నుండి 10 రూపాయల వరకు మాత్రమే ఉండేది.","table":null},{"a":"నూటికి 25 వంతుల పన్ను","e":"","table":null},{"a":"40 లక్షలు","e":"సర్వైఖాస్ ప్రాంతానికి 42 లక్షలు మాఫీ ఇచ్చారని సభ తెలిపింది.","table":null},{"a":"దివానీ-సర్వైఖాస్ ఉద్యోగుల మధ్య వ్యత్యాసం","e":"","table":null},{"a":"1941, చిల్కూరు","e":"నల్లగొండ జిల్లా హుజూర్‌నగర్ తాలూకాలోని చిల్కూరు గ్రామంలో జరిగింది.","table":null},{"a":"రావి నారాయణరెడ్డి","e":"","table":null},{"a":"ప్రథమ సత్యాగ్రహులలో ఒకరు","e":"స్టేటు కాంగ్రెస్‌లోని సోషలిస్టు భావాలుగల యువనాయకుడుగా రాజకీయ రంగమెక్కారు.","table":null},{"a":"నాలుగు అణాలు","e":"ఇంతకుముందు సభ్యత్వ రుసుము రూపాయి నుండి నాలుగు అణాలకు తగ్గించారు.","table":null},{"a":"కమ్యూనిస్టు కార్యక్రమాలు","e":"","table":null},{"a":"రంగమ్మ ఒబులరెడ్డి","e":"","table":null},{"a":"1942, ధర్మవరం","e":"","table":null},{"a":"మాదిరాజు రామకోటీశ్వరరావు","e":"","table":null},{"a":"కమ్యూనిస్టులు, కమ్యూనిస్టేతరులు","e":"ప్రపంచయుద్ధంపై భిన్న ధోరణులలో వాదించారు.","table":null},{"a":"జాతీయపతాక ఉద్యమం","e":"","table":null},{"a":"రంగమ్మ ఒబులరెడ్డి","e":"ఈసారి కూడా రంగమ్మ ఒబులరెడ్డియే అధ్యక్షత వహించారు.","table":null},{"a":"చివరిది","e":"","table":null},{"a":"కాంగ్రెస్, కమ్యూనిస్టు, మితవాదులు","e":"కాంగ్రెస్ మొదటిది, కమ్యూనిస్టు రెండవది, మితవాదులు మూడవది.","table":null},{"a":"వర్గ విభేదాలు","e":"భూస్వామ్య ప్రతినిధులైన మితవాదులు ఒకవైపు, రైతాంగ ప్రయోజనాలకై పోరాడే కమ్యూనిస్టులు మరోవైపు సంఘర్షణ పడసాగారు.","table":null},{"a":"1943 మే 23,24,25, హైదరాబాద్","e":"ఇది రాజధాని నగరంలో జరిగిన మహాసభ.","table":null},{"a":"రెడ్డి హాస్టల్","e":"","table":null},{"a":"కొండా వెంకటరంగారెడ్డి, బద్దం ఎల్లారెడ్డి","e":"మితవాది కొండా వెంకటరంగారెడ్డి గెలిచారు.","table":null},{"a":"బద్దం ఎల్లారెడ్డి, ఆరుట్ల లక్ష్మీనరసింహారెడ్డి, రావి నారాయణరెడ్డి","e":"వీరికి మంచి కమ్యూనిస్టులని పేరుండేది.","table":null},{"a":"హైదరాబాద్ సంస్థానంలో బాధ్యతాయుత ప్రభుత్వం ఏర్పాటు","e":"దీనిని భారతదేశ రాజకీయాలలో ముఖ్య ఘట్టమని చెప్పాలి.","table":null},{"a":"1942","e":"","table":null},{"a":"1944 మే 27,28, భువనగిరి","e":"","table":null},{"a":"రావి నారాయణరెడ్డి","e":"","table":null},{"a":"చీలిక ప్రభావం","e":"","table":null},{"a":"ఒక అణా","e":"నాలుగు అణాల నుండి ఒక అణాకు తగ్గించారు.","table":null},{"a":"1945 మార్చి 21,22,23, మడికొండ","e":"వరంగల్ జిల్లా మడికొండలో జరిగింది.","table":null},{"a":"మాదిరాజు రామకోటీశ్వరరావు","e":"","table":null},{"a":"కొండా వెంకటరంగారెడ్డి","e":"","table":null},{"a":"1946 మే 10,11,12, కంది","e":"మెదక్ జిల్లా కందిలో సర్దార్ జమలాపురం కేశవరావు అధ్యక్షతన జరిగింది.","table":null},{"a":"స్టేటు కాంగ్రెస్ సత్యాగ్రహం","e":"గొప్ప జాతీయవాది; ఆయన తరువాత ఖమ్మం జిల్లా కాంగ్రెస్‌కు అంతటి పటిష్టమైన నాయకుడు మరొకరు లభించలేదు.","table":null},{"a":"చివరి సమావేశం","e":"మొదటి సమావేశం మెదక్ జిల్లా జోగిపేటలో జరగగా, దీని చివరి సమావేశం కూడా మెదక్ జిల్లా కందిలోనే జరిగింది.","table":null},{"a":"విప్లవోద్యమంగా","e":"పరిమితమైన సాంస్కృతికోద్యమంగా ప్రారంభమై క్రమంగా విప్లవోద్యమంగా మారింది.","table":null},{"a":"కాంగ్రెస్ పార్టీ, కమ్యూనిస్టు పార్టీ","e":"మితవాదులు కాంగ్రెస్ పార్టీలో, అతివాదులు కమ్యూనిస్టు పార్టీలో చేరిపోయారు.","table":null},{"a":"జోగిపేట (1930) నుండి కంది (1946) వరకు","e":"మొత్తం 13 మహాసభలు జరిగాయి; ఇవి తెలంగాణ ఆంధ్రులకు ప్రాతినిధ్యం వహించిన పెద్ద సంస్థ.","table":{"headers":["సంఖ్య","సంవత్సరం","ప్రదేశము","అధ్యక్షులు"],"rows":[["1","1930","జోగిపేట","సురవరం ప్రతాపరెడ్డి"],["2","1931","దేవరకొండ","బూర్గుల రామకృష్ణారావు"],["3","1934","నల్లగొండ","పులిజాల రంగారావు"],["4","1935","సిరిసిల్ల","మాడపాటి హనుమంతరావు"],["5","1936","షాద్‌నగర్","కొండా వెంకటరంగారెడ్డి"],["6","1937","నిజామాబాద్","మందుముల నరసింగరావు"],["7","1940","మల్కాపురం","మందుముల రామచంద్రరావు"],["8","1941","చిల్కూరు","రావి నారాయణరెడ్డి"],["9","1942","ధర్మవరం","మాదిరాజు రామకోటీశ్వరరావు"],["10","1943","హైదరాబాద్","కొండా వెంకటరంగారెడ్డి"],["11","1944","భువనగిరి","రావి నారాయణరెడ్డి"],["12","1945","మడికొండ","మందుముల నరసింగరావు"],["13","1946","కంది","జమలాపురం కేశవరావు"]],"unit":"మహాసభల వివరాలు"}},{"a":"రంగమ్మ ఒబులరెడ్డి, ఎల్లాప్రగడ సీతాకుమారి","e":"ఈ ఇద్దరూ మహిళా మహాసభలకు రెండేసి పర్యాయాలు అధ్యక్షత వహించారు.","table":{"headers":["క్రమసంఖ్య","మహిళా మహాసభ అధ్యక్షురాలు"],"rows":[["1","నడింపల్లి సుందరమ్మ"],["2","టి. వరలక్ష్మమ్మ"],["3","ఎల్లాప్రగడ సీతాకుమారి"],["4","మాడపాటి మాణిక్యాంబ"],["5","బూర్గుల అనంతలక్ష్మీదేవి"],["6","నందగిరి ఇందిరాదేవి"],["7","యోగ్యశీలాదేవి"],["8","రంగమ్మ ఒబులరెడ్డి"],["9","రంగమ్మ ఒబులరెడ్డి"],["10","ఎల్లాప్రగడ సీతాకుమారి"]],"unit":"మహిళా మహాసభల అధ్యక్షురాండ్రు"}},{"a":"ఆంధ్ర స్వరాజ్య పార్టీ","e":"","table":null},{"a":"10000 మందికి మించి","e":"శ్రీయుత నరసాగౌడ్‌గారి చేతి ద్వారా మూడురోజులు మహావైభవంగా జరిగిన ఈ సభకు ఇంతమంది హాజరయ్యారు.","table":null},{"a":"స్వతంత్రంగా","e":"","table":null},{"a":"అఖిలభారత మహిళాసభ","e":"","table":null},{"a":"శ్రేయోభివృద్ధి, ద్యోతకమైన భావన","e":"","table":null},{"a":"వితంతు వివాహాలను సమర్థించాయి, బహుభార్యాత్వాన్ని, కన్యాశుల్కాన్ని, వేశ్యావృత్తిని నిషేధించాలని కోరాయి","e":"","table":null},{"a":"భాగం ఉండాలి","e":"","table":null},{"a":"ప్రాతినిధ్యం","e":"","table":null},{"a":"మాడపాటి మాణిక్యాంబ","e":"","table":null},{"a":"ఒక్క పర్యాయం మాత్రమే","e":"మాడపాటి హనుమంతరావు మహాసభకు, ఆయన సతీమణి మాడపాటి మాణిక్యాంబ మహిళా సభకు అధ్యక్షులుగా ఉన్నారు.","table":null},{"a":"తెలంగాణావారు","e":"అయినప్పటికీ ప్రభుత్వోద్యోగాలలోగానీ, ఉన్నత పదవులలోగానీ ఆంధ్రులకు స్థానం ఉండేది కాదు.","table":null},{"a":"కొత్త దేవాలయాలు నిర్మించకూడదు, పాతవాటికి అనుమతి లేనిదే మరమ్మతులు చేయకూడదు","e":"గస్తీ నిషాన్ 53 కింద సభలు, సమావేశాలు జరుపరాదని కూడా నిర్బంధం ఉండేది.","table":null},{"a":"శ్రీమతి కజిన్స్","e":"","table":null},{"a":"సరోజినీ నాయుడు, లేడీ హమీనా హైదరీ, రుస్తుంజీ సర్దుంజీ","e":"ఈ సమావేశానికి రాజకుమారి ధన్‌రాజ్ గిర్జీని అధ్యక్షులుగా ఎన్నుకున్నారు.","table":null},{"a":"ఉన్నతోద్యోగులు, శ్రీమంతులైనవారి భార్యలకు మాత్రమే","e":"","table":null},{"a":"సంఘం","e":"ఆమె పాట్రన్‌గా కూడా ఉండేవారు.","table":null},{"a":"రంగమ్మ ఒబులరెడ్డి, రాణి సరళాదేవి, సుందరమ్మ","e":"","table":null},{"a":"తరచుగా పాల్గొన్నారు","e":"సంస్కరణోద్యమం వెల్లువ, జాతీయోద్యమ ప్రభావం కలిసి ఇది సాధ్యమైంది.","table":null},{"a":"శ్రీమతి ఎల్లాప్రగడ సీతాకుమారి","e":"","table":null},{"a":"బూర్గుల రామకృష్ణారావుగారి భార్య శ్రీమతి అనంత లక్ష్మీదేవి","e":"","table":null},{"a":"1935","e":"","table":null},{"a":"గద్వాల మహారాణి ఆదిలక్ష్మీదేవి అధ్యక్షులు, బూర్గుల అనంత లక్ష్మీదేవి ఉపాధ్యక్షులు, సీతాకుమారి కార్యదర్శి","e":"","table":null},{"a":"15 సంవత్సరాలు","e":"హైదరాబాద్ ఆంధ్ర మహిళా సభను దుర్గాబాయి దేశ్‌ముఖ్ స్థాపించారు.","table":null},{"a":"ఇల్లిందల సరస్వతీదేవి, ఇల్లిందల శ్యామలాదేవి","e":"ఇల్లిందల సరస్వతీదేవి కోశాధికారిగా, కూచిభొట్ల రాజ్యలక్ష్మి సంయుక్త కార్యదర్శిగా ఉన్నారు.","table":null},{"a":"బొగ్గలకుంట రోడ్డులో ఉన్న రెడ్డి హాస్టల్ హాలును","e":"","table":null},{"a":"శ్రీకృష్ణదేవరాయాంధ్ర భాషానిలయం గ్రంథాలయం నుండి పుస్తకాలు తెప్పించడం","e":"చదవగలిగిన స్త్రీలకు వారం రోజుల కోసం పంపేవారు.","table":null},{"a":"స్వంత స్థలం సంపాదించి భవనం నిర్మించారు","e":"అందులో ఒక ప్రైమరీ స్కూలు తెరిచారు.","table":null},{"a":"హైస్కూలుగా మారింది","e":"","table":null},{"a":"శిశు వికాస్ విహార్","e":"తరువాత క్రమేపీ స్త్రీల హాస్టల్, లైబ్రరీ, కుట్టుపని శిక్షణా కేంద్రం నెలకొల్పారు.","table":null},{"a":"గ్రామవర్తకులు భోజన సామగ్రి","e":"ఈ సామగ్రికి డబ్బు అసలే చెల్లించకపోవడమో, ఒకవేళ చెల్లించినా ఏ కొద్దిగానో చెల్లించడమో జరిగేది.","table":null},{"a":"వంతుపద్ధతి","e":"కొందరు ఒకసారి, మరికొందరు ఇంకొక సారి సామగ్రి సప్లయిచేసేవారు.","table":null},{"a":"''వర్తక స్వాతంత్ర్యము''","e":"","table":null},{"a":"కుమ్మరి నీళ్ళు తేవాలి, వంట చేయాలి, చాకలి పాత్రలు కడగాలి, బట్టలు ఉతకాలి","e":"హరిజనులు అధికారుల మోటాముల్లెలను ఒక గ్రామం నుండి మరొక గ్రామానికి మోసుకుపోవాలి; ఈ పనులకు కూలీ ఇచ్చేవారు కారు.","table":null},{"a":"కాంగ్రెసు ఆధ్వర్యాన ప్రజా ప్రభుత్వం ఏర్పడిన తరువాత","e":"","table":null},{"a":"సహపంక్తి భోజనాలు, అస్పృశ్యతా నివారణ, స్త్రీ విద్య, వితంతు వివాహాలు, రజస్వలానంతర వివాహాలు","e":"కుల ప్రస్తక్తి లేకుండా, భాషా పరిధులను బట్టి ఉద్యమాలు నడపడం కూడా వీటిలో భాగం.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-18-vidya-vignanam-samskruti', 'telangana-history-te', 18, 'విద్య, విజ్ఞానం, సంస్కృతి', '[{"a":"నిజాం ప్రభుత్వమే","e":"విద్యా వ్యవస్థపై ప్రభుత్వానికి పూర్తి గుత్తాధికారం ఉండేది.","table":null},{"a":"చాలా అరుదు","e":"ప్రభుత్వం వాటిని అనుమతించేది కాదు.","table":null},{"a":"తెలుగు","e":"ప్రారంభంలో ఉర్దూ విద్యావిధానం ఉన్నా కింది తరగతుల్లో తెలుగు పుస్తకాలు కొనసాగించారు.","table":null},{"a":"కందుకూరి వీరేశలింగం పంతులు","e":"","table":null},{"a":"ఉర్దూ","e":"క్రమంగా మొదటి తరగతి నుంచి ఉర్దూలో విద్యావిధానం కొనసాగింది.","table":null},{"a":"రెండవ భాషగా","e":"","table":null},{"a":"ఉత్తర హిందూస్థానం","e":"","table":null},{"a":"కఠినంగా","e":"దీనివల్ల తెలుగు విద్యార్థులకు పాఠాలు అర్థం చేసుకోవడం కష్టంగా ఉండేది.","table":null},{"a":"సంస్థానంలోనే (హైదరాబాద్ సంస్థానం)","e":"","table":null},{"a":"ముస్లిం చక్రవర్తులు, రాజులు","e":"వారి ప్రధానులు, దర్బారుల్లోని విద్యావంతుల వర్ణన హెచ్చుగా ఉండేది.","table":null},{"a":"ఇస్లాం మతం","e":"","table":null},{"a":"రాజా బీర్బల్, రాజా తాన్సేన్","e":"","table":null},{"a":"హిందూ యుగం, ముస్లిం యుగం, బ్రిటిష్ యుగం","e":"ఇది బ్రిటిష్ వారు పెట్టిన విభజన పద్ధతి.","table":null},{"a":"నిజాం నవాబు, అతని పూర్వుల చరిత్ర","e":"","table":null},{"a":"బోధనాంశంగా","e":"","table":null},{"a":"ఉర్దూలో","e":"","table":null},{"a":"ఉర్దూలోకి","e":"","table":null},{"a":"పార్సీ, అరబ్బీ","e":"","table":null},{"a":"ఇతర రాష్ట్రాల నుంచి","e":"","table":null},{"a":"ఒకటి (ఒకటి మాత్రమే)","e":"ఇది జాతీయ భాషగా, ప్రజల మాతృభాషగా ఉండేది కాదు.","table":null},{"a":"తెలుగు, మరాఠీ, కన్నడం","e":"","table":null},{"a":"ప్రత్యామ్నాయంగా, పరాయి భాషాధిపత్యంగా","e":"దీనివల్ల తెలుగువారిలో విద్యావృద్ధి తగ్గిపోయింది.","table":null},{"a":"విశ్వకవి టాగూరు నుంచి రాజాజీ వరకు","e":"","table":null},{"a":"కాంగ్రెస్ ప్రభుత్వం ఏర్పడ్డాక","e":"","table":null},{"a":"ప్రభుత్వ వ్యతిరేకులుగా","e":"","table":null},{"a":"1940","e":"","table":null},{"a":"బ్రిటిష్ వారికి","e":"తాను స్వతంత్రుడనని చెప్పుకున్నా వాస్తవానికి సామంతుడే.","table":null},{"a":"సికింద్రాబాద్","e":"","table":null},{"a":"రెసిడెంట్","e":"","table":null},{"a":"హైదరాబాద్ నగరం","e":"అక్కడి నుంచి నిజాం పరిపాలనా వ్యవహారాలు తెలుసుకుని ఢిల్లీలోని బ్రిటిష్ ప్రభుత్వానికి రిపోర్టు చేసేవాడు.","table":null},{"a":"రాజకీయ ఉద్యమాలను అణచివేయడానికి","e":"నిజాంకు, బ్రిటిష్ వారికి వ్యతిరేకమైన ఉద్యమాలు తలెత్తకుండా చేయడానికి ఈ దిగ్బంధనాన్ని ఉపయోగించారు.","table":null},{"a":"సర్ వాల్టర్ మాంక్టన్","e":"","table":null},{"a":"లక్షల రూపాయలు","e":"","table":null},{"a":"వేల రూపాయలు","e":"","table":null},{"a":"30 సంవత్సరాలు","e":"","table":null},{"a":"1948","e":"పోలీసు చర్య అనంతరం పదవి విరమించి లండన్ వెళ్లిపోయాడు.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-19-grandhalayalu', 'telangana-history-te', 19, 'గ్రంథాలయాలు', '[{"a":"1901","e":"ఇది హైదరాబాద్ నగరంలో స్థాపించిన తొలి ఆంధ్రభాషానిలయాల్లో ఒకటి.","table":null},{"a":"కొమర్రాజు వెంకటలక్ష్మణరావు, రావిచెట్టు రంగారావు, మునగాల జమీందారు రాజా నాయని వెంకటరంగారావు","e":"వీరు తెలుగు తల్లిని కనక కిరీటంతో అలంకరించాలనే ఆకాంక్షతో ఈ గ్రంథాలయాన్ని స్థాపించారు.","table":null},{"a":"నిజాం దమన రీతి","e":"నిరక్షరాస్యత నిర్మూలన, చరిత్ర పరిశోధనతో పాటు నిజాం దమన రీతికి వ్యతిరేకంగా ఉద్యమం ఈ లక్ష్యాల్లో ఒకటి.","table":null},{"a":"ఆసఫియా స్టేట్ లైబ్రరీ","e":"దీనిని అబ్దుల్ ఖయ్యూం, మౌల్వీ సయ్యద్ హుసేన్ బిల్‌గ్రామీ, ఇమాదుల్ ముల్క్ కలిసి స్థాపించారు.","table":null},{"a":"స్టేట్ సెంట్రల్ లైబ్రరీ, అఫ్జల్‌గంజ్","e":"ప్రస్తుతం అఫ్జల్‌గంజ్ ప్రాంతంలో ఉన్న స్టేట్ సెంట్రల్ లైబ్రరీయే పాత ఆసఫియా స్టేట్ లైబ్రరీ.","table":null},{"a":"భారత గుణవర్ధక సంస్థ","e":"ఇది ఇప్పటికీ పనిచేస్తున్నది, ఇందులో ప్రాచీన కవుల రచనలు, గ్రంథాలు ఉన్నాయి.","table":null},{"a":"1908","e":"దీనికి ఆంధ్ర పితామహ మాడపాటి హనుమంతరావు కార్యదర్శిగా ఉండేవారు.","table":null},{"a":"మాడపాటి హనుమంతరావు","e":"ఆయనను ఆంధ్ర పితామహ అని పిలుస్తారు.","table":null},{"a":"దాదాపు 15 గ్రంథాలయాలు","e":"తెలంగాణలో ఆంధ్రోద్యమం ప్రారంభమయ్యేనాటికి 1922 వరకల్లా సుమారు 15 గ్రంథాలయాలు స్థాపించబడ్డాయి.","table":{"headers":["సంవత్సరం","ప్రాంతం","గ్రంథాలయం పేరు"],"rows":[["1905","సికింద్రాబాద్","ఆంధ్ర సంవర్ధనీ గ్రంథాలయం"],["1911","ఎర్రుపాలెం","మహబూబియా గ్రంథాలయం"],["1917","సూర్యాపేట","ఆంధ్ర విజ్ఞాన ప్రకాశన గ్రంథాలయం"],["1918","నల్లగొండ","ఆంధ్ర సరస్వతీ గ్రంథాలయం"],["—","వరంగల్","శబ్దానుశాసన గ్రంథాలయం"],["—","ఖమ్మం","జ్ఞాన విద్యుత్ ప్రవాహిణీ భాషానిలయం"],["—","హైదరాబాద్ (గౌలిగూడ)","బాలసరస్వతీ ఆంధ్ర గ్రంథాలయం"],["—","నాంపల్లి","వేమన ఆంధ్ర భాషానిలయం"]],"unit":"గ్రంథాలయం స్థాపించిన ప్రాంతం"}},{"a":"సభలు, సమావేశాలు, కవితాగోష్ఠులు","e":"వివిధ సంస్థల వార్షికోత్సవాలకు కూడా ఇవి వేదికగా ఉండేవి.","table":null},{"a":"గ్రంథాలయాలు","e":"గ్రంథాలయాల ద్వారానే ఆంధ్రోద్యమం అతి త్వరగా రాష్ట్రంలో వ్యాపించింది.","table":null},{"a":"ప్రభుత్వ అనుమతి లేదని","e":"గ్రంథాలయం నడపడానికి ప్రభుత్వ అనుమతి తీసుకున్నారా అని కలెక్టర్ ప్రశ్నించి, లేదని తెలియగానే మూసివేయమని ఆజ్ఞాపించాడు.","table":null},{"a":"సర్ అక్బర్ హైదరీ","e":"పంతులుగారు (మాడపాటి హనుమంతరావు) అప్పటి ప్రభుత్వ హోం కార్యదర్శి సర్ అక్బర్ హైదరీకి లేఖరాశారు.","table":null},{"a":"గ్రంథాలయాలకు ప్రభుత్వ అనుమతి అవసరం లేదని","e":"హోం కార్యదర్శి కలెక్టర్ నుంచి సమాచారం తెప్పించుకుని, గ్రంథాలయాలు నడపడానికి ప్రభుత్వ అనుమతి పొందవలసిన అవసరం లేదని పంతులుగారికి సమాధానమిచ్చారు.","table":null},{"a":"ఒక సంవత్సరం వరకు","e":"మడికొండ గ్రంథాలయానికి కూడా ఇలాంటి దురవస్థే పట్టింది.","table":null},{"a":"తెలుగు భాషను గుంజవలసిన అవసరం లేదు","e":"సర్కారు వారి దస్తరములన్నీ ఉర్దూ భాషలో ఉండగా, చచ్చిపోయిన తెలుగు భాషను గుంజవలసిన అవసరం లేదని అన్నాడట.","table":null},{"a":"సర్కారీ దవాఖానాలో పనిచేసిన మహారాష్ట్రుడు (డాక్టరు)","e":"ఇతను ప్రజల మనస్తత్వాన్ని గ్రహించి, సమారాధన పేరుతో సామగ్రి అడిగించి, మిగిలిన సొమ్ముతో గ్రంథాలయం స్థాపనకు సహకరించాడు.","table":null},{"a":"గోదావరి వచనాలయము","e":"గ్రామ కూడలిలో మూడు వందల గజాల స్థలం కొని, ఈ గ్రంథాలయాన్ని స్థాపించారు.","table":null},{"a":"1925, మధిరలో","e":"తెలంగాణలోని అన్ని గ్రంథాలయాల ప్రతినిధులు ఈ సభలో పాల్గొన్నారు.","table":null},{"a":"పింగళి వెంకట్రామిరెడ్డి","e":"ఆయన దేశముఖ్, జీతభత్యములు లేకుండా సెషన్స్ జడ్జి ఉద్యోగం చేసినవారు.","table":null},{"a":"సూర్యాపేటలో, ఆంధ్ర జనసంఘం సమావేశంతోపాటు","e":"ఈ గ్రంథాలయసభతోపాటు ఆంధ్ర యువక సభ, సంఘసంస్కార సభ, ఆంధ్ర మహిళాసభ, వైశ్య యువజన సభలు కూడా జరిగాయి.","table":null},{"a":"వామన్ నాయక్","e":"ఈ సభలు 1929 మే 31, జూన్ 1వ తేదీల్లో జరిగాయి.","table":null},{"a":"కారాగార శిక్ష","e":"పోలీసుల దౌర్జన్యాలను ఎదుర్కొని గ్రంథాలయాలను నిర్వహించిన సందర్భాలు ఎక్కువగా ఉన్నాయి.","table":null},{"a":"అధ్యక్షస్థానాచార్యుని, తదితరుల ఉపన్యాసాలను ముందుగా తనకు చూపించాలని","e":"ఈ అవమానకరమైన షరతులను గ్రంథాలయ కార్యకర్తలు అంగీకరించలేదు.","table":null},{"a":"హైకోర్టు","e":"నిరంకుశ నిర్బంధ విధానం అమల్లో ఉన్నప్పటికీ కార్యకర్తల ఉత్సాహం తగ్గలేదు.","table":null},{"a":"వెల్దుర్తి మాణిక్యరావు, గుండవరపు హనుమంతరావు, కె.సి.గుప్తా","e":"వీరు తొలి అణాగ్రంథమాలలను స్థాపించారు.","table":null},{"a":"ఐదు రూపాయలు","e":"","table":null},{"a":"హైదరాబాద్ రాజ్యాంగ సంస్కరణలు, 1939 నవంబరు","e":"నాటి నిజాం తీసుకువచ్చిన సంస్కరణలను వెల్దుర్తి మాణిక్యరావు ఉర్దూ నుంచి తెలుగులోకి అనువదించారు.","table":null},{"a":"మాడపాటి హనుమంతరావు","e":"ఈ పుస్తకం రెండు ముద్రణలు వేసినా చాలలేదు.","table":null},{"a":"నిషేధం","e":"ఈ పుస్తకం రైతులందరికి బద్దకం వదిలి కార్యదీక్షకు పూనాలని, ఉద్యమించాలని సూచిస్తూ రైతుల కడగండ్లను వివరించింది.","table":null},{"a":"నాలుగు గ్రంథాలు","e":"గ్రామ వ్యవసాయం, వైద్యం, పరిశ్రమలు, చారిత్రక విషయాలపై రచనలు చేయించి ఈ నాలుగు గ్రంథాలను ప్రచురించింది.","table":null},{"a":"ధవళ శ్రీనివాసరావు, సరిప్రగడ భర్తవరావు","e":"దీనికి అంబడిపూడి వెంకటరత్నం పట్టుకొమ్మగా ఉండేవారు.","table":null},{"a":"1932, ఆచార్య రాయప్రోలు సుబ్బారావు","e":"కురుగంటి సీతారామయ్య కార్యదర్శిగా ఉండేవారు.","table":null},{"a":"బూర్గుల రంగనాథరావు, నెల్లూరు కేశవస్వామి, వెల్దుర్తి మాణిక్యరావు, 1939లో","e":"ఇది ఖండకావ్యాలను, కథానికలను, సాహిత్య విమర్శలను ప్రచరించింది.","table":null},{"a":"1941","e":"ఈ గ్రంథమాల 1938-41, 1953-61 మధ్యకాలంలో ముప్పై పుస్తకాలను ప్రచురించారు.","table":null},{"a":"కోదాటి నారాయణరావు","e":"ఈ గ్రంథాలయం అద్దురంగా పనిచేసింది.","table":null},{"a":"రాజా నాయని వెంకటరంగారావు, కొమర్రాజు వెంకటలక్ష్మణరావు, గాడిచర్ల హరిసర్వోత్తమరావు, అయ్యదేవర కాళేశ్వరరావు","e":"దీని కార్యస్థానం హైదరాబాద్‌లోని రెసిడెన్సీ బజార్‌లో రావిచెట్టు రంగారావు ఇంట్లో ఉండేది.","table":null},{"a":"మద్రాసుకు","e":"రావిచెట్టు వారి కార్యకలాపాలపై హైదరాబాద్ పోలీసుల నిఘా ఎక్కువవడం వల్ల ఇలా చేయవలసి వచ్చింది.","table":null},{"a":"ఆదిరాజు వీరభద్రరావు","e":"1922లో ఆంధ్ర జనసంఘానికి అనుబంధంగా ఆంధ్ర పరిశోధక మండలిని ఏర్పరిచారు.","table":null},{"a":"కొమర్రాజు లక్ష్మణరావు","e":"కొమర్రాజు వారి అస్తమయానంతరం లక్ష్మణరావు పరిశోధక మండలిగా మారింది.","table":null},{"a":"తెలంగాణా శాసనాలు రెండు సంపుటాలు","e":"ఈ సేవ అసదృశ్యమైనదిగా పేర్కొన్నారు.","table":null},{"a":"1952","e":"ఇది పుట్టగానే తెలంగాణ అంతటా సాహిత్య ఝుంఝూమారుతం వీచింది.","table":null},{"a":"కోటి గొంతుకలు","e":"దీనిని పలికించినవాడు దాశరథి.","table":null},{"a":"ఆచార్య లక్ష్మీరంజనం, సి. నారాయణరెడ్డి, కాళోజీ, దాశరథి","e":"వానమామలై, రామరాజు, పల్లా దుర్గయ్య, కప్పగంతుల లక్ష్మణశాస్త్రి, ఇరివెంటి కృష్ణమూర్తి, వి.పి. రాఘవాచార్యులు కూడా ఈ సంఘం పరిపుష్టికి కృషిచేశారు.","table":null},{"a":"గోల్కొండ కవుల సంచిక","e":"తెలంగాణలోని నలుమూలల ఉన్న మూడు వందల యాభై నలుగురు కవుల రచనలను సంపుటీకరించి ఇది ప్రకటించారు.","table":null},{"a":"సురవరం ప్రతాపరెడ్డి","e":"తెలంగాణాలో ఎవ్వరూ తెలుగు మాట్లాడరని, తెలుగువారంతా ఉరుదులోనే రాస్తారని కొందరు అనేవారు, ఇది ఆయనకు బాధ కలిగించింది.","table":null},{"a":"వట్టికోట ఆళ్వారుస్వామి","e":"బూర్గుల రంగనాథరావు, భాస్కరభట్ల కృష్ణారావుగార్ల ప్రోద్బలంతో ఈ ప్రయత్నం ప్రారంభమైంది.","table":null},{"a":"1943 మే 26, రెడ్డి హాస్టల్ గ్రంథాలయ భవనం","e":"హైదరాబాద్ నాయకులను, జంటనగరాల సాహిత్యాభిమానులను ఈ సమావేశానికి పిలిచారు.","table":null},{"a":"లోకనంది శంకరనారాయణరావు","e":"ఈ సమావేశంలో ఒక సాహిత్య సంస్థను స్థాపించాలని ఏకగ్రీవంగా నిర్ణయించారు.","table":null},{"a":"నిజాంరాష్ట్ర ఆంధ్ర సారస్వత పరిషత్తు","e":"మొదట ''హైదరాబాద్ ఆంధ్ర సాహిత్య పరిషత్తు'' అనే పేరు ప్రతిపాదించినా, తర్వాత ఈ పేరుకు మార్చారు.","table":null},{"a":"11 మంది","e":"వీరు నియమావళిని, కార్యప్రణాళికను తయారు చేశారు.","table":{"headers":["క్రమసంఖ్య","సభ్యుని పేరు"],"rows":[["1","మాడపాటి హనుమంతరావు పంతులు"],["2","బుక్కపట్టణం రామానుజాచార్యులు"],["3","సురవరం ప్రతాపరెడ్డి"],["4","లోకనంది శంకరనారాయణరావు"],["5","బూర్గుల రామకృష్ణారావు"],["6","చిదిరెమఠం వీరభద్రశర్మ"],["7","ఆదిరాజు వీరభద్రరావు"],["8","నందగిరి వెంకటరావు"],["9","కోదాటి నారాయణరావు"],["10","గడియారం రామకృష్ణశర్మ"],["11","భాస్కరభట్ల కృష్ణారావు"]],"unit":"1943లో ఏర్పాటైన ఉపసంఘ సభ్యులు"}},{"a":"1943 జూన్ 1, రెడ్డి హాస్టల్ గ్రంథాలయం","e":"ఈ సభలో మొదటి కార్యవర్గం ఎన్నికైంది.","table":null},{"a":"లోకనంది శంకరనారాయణరావు (అధ్యక్షులు), బిదురు వెంకటశేషయ్య (ప్రధాన కార్యదర్శి)","e":"మొదట ఈ సంస్థ కార్యస్థానం గోల్కొండ పత్రిక కార్యాలయంలో ఉండేది.","table":null},{"a":"సురవరం ప్రతాపరెడ్డి","e":"లోకనందివారు నగరం విడిచి వెళ్ళవలసి రావడంతో సురవరం ప్రతాపరెడ్డి అధ్యక్షులైనారు.","table":null},{"a":"వరంగల్లు పట్టణం, ఉదయరాజు రాజేశ్వరరావు","e":"కాళోజీ నారాయణరావు కార్యదర్శిగా ఆహ్వాన సంఘం ఏర్పడింది.","table":null},{"a":"కొత్వాల్ వెంకటరామిరెడ్డిగారు ప్రారంభించారు, సురవరం ప్రతాపరెడ్డిగారు అధ్యక్షత వహించారు","e":"వరంగల్లు కోటలో కవి సమ్మేళనం ఏర్పాటు చేయబడింది.","table":null},{"a":"వేసిన పందిళ్ళను పీకి వేదికను ధ్వంసం చేశారు","e":"అయినా ఎం.ఎస్. రాజలింగంగారు తన యువక సంఘంతో వెళ్ళి సభాస్థలిని బాగుచేసి కవి సమ్మేళనం జరపాలని పట్టుబట్టారు.","table":null},{"a":"నల్లగొండలో, కంచనపల్లి చిన వెంకటరామారావుగారి అధ్యక్షతన","e":"రాష్ట్రంలో రాజకీయ అనిశ్చితివల్ల ఈ సభలు పెద్ద ఉత్సాహం లేకుండా ముగిశాయి.","table":null},{"a":"ఇల్లిందల రామచంద్రరావు","e":"దేవులపల్లి రామానుజరావుగారి మిత్రుడైన ఈయన స్థానిక ముస్లిం మతోన్మాదుల వ్యతిరేకతను ఎదిరించి సభను జరిపారు.","table":null},{"a":"రాష్ట్రం విడిచి సురక్షిత ప్రాంతానికి వెళ్ళిపోయారు","e":"దీనితో పరిషత్తు కార్యకలాపాలు కొంతకాలం స్తంభించాయి.","table":null},{"a":"మాతృభాష ద్వారా","e":"అందుకోసం సభలు, సమావేశాలు జరిగాయి.","table":null},{"a":"దేవులపల్లి రామానుజరావు","e":"మొక్కను పెంచి మానును చేశారు, తరువాత దా.సి.నారాయణరెడ్డి దీని బాధ్యత వహించి నూతన భవనాలు కట్టించారు.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-2-ikshvaku', 'telangana-history-te', 2, 'ఇక్ష్వాకులు', '[{"a":"వాసిష్టీ పుత్ర శ్రీచాంతమూలుడు","e":"శాతవాహన సామ్రాజ్యం అంతరించాక కృష్ణాతీరంలో విజయపురి రాజధానిగా ఈ వంశరాజ్యం స్థాపించాడు.","table":null},{"a":"విజయపురి","e":"దీన్నే నేటి నాగార్జునకొండ అంటారు.","table":null},{"a":"225-300 మధ్య","e":"","table":null},{"a":"శాంతిమూలుడు, వీర పురుషదత్తుడు, ఏహువల శాంతమూలుడు, రుద్రపురుష దత్తుడు","e":"","table":null},{"a":"గుంటూరు, ప్రకాశం, నల్లగొండ మండలాలు","e":"","table":null},{"a":"వైదిక మతం","e":"","table":null},{"a":"మహాసేన, విరూపాక్షాలయాలు","e":"","table":null},{"a":"రాణివాసపు స్త్రీలు, రాణులు","e":"","table":null},{"a":"శాతవాహన పద్ధతి","e":"","table":null},{"a":"సింహం","e":"","table":null},{"a":"చైనా, సింహళం, మలయా దేశాలు","e":"","table":null},{"a":"బౌద్ధతీర్థము","e":"","table":null},{"a":"ప్రాకృతభాష","e":"","table":null},{"a":"పంచాంగం, చంద్రాయన వ్యవహారము","e":"తిథి, వార, పక్ష, మాసాలతో కూడిన పంచాంగం, చంద్రాయన వ్యవహారము వీరి కాలంనుండే ప్రారంభమైనది.","table":null},{"a":"గ్రీష్మము, వర్షము, హేమంతము","e":"ఒక్కో ఋతువుకు నాలుగు మాసాలు.","table":null},{"a":"వైవాహిక సంబంధాలు","e":"","table":null},{"a":"నాగార్జునకొండ త్రవ్వకాలలో లభించిన పురావస్తు సంపద","e":"","table":null},{"a":"వెలుపల చెక్కరాయి, మట్టి ఇటుకలు","e":"","table":null},{"a":"రంగభూమి","e":"గోళాకారమైన ఈ కట్టడంలో దాదాపు వేయిమంది ప్రేక్షకులు కూర్చుని చూడగలిగేవారు.","table":null},{"a":"రోమన్ నాణేలు","e":"విదేశాలతో విజయపురికి వర్తక వ్యాపారాలు విరివిగా సాగినట్లు తెలుస్తుంది.","table":null},{"a":"ఇక్ష్వాకు వంశం","e":"","table":null},{"a":"రుద్రపురుషదత్తుడు","e":"పల్లవరాజైన సింహవర్మ విజయపురిపై దండెత్తి ఇక్ష్వాకు రాజ్యాన్ని అంతరింపజేశాడు.","table":null},{"a":"విశ్వవిద్యాలయంగా","e":"నాగార్జునుని కాలం నుండి కొన్ని శతాబ్దాల వరకు విద్యార్థుల విద్యాదాహాన్ని తీర్చే కేంద్రంగా నిలిచింది.","table":null},{"a":"కాశ్మీర్, గాంధార, చీన, చిలాటి, తోసలి, అపరాంత, వంగ, వారణాసి, యవన, సాలూర, తంబపణ్ణి, తమిళ దేశాలు","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-20-patrikalu', 'telangana-history-te', 20, 'పత్రికలు', '[{"a":"శ్రీనివాసశర్మ","e":"1921లో మహబూబ్‌నగర్ జిల్లా కొయిలకొండలో సరోజిని విలాస్ ముద్రాక్షరశాల స్థాపించి ఈయన హిత బోధిని పత్రికను ప్రారంభించారు.","table":null},{"a":"వ్యవసాయం, వైద్యం, పారిశ్రామిక, సంఘసంస్కరణ","e":"రాజకీయాల్లో ప్రవేశం లేకుండా ఈ నాలుగు అంశాలపై పత్రిక నడిచింది.","table":null},{"a":"అయిదువందల మంది","e":"","table":null},{"a":"రెండు సంవత్సరాలు","e":"శ్రీనివాసశర్మ స్వయంగా ఆయుర్వేద వైద్యుడిగా, ''లోక నాట్యమండలి'' ద్వారా సాంస్కృతిక కార్యక్రమాల్లో మునిగిపోవడం వలన పత్రిక ఆగిపోయింది.","table":null},{"a":"వెంకటరావు","e":"1917లో దివ్యజీవన సమాజానికి చెందిన వెంకటరావు ఈ మాసపత్రికను ప్రారంభించారు.","table":null},{"a":"జగదీశ్వర ప్రింటింగ్ ప్రెస్","e":"ఇది గోలుగూడలో ఉంది, పత్రిక పూర్తిగా ఆధ్యాత్మిక జ్ఞానం వివరించేది.","table":null},{"a":"నీలగిరి","e":"1922 ఆగస్టు 24న షబ్బీసు వెంకటరామనరసింహారావు సంపాదకత్వంలో నల్లగొండ నుంచి ఈ వారపత్రిక ప్రారంభమైంది, ఇదే మొట్టమొదటి పూర్తిస్థాయి రాజకీయ పత్రిక.","table":null},{"a":"వొద్దిరాజు సోదరులు","e":"1922 ఆగస్టు 27న వరంగల్ జిల్లా మానుకోట తాలూకా ఇనుగుర్తి నుంచి వొద్దిరాజు సీతారామచంద్రరావు, వొద్దిరాజు రాఘవరంగారావు సోదరులు దీన్ని ప్రచురించారు.","table":null},{"a":"షబ్బీసు రామనరసింహారావు","e":"","table":null},{"a":"1929లో","e":"","table":null},{"a":"సురవరం ప్రతాపరెడ్డి","e":"1926 నుంచి 1946 వరకు అవిచ్ఛిన్నంగా ఈయన గోల్కొండ పత్రిక ద్వారా ప్రజలను మేల్కొల్పారు.","table":null},{"a":"1947లో","e":"","table":null},{"a":"ముదిగొండ వీరభద్రశాస్త్రి","e":"1923లో వరంగల్ నుంచి ఈయన దీన్ని ప్రారంభించారు.","table":null},{"a":"పి.ఎస్.శర్మ","e":"ఈయన సంపాదకత్వంలో వెలువడ్డ ఈ పత్రిక 1927లో నాల్గో సంవత్సరం మొదటి సంచికతో ఆగిపోయింది.","table":null},{"a":"దత్తాత్రేయ శర్మ","e":"1924లో సికింద్రాబాద్ నుంచి ఈయన దీన్ని అంధ్రాంగ్ల భాషలో ప్రచురించారు, ఏడేని సంవత్సరాలు నడిచింది.","table":null},{"a":"బెల్లంకొండ రామానుజాచార్యులు, నరసింహాచార్యులు","e":"వీరు ఆత్రాఫ్‌బల్దా జిల్లా వడ్డేపల్లి గ్రామానికి చెందిన సోదరులు, ఈ పత్రిక మూడేళ్లు నడిచింది.","table":null},{"a":"తెలుగు, సంస్కృతం, ఇంగ్లీష్","e":"ఈయన నల్లగొండ జిల్లా రామన్నపేట తాలూకా వలిగొండ కాపురస్తుడు.","table":null},{"a":"మాడపాటి హనుమంతరావు","e":"షబ్బీసు వెంకటరామ నరసింహారావుతో పాటు ఈయన కూడా మాడపాటి హనుమంతరావు వద్ద శిక్షణ పొందారు.","table":null},{"a":"ఆంధ్రవాణి","e":"ఈ పత్రికను ఐదు సంవత్సరాలు నడిపారు, ఆ పత్రిక కార్యాలయం ఉన్న వీధిని ఇప్పటికీ ''ఆంధ్రవాణి వీధి'' అని పిలుస్తారు.","table":null},{"a":"1970లో","e":"","table":null},{"a":"బుక్కపట్టణం రామానుజాచార్యులు","e":"1929లో హైదరాబాద్ నగరంలో ఈయన దీన్ని ప్రారంభించారు.","table":null},{"a":"రామానుజాచార్యులు","e":"","table":null},{"a":"1942, రామానుజాచార్యులు","e":"ఈ పత్రికలో ''చార్మినార్ గాసిప్'' అనే శీర్షిక ప్రతిదినం ఉండేది, నిజాం నవాబు అంతఃపుర విషయాలు, పై అధికారవర్గం కార్యాలయాల రహస్యాలు దీనిలో ప్రచురితమయ్యేవి.","table":null},{"a":"రామానుజాచార్యులు, రాజగోపాల్","e":"1937లో ఈ మిత్రులిద్దరూ కలిసి దీన్ని ప్రారంభించారు, 1939లో ఇది దినపత్రికగా మారింది.","table":null},{"a":"డెయిలీ న్యూస్","e":"ఈ పత్రిక ప్రారంభించిన నెలరోజులకే ఆయన మరణించారు.","table":null},{"a":"భాగ్యరెడ్డి","e":"1925లో ప్రముఖ సంఘసంస్కరణ వేత్త అయిన భాగ్యరెడ్డి దీన్ని స్థాపించారు, తర్వాత ఆరోగ్య కారణాలవల్ల మైసూరు వెళ్లడంతో పత్రిక ఆగిపోయింది.","table":null},{"a":"ఆది హిందూ","e":"హరిజనోద్ధరణ కృషిలో భాగంగా ఈ పత్రికను ప్రారంభించారు.","table":null},{"a":"వీరభద్రశర్మ","e":"","table":null},{"a":"దేవపల్లి రామానుజారావు","e":"వరంగల్ నుంచి ఈయన సంపాదకత్వంలో వెలువడిన ఈ పత్రిక ఆర్థిక కారణాలవల్ల ఒక సంవత్సరంలోనే ఆగిపోయింది.","table":null},{"a":"నిజాం నిర్బంధం","e":"వాక్ స్వాతంత్ర్యంపై నిజాం విధించిన క్రూర నిర్బంధమే దీనికి కారణం.","table":null},{"a":"చల్లా సుబ్బారావు","e":"1945లో ఈయన ఈ తెలుగు మాసపత్రికను వెలువరించారు.","table":null},{"a":"ఖాజా అబ్దుల్ గఫార్","e":"ప్రముఖ ఉర్దూ పత్రిక ''పయాం'' సంపాదకుడైన ఈయన ఈ తెలుగు పత్రికను ప్రారంభించారు, ఇది ఆరు నెలలు మాత్రమే నడిచింది.","table":null},{"a":"గులాం మహమ్మద్ కలకత్తావాలా","e":"ఈయన ఖాన్ బహదూర్ అహమద్ నవాజ్‌జంగ్ అల్లుడు, ఇంగ్లీష్, ఉర్దూ, తెలుగు మూడు భాషల్లో పత్రికలు నడిపారు.","table":null},{"a":"వేర్వేరు వర్గాలు","e":"","table":{"headers":["భాష","సమర్థించినది"],"rows":[["ఇంగ్లీష్","నిజాం ప్రభుత్వం"],["ఉర్దూ","లీగ్, రజాకార్లు"],["తెలుగు","నిజాం వ్యతిరేక శక్తులు"]],"unit":"మీజాన్ ఎడిషన్లు"}},{"a":"అడవి బాపిరాజు","e":"బాపిరాజు ''ధూపదీపాలు'', ''మిర్చి మసాలా'' శీర్షికలు నిర్వహించి ప్రజలకు వినోదాన్ని, విజ్ఞానాన్ని అందించారు.","table":null},{"a":"తిరుమల రామచంద్ర తదితరులు","e":"","table":{"headers":["క్రమ సంఖ్య","సబ్ ఎడిటర్ పేరు"],"rows":[["1","తిరుమల రామచంద్ర"],["2","రాంభట్ల కృష్ణమూర్తి"],["3","శ్రీనివాస చక్రవర్తి"],["4","బొమ్మకంటి సుబ్బారావు"],["5","విద్వాన్ విశ్వం"]],"unit":"మీజాన్ సబ్ ఎడిటర్లు"}},{"a":"1947 ఆగస్టు 7","e":"రాజకార్ల దౌష్ట్యాలకు విసిగిపోయి ఈయన బాధ్యతలనుండి తప్పుకున్నారు, పత్రిక మొత్తం మూడు సంవత్సరాలు నడిచింది.","table":null},{"a":"మందుముల నరసింగరావు","e":"ఈయన ఆంధ్ర మహాసభ పూర్వాధ్యక్షుడు, రజాకార్లు ఈ పత్రికను ఆపివేయడానికి తీవ్రంగా కృషి చేసినా పత్రిక ఆగిపోయింది.","table":null},{"a":"షోయబుల్లాఖాన్","e":"","table":null},{"a":"హత్య","e":"ఖాసిం రజ్వీ సూచనపై రజాకార్ల దుర్మార్గులు ఈయనను చంపేశారు, ఈ హత్య దేశంలోనే తీవ్ర సంచలనాన్ని సృష్టించింది.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-21-telangana-jalavanarulu-parishramalu', 'telangana-history-te', 21, 'తెలంగాణ జలవనరులు, పరిశ్రమలు', '[{"a":"నిర్మలగుట్టలు","e":"ఈ శాఖ ఆదిలాబాద్ జిల్లాలో అంతమవుతుంది.","table":null},{"a":"రాచీ గుట్టలు","e":"","table":null},{"a":"కందికల్ గుట్టలవరుస","e":"","table":null},{"a":"రాచకొండ గుట్టలు","e":"","table":null},{"a":"అమ్రాబాద్ గుట్టలు","e":"ఇవి తెలంగాణలో ప్రారంభమై రాయలసీమలోనికి వ్యాపించి ఉన్నాయి, కృష్ణానది ఇక్కడ గుండా ప్రవహిస్తుంది.","table":null},{"a":"వికారాబాద్","e":"","table":null},{"a":"నల్గొండ","e":"","table":null},{"a":"ఆదిలాబాద్, వరంగల్","e":"","table":null},{"a":"కృష్ణా, గోదావరి","e":"ఈ రెండు మహానదుల లోయల గుండానే ప్రాచీనాంధ్రులు మొదట తెలంగాణలో స్థిరపడ్డారు.","table":null},{"a":"మంజీర","e":"","table":null},{"a":"బీడ్","e":"బీడ్ జిల్లా మహారాష్ట్రలో ఉంది.","table":null},{"a":"400 మైళ్ళు","e":"","table":null},{"a":"ప్రాణహిత","e":"","table":null},{"a":"కాళేశ్వరం","e":"ఇది ఆదిలాబాద్ జిల్లాలోని ఒక పుణ్యక్షేత్రం.","table":null},{"a":"40 మైళ్ళు","e":"","table":null},{"a":"సిరిసిల్ల కొండలు, 80 మైళ్ళు","e":"ఇది కరీంనగర్ జిల్లాలోని సిరిసిల్ల కొండలలో జన్మించి 80 మైళ్ళు ప్రవహిస్తుంది.","table":null},{"a":"మహాదేవపూర్","e":"","table":null},{"a":"800 మైళ్ళు","e":"","table":null},{"a":"మహాబలేశ్వర్","e":"ఇది పశ్చిమ కనుమలలోని సతారావద్ద ఉంది.","table":null},{"a":"పాతాళగంగ","e":"","table":null},{"a":"సంగమేశ్వర్","e":"ఇది ఆలంపూర్ సమీపంలో ఉంది.","table":null},{"a":"షాహాబాద్ కొండలు, 95 మైళ్ళు","e":"ఇది మహబూబ్‌నగర్ జిల్లాలోని షాహాబాద్ కొండలలో జన్మిస్తుంది.","table":null},{"a":"157 మైళ్ళు","e":"","table":null},{"a":"అనంతగిరి కొండలు","e":"","table":null},{"a":"ఉస్మాన్‌సాగర్","e":"","table":null},{"a":"వజీరాబాద్","e":"ఇది నల్గొండ జిల్లాలో ఉంది.","table":null},{"a":"మహమ్మద్‌ఖులీ, 1589","e":"","table":null},{"a":"భాగ్యనగరం","e":"ఇది మహమ్మద్‌ఖులీకి ప్రియురాలైన భాగమతి పేరు మీద పెట్టారు.","table":null},{"a":"హైదర్‌మహల్","e":"ఈమె మహమ్మద్‌ఖులీ భార్య.","table":null},{"a":"మూడవ నిజాం సికిందర్‌జా, 1806.","e":"","table":null},{"a":"ఫణిగిరి గుట్టలు","e":"","table":null},{"a":"03","e":"","table":null},{"a":"పాకాల, రామప్ప, లక్నవరం, ఘనపురం","e":"ఇవి సుప్రసిద్ధమైన నీటిపారుదల చెరువులు.","table":null},{"a":"ముస్లింరాజులు","e":"","table":null},{"a":"16వ శతాబ్దం","e":"","table":null},{"a":"1799","e":"","table":null},{"a":"భారత ఇరిగేషన్ కమీషన్","e":"1902లో భీకర క్షామం మరల రాకుండా చేయాలని ఈ కమీషన్ వచ్చింది.","table":null},{"a":"సర్ మోక్షగుండం విశ్వేశ్వరయ్య","e":"","table":null},{"a":"నవాబ్ అలీ నవాజ్‌జంగ్","e":"","table":null},{"a":"నిజాంసాగర్, ఉస్మాన్‌సాగర్, హిమాయత్‌సాగర్","e":"వీటితోపాటు పోచారం, వైరా, పాలేరు, దిండి, చంద్రసాగర్, మానేరు, కోయల్‌సాగర్ ప్రాజెక్టులు కూడా ముఖ్యమైనవి.","table":null},{"a":"అలీనవాజ్‌జంగ్","e":"","table":null},{"a":"శ్రీరాంసాగర్ ప్రాజెక్ట్","e":"","table":null},{"a":"బొగ్గు","e":"","table":null},{"a":"ఇండస్ట్రియల్ ఫండ్, ఒక కోటి రూపాయలు","e":"","table":null},{"a":"4 కోట్ల 98 లక్షలు","e":"","table":null},{"a":"ఆజంజాహీ టెక్స్‌టైయిల్స్ మిల్లు, ఉస్మాన్‌షాహీ టెక్స్‌టైయిల్స్ మిల్లు","e":"ఆజంజాహీ మిల్లు వరంగల్‌లో, ఉస్మాన్‌షాహీ మిల్లు నాందేడ్/మహారాష్ట్రలో ఉన్నాయి.","table":null},{"a":"పత్తి","e":"ఆదిలాబాద్ జిల్లా, మరాట్వాడాలో పండే పత్తిని ఉపయోగించుకునేందుకు ఇవి నిర్మించారు.","table":null},{"a":"హైదరాబాద్ స్పిన్నింగ్ అండ్ వీవింగ్‌మిల్లు, 1874","e":"","table":null},{"a":"రూ.8,16,666","e":"","table":null},{"a":"1659 మంది","e":"","table":null},{"a":"1931, 18 లక్షలు","e":"","table":null},{"a":"3400 మంది","e":"","table":null},{"a":"1929, రూ.20,98,600","e":"","table":null},{"a":"నిజాంషుగర్ ఫ్యాక్టరీ, 1937","e":"","table":null},{"a":"72 శాతం","e":"","table":null},{"a":"1939","e":"","table":null},{"a":"ఆదిలాబాద్","e":"","table":null},{"a":"ఆరువేల టన్నులు","e":"","table":null},{"a":"వెంకట ఎన్.ఎస్.ఆర్ (నిజాంస్టేటు రైల్వే)","e":"","table":null},{"a":"2500 మంది","e":"","table":null},{"a":"మిషన్‌టూల్స్","e":"ఇది హైదరాబాద్‌లో ఉంది.","table":null},{"a":"1924, రూ.61 లక్షలు","e":"","table":null},{"a":"1100 మంది","e":"","table":null},{"a":"4","e":"","table":null},{"a":"వజీర్ సుల్తాన్ టొబాకో కంపెనీ","e":"ఇది చార్మినార్ సిగరెట్లను తయారుచేసే కంపెనీ.","table":null},{"a":"1940","e":"","table":null},{"a":"తెలంగాణ","e":"","table":null},{"a":"గోండులు, కోయలు","e":"వీరితోపాటు చెంచులు, లంబాడీలు కూడా ముఖ్యమైనవారు.","table":null},{"a":"చేనేత పరిశ్రమ","e":"వ్యవసాయం తరువాత ఇదే ప్రధాన కుటీర పరిశ్రమ.","table":null},{"a":"30 శాతం","e":"","table":null},{"a":"1851","e":"","table":null},{"a":"తెలంగాణ అడవులు","e":"","table":null},{"a":"వెండి చెక్కడం పని","e":"","table":null},{"a":"ఆటబొమ్మలు","e":"","table":null},{"a":"సిల్క్ చీరలు","e":"","table":null},{"a":"చెక్కు చీరలు","e":"","table":null},{"a":"ఖాదీ వస్త్రాలు","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-22-mulki-kathanam', 'telangana-history-te', 22, 'ముల్కీ కథనం', '[{"a":"ఆఫాఖీలు, ఆరబ్బీలు, ఇరానీయులు","e":"బహమనీ సుల్తానుల పరిపాలనలో దక్కనుకు కొత్తగా వచ్చిన ఈ వర్గాల వారికి సుల్తానులు గొప్ప ఉద్యోగాలిచ్చారు.","table":null},{"a":"సూఫీ మతం","e":"వీరు ఇస్లాంలోని సాత్విక మత ధోరణికి ప్రతినిధులు.","table":null},{"a":"సున్నీలు","e":"","table":null},{"a":"బీదర్‌నగరం","e":"","table":null},{"a":"ఖాజీ మహమ్మద్ గవాన్","e":"హత్య జరిగే నాటికి ఆయన వయసు 78 సంవత్సరాలు, ఈ హత్యతో బహమనీ రాజ్యం శిథిలమైపోయింది.","table":null},{"a":"కుతుబ్‌షాహీలు","e":"వీరు పదునారవ శతాబ్ది తుదినుంచి పదునేడవ శతాబ్ది తుదివరకు పాలించారు.","table":null},{"a":"కులీ కుతుబ్‌షా","e":"ఆయన ఇరాన్‌లోని హమ్దాన్ రాజవంశానికి చెందినవాడు.","table":null},{"a":"అబ్దుల్ హసన్ తానీషా","e":"","table":null},{"a":"సూర్యప్రకాశరావు","e":"","table":null},{"a":"మాదన్న నియామకం","e":"మాదన్నను ప్రధానిగా నియమించడం ఈ కాలంలో మొదటిసారి జరిగింది.","table":null},{"a":"రెవిన్యూ శాఖ","e":"","table":null},{"a":"ముల్కీ నాన్‌ముల్కీల గొడవలు","e":"మాదన్న హత్యతో కుతుబ్‌షాహీ రాజ్యం పునాదులు కదిలాయి.","table":null},{"a":"ముస్లింలు, ఉర్దూభాష మాట్లాడే కాయస్థులు","e":"వీరు నిజాంకు విశ్వాసపాత్రులు, వీరికి పెద్ద పదవులు లభించాయి.","table":null},{"a":"మీర్ ఆలమ్, చందూలాల్, ఇమాదుల్ ముల్క్","e":"వీరు ముఖ్యులైన ఉత్తరాది వారు.","table":null},{"a":"కర్నాటక, ఉత్తర సర్కారులు, రాయలసీమ, బిరార్","e":"ఈ ప్రాంతాలు బ్రిటిష్ రాజ్యంలో కలిసిపోగానే అక్కడివారికి నిజాం ఇచ్చిన జాగీర్లు, సౌకర్యాలు రద్దయ్యాయి.","table":{"headers":["క్రమసంఖ్య","ప్రాంతం"],"rows":[["1","కర్నాటక"],["2","ఉత్తర సర్కారులు"],["3","రాయలసీమ"],["4","బిరార్"]],"unit":"బ్రిటిష్‌లో కలిసిన నిజాం రాష్ట్ర ప్రాంతాలు"}},{"a":"దేశద్రోహులు","e":"","table":null},{"a":"మొగల్ చక్రవర్తి","e":"","table":null},{"a":"వైద్యం, గుత్తేదారు, వ్యాపారం","e":"","table":null},{"a":"అఫ్జలుద్దౌలాబహదూర్","e":"","table":null},{"a":"సాలార్‌జంగ్ (మెదటి)","e":"","table":null},{"a":"ముఖ్యమైన ఉద్యోగాల నియామకం","e":"దీనితో సాలార్‌జంగ్ రాజీనామాకు సిద్ధమయ్యాడు.","table":null},{"a":"ఒక ఫకీరు","e":"నిజాంకు ఫకీర్ల పట్ల మక్కువ ఎక్కువ; తనవైపు తిప్పుకోడానికి ఫకీరుకు లంచమిచ్చారు.","table":null},{"a":"సాలార్‌జంగ్ చెప్పిన వ్యక్తినే","e":"దీనితో సాలార్‌జంగ్ కూడా నిజాం అభిమానం పొందాడు, అయినా అధికారుల మధ్య మనస్పర్థలు మొదలయ్యాయి.","table":null},{"a":"మీర్ మహబూబ్ అలీఖాన్ బహదూర్","e":"","table":null},{"a":"1880","e":"","table":null},{"a":"ఉత్తరాదివారికి","e":"ఇది ఉత్తరాదివారి ప్రవేశానికి మార్గం సులభం చేసింది.","table":null},{"a":"స్థానికులు (ఇక్కడివారు)","e":"","table":null},{"a":"బయటివారి సంఖ్య","e":"దీనిపై 1886లో రాష్ట్రోద్యోగుల సివిల్ లిస్ట్ మొదటిసారి విడుదలైంది.","table":null},{"a":"476","e":"హైదరాబాద్ రాష్ట్రం నుంచి 246 (52%), బ్రిటిష్ ఇండియా నుంచి 230 (48%) మంది ఉద్యోగులు ఉన్నారు.","table":{"headers":["పుట్టిన స్థలం","ఉద్యోగులసంఖ్య","శాతం","వేతన విభాగం"],"rows":[["హైదరాబాద్ రాష్ట్రం","246","52","42"],["బ్రిటిష్ ఇండియా","230","48","58"],["మద్రాసు, బొంబాయి (ప్రెసిడెన్సీలు మినహాయించి)","97","20","24"],["మద్రాసు ప్రెసిడెన్సీ","66","14","11"],["బొంబాయి ప్రెసిడెన్సీ","36","8","8"],["ఇతర యూరప్ దేశాలు","24","5","13"]],"unit":"1886 సంవత్సరపు ఉద్యోగుల సివిల్ లిస్టు (బ్రిటిష్ ఇండియా వారి వర్గీకరణ)"}},{"a":"42 శాతం","e":"మిగతా 58 శాతం వేతనం బ్రిటిష్ ఇండియా నుంచి వచ్చినవారికి లభించింది.","table":null},{"a":"హైదరాబాద్ సివిల్ సర్వీస్","e":"","table":null},{"a":"ఉద్యోగాలు స్థానికులకే ఇవ్వాలి","e":"విదేశీయుల అవసరం ఉంటే ప్రధానమంత్రి అనుమతి తీసుకోవాలని ఈ జరీదా పేర్కొంది.","table":null},{"a":"పుట్టుక లేదా వివాహం లేదా 15 ఏళ్ల నివాసం","e":"నిజాం రాష్ట్రంలో పుట్టి ఉండాలి, లేదా ఇక్కడి వ్యక్తిని వివాహం చేసుకుని ఉండాలి, లేదా పదిహేను సంవత్సరాలు నిజాం రాజ్యంలో నివాసంగా ఉండాలి.","table":null},{"a":"రాష్ట్రంలో ఉద్యోగం చేయడానికి నిబంధన","e":"ఏదో విధంగా ముల్కీ సర్టిఫికెట్లు సంపాదించి చాలామంది ఉద్యోగులుగా, ఉపాధ్యాయులుగా వచ్చారు.","table":null},{"a":"ముల్కీ ఉద్యమం","e":"","table":null},{"a":"రాష్ట్ర ప్రధాని","e":"సర్ అక్బర్ హైదరీ రాష్ట్ర ప్రధానిగా ఉన్నప్పుడు, అంతకుముందు ఆర్థికమంత్రిగా ఉన్నప్పుడు కూడా ఈ పని చేశాడు.","table":null},{"a":"తెలంగాణ","e":"హైదరాబాద్ రాష్ట్రపూర్వ విభాగాలైన మరట్వాడా, కర్ణాటకలో ఈ సమస్య లేదు.","table":null},{"a":"యూనియన్ ఉద్యోగులు","e":"","table":null},{"a":"ఇంగ్లిష్","e":"","table":null},{"a":"ప్రాంతీయ భాషలు","e":"దీనివలన ప్రాంతీయ భాషలలో బోధన చేసే ఉపాధ్యాయులు అవసరమయ్యారు.","table":null},{"a":"వృతిరేకంగా కావాలనుకున్న ప్రచారం","e":"ఈ ప్రచారం స్థానిక, స్థానికేతర ఉద్యోగుల మధ్య వ్యతిరేకభావాన్ని పెంపొందించడానికి తోడ్పడింది.","table":null},{"a":"ఒకటి","e":"బ్రిటిష్ వారి తోడ్పాటుతో నిజాం ప్రభుత్వం ఉర్దూను విశ్వవిద్యాలయ స్థాయివరకు బోధనా భాషగా చేసి అమలు జరిపింది.","table":null},{"a":"తెలుగు, మరాఠీ, కన్నడం","e":"","table":null},{"a":"ఉర్దూ","e":"దీని ఫలితంగా ఆంధ్రుల్లో విద్యావ్యాప్తి తగ్గిపోయింది.","table":null},{"a":"విశ్వకవి టాగూరు నుంచి రాజగోపాలాచారి వరకు","e":"","table":null},{"a":"కాంగ్రెస్ ప్రభుత్వం","e":"","table":null},{"a":"1940","e":"","table":null},{"a":"1941 ఏప్రిల్","e":"","table":null},{"a":"వినాయకరావు విద్యాలంకార్","e":"","table":null},{"a":"మెట్రిక్ వరకు మాతృభాషలో బోధన తదితరాలు","e":"","table":{"headers":["క్రమసంఖ్య","అంశం"],"rows":[["1","మెట్రిక్ వరకు ఎవరి మాతృభాషలో వారికి బోధన జరగాలి"],["2","మెట్రిక్ తరువాత ఉర్దూ స్థానంలో ఇంగ్లిషులో బోధన జరగాలి"],["3","హిందీ, సంస్కృతం భాషలను బోధించాలి"],["4","విద్యార్థులను వందేమాతరం పాడటానికి అనుమతించాలి"],["5","ఖాన్సీ స్కూళ్లను అడ్డుకునే గస్తీని రద్దుపరచాలి"]],"unit":"1941 సభలో ఏకగ్రీవ ఆమోదం పొందిన అంశాలు"}},{"a":"రాష్ట్రప్రభుత్వానికి","e":"","table":null},{"a":"తెలుగు, మరాఠీ, కన్నడ భాషల్లో బోధన తదితరాలు","e":"","table":{"headers":["క్రమసంఖ్య","అంశం"],"rows":[["1","తెలుగు, మరాఠీ, కన్నడ భాషలలో బోధన జరగాలి"],["2","ఖాన్సీ పాఠశాలలను నిషేధించే ఉత్తరువులను ఉపసంహరించుకోవాలి"],["3","హిందూ బాలికలకు అనవసరమైన ఉర్దూలో బోధన జరుగరాదు"],["4","ప్రాథమిక విద్యను ఉచితంగా, నిర్బంధంగా అమలు జరపాలి"],["5","పాఠ్యగ్రంథాల రచనలో ప్రజామండలి ప్రతినిధులకు అవకాశం ఇవ్వాలి"],["6","ప్రాంతీయ భాషలను ఆయా ప్రాంతాలలో అధికార భాషలుగా ప్రకటించాలి"]],"unit":"1941 జోషి మెమోరాండంలోని అంశాలు"}},{"a":"బూర్గుల రామకృష్ణారావు","e":"","table":null},{"a":"1944 నవంబరు 11","e":"","table":null},{"a":"ఉర్దూ మాతృభాష కాని విద్యార్థులకు ఉర్దూలో బోధన ఎంతవరకు సమంజసం అని","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-23-majlis-ittehadul-muslimeen-rajakeeyalu', 'telangana-history-te', 23, 'మజ్లిస్ ''ఇత్తెహాదుల్ ముసల్మీన్'' రాజకీయాలు', '[{"a":"యాభై సంవత్సరాల హైదరాబాద్","e":"","table":null},{"a":"1926","e":"","table":null},{"a":"జాగీర్దార్లు, మన్సబ్‌దారులు","e":"","table":null},{"a":"హైదరాబాద్","e":"","table":null},{"a":"నవాబ్ వికారుల్ ముల్క్ బహదూర్","e":"","table":null},{"a":"అలీఘర్","e":"","table":null},{"a":"హిందువుల పాలితులు","e":"","table":null},{"a":"హైదరాబాద్","e":"","table":null},{"a":"పాకిస్తాన్","e":"","table":null},{"a":"ముసల్మానులందరినీ సంఘటితపరచడం, ఆర్థికాభివృద్ధికి తోడ్పడటం, ప్రభుభక్తిపరాయణులుగా తీర్చిదిద్దడం","e":"","table":null},{"a":"మహమ్మద్ ప్రవక్త జన్మదినోత్సవం","e":"","table":null},{"a":"1938","e":"","table":null},{"a":"ఆర్యసమాజ్","e":"","table":null},{"a":"బహదూర్ యార్ జంగ్","e":"","table":null},{"a":"ఉర్దూ","e":"","table":null},{"a":"హైదరాబాద్ ప్రభుత్వం సర్వస్వాతంత్ర్యం కలిగిన రాజాధికారిగా ఉండాలి","e":"","table":null},{"a":"ముస్లింలు","e":"","table":null},{"a":"బోధనాభాషగా, రాజభాషగా","e":"","table":null},{"a":"''అనిల్ మాలిక్''","e":"అంటే ''నేనే ప్రభువును'' అని అర్థం.","table":null},{"a":"అహమ్ బ్రహ్మాస్మీ","e":"","table":null},{"a":"ఉస్మాన్ అలీఖాన్","e":"","table":null},{"a":"తల్లీగ్","e":"","table":null},{"a":"బహదూర్ యార్ జంగ్","e":"","table":null},{"a":"20 వేల మంది","e":"","table":null},{"a":"88.9 శాతం","e":"","table":null},{"a":"84 శాతం","e":"","table":null},{"a":"శుద్ధి సంఘటన","e":"","table":null},{"a":"ఇనాయతుల్లా మష్రికీ","e":"","table":null},{"a":"బహదూర్ యార్ జంగ్","e":"","table":null},{"a":"కాక్సార్ ఉద్యమ నాయకత్వం","e":"","table":null},{"a":"మజ్లిస్ సంస్థ","e":"","table":null},{"a":"అయ్యంగార్ కమిటీ","e":"","table":null},{"a":"1939; సర్ అక్బర్ హైదరీ","e":"సర్ అక్బర్ హైదరీ నాటి సంస్థాన ప్రధాని.","table":null},{"a":"హిందూ-ముస్లిం లిద్దరికీ సమాన ప్రతిపత్తి కల్పించడం","e":"","table":null},{"a":"మజ్లిస్‌కు","e":"","table":null},{"a":"''హిజ్ మెజెస్టీ'' బిరుదు","e":"","table":null},{"a":"ముసల్మానులు","e":"","table":null},{"a":"ప్రత్యేక దేశంగా ముస్లిం రాజ్యంగా","e":"","table":null},{"a":"సర్కారు, సీడెడ్ జిల్లాలు నిజాం రాష్ట్రంలో కలిసిపోయి ''ఉస్మానిస్తాన్'' ఏర్పడుతుంది","e":"","table":null},{"a":"50 కోట్ల రూపాయలు","e":"","table":null},{"a":"సావర్కర్","e":"","table":null},{"a":"రాజ్యం మొదటి నిజాం స్వంత ఆస్తికాదని, 7వ నిజాం సొంత జాగీరు కాదని","e":"","table":null},{"a":"ముస్లిం ప్రజలందరి ఆస్తి","e":"","table":null},{"a":"ఒక సంవత్సరం","e":"","table":null},{"a":"జంగ్, బహదూర్","e":"చివరికి బహదూర్ యార్ఖాన్‌గానే మిగిలిపోయాడు.","table":null},{"a":"జాగీర్దారీ కుటుంబం","e":"","table":null},{"a":"మహమ్మద్ అలీ జిన్నా","e":"","table":null},{"a":"ఉర్దూలోకి","e":"","table":null},{"a":"లక్షరూపాయలు","e":"","table":null},{"a":"చందాలు ఇవ్వలేనివారు దేశం ఎలా సంపాదించుకుంటారు","e":"","table":null},{"a":"ఆలింగనం చేసుకున్నాడు","e":"","table":null},{"a":"నలభయ్యో ఏట","e":"","table":null},{"a":"ఒక మిత్రుని ఇంట్లో హఠాత్తుగా మరణించాడు","e":"","table":null},{"a":"హత్య జరిగిందని","e":"విచారణలో ఇది వెల్లడి కాలేదు.","table":null},{"a":"''ఖాయిదె ఆజం''","e":"","table":null},{"a":"''ఖాయిద్-ఎ-మిల్లత్''","e":"","table":null},{"a":"మజ్లిస్","e":"","table":null},{"a":"మజ్లిస్ రాజకీయ సంస్థ కాదని భావించారు","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-24-arya-samaj-poratalu', 'telangana-history-te', 24, 'ఆర్యసమాజ్ పోరాటాలు', '[{"a":"బలం","e":"","table":null},{"a":"ఉత్తర హిందూస్థానం","e":"","table":null},{"a":"ఆర్యులం","e":"","table":null},{"a":"దయానంద సరస్వతి","e":"","table":null},{"a":"శ్రద్ధానందుడు","e":"","table":null},{"a":"పండిత కేశవరావు కోరాట్కర్","e":"","table":null},{"a":"హైదరాబాద్ హైకోర్టు న్యాయమూర్తి","e":"","table":null},{"a":"1932","e":"","table":null},{"a":"1921","e":"","table":null},{"a":"1923","e":"","table":null},{"a":"సిద్దీకీ దీన్‌దార్","e":"","table":null},{"a":"మంగళ్‌దేవ్, పండిత రామచంద్ర దహేళ్వీలు","e":"","table":null},{"a":"హైదరాబాద్ రాష్ట్ర శాసనసభ","e":"","table":null},{"a":"హిందూ-ముస్లిం సభ్యులు","e":"","table":null},{"a":"పండిత వినాయకరావు విద్యాలంకార్","e":"","table":null},{"a":"1932 మే 21","e":"","table":null},{"a":"పండిత వినాయకరావు విద్యాలంకార్","e":"కేశవరావు కుమారుడు.","table":null},{"a":"పండిత రామచంద్ర దహేళ్వీ, చంద్రభాను","e":"","table":null},{"a":"1934","e":"","table":null},{"a":"నారాయణస్వామి, స్వామి స్వతంత్రానంద, ఆచార్య రాందేవులు","e":"","table":null},{"a":"హవన కుండాలను, మందిరాలను","e":"","table":null},{"a":"హోంశాఖ కార్యదర్శి జువైదర్‌జంగ్","e":"","table":null},{"a":"కలెక్టరు స్వంత ఖర్చులతో మందిరాలను, హవనకుండాలను నిర్మించి పెట్టవలసిందని","e":"","table":null},{"a":"1937","e":"","table":null},{"a":"1937","e":"","table":null},{"a":"21 మంది","e":"","table":null},{"a":"ధర్మప్రకాశ్‌ను","e":"","table":null},{"a":"శ్యాంలాల్‌ను","e":"","table":null},{"a":"డిసెంబర్ 17; బీదర్ జైలు","e":"","table":null},{"a":"1932","e":"","table":null},{"a":"పండిత నరేంద్రజీని","e":"","table":null},{"a":"మన్ననూరు జైలు","e":"","table":null},{"a":"''కాలాపానీ''","e":"","table":null},{"a":"మహబూబ్‌నగర్ జిల్లా (నల్లమల అడవులలో అమరాబాద్ సమీపం)","e":"","table":null},{"a":"మూడు సంవత్సరాలు","e":"","table":null},{"a":"వాగ్బంధనం","e":"","table":null},{"a":"అఖిలభారత ఆర్యమహాసభ","e":"","table":null},{"a":"హైదరాబాద్ సమస్య",