.యం.మున్షీ","e":"","table":null},{"a":"రెండువేల రూపాయలు","e":"","table":null},{"a":"స్వల్పం","e":"","table":null},{"a":"గాంధీజీ అహింసా సిద్ధాంతం","e":"","table":null},{"a":"స్థానం","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-25-swatantryodyamalu', 'telangana-history-te', 25, 'స్వాతంత్ర్యోద్యమాలు', '[{"a":"1800వ సంవత్సరం","e":"","table":null},{"a":"1948 సెప్టెంబరు 17","e":"","table":null},{"a":"1885 నుండి 1920 వరకు","e":"","table":null},{"a":"రామచంద్ర పిళ్ళె","e":"","table":null},{"a":"సికింద్రాబాద్","e":"","table":null},{"a":"బీరార్‌ను బ్రిటిష్ ప్రభుత్వానికి శాశ్వతంగా దత్తం చేసినట్లు ఒప్పందం","e":"","table":null},{"a":"1906-07 మధ్య","e":"","table":null},{"a":"1901 నుంచి 1906 వరకు","e":"","table":null},{"a":"''హైదరాబాద్ స్వాతంత్ర్యోద్యమం'' నాల్గో సంపుటం","e":"","table":null},{"a":"హైదరాబాద్","e":"","table":null},{"a":"60 మంది","e":"","table":null},{"a":"బ్రౌన్‌గన్ ఫ్యాక్టరీ (ఆయుధాలు)","e":"","table":null},{"a":"అలీఘర్","e":"","table":null},{"a":"కాంగ్రెస్ ఖిలాఫత్ ఉద్యమాలు","e":"","table":null},{"a":"హైదరాబాద్ నిజాం, టర్కీ సుల్తాన్‌ల విడ్యం","e":"","table":null},{"a":"శౌకత్ అలీ, సర్ అక్బర్ హైదరీ","e":"","table":null},{"a":"వివాహం","e":"","table":null},{"a":"హైదరాబాద్ జిల్లా కాంగ్రెస్ సంఘం","e":"","table":null},{"a":"వామన్ నాయక్","e":"","table":null},{"a":"15 సంవత్సరాలు","e":"","table":null},{"a":"మాడపాటి హనుమంతరావు, బూర్గుల రామకృష్ణారావు, కొండా వెంకటరంగారెడ్డి","e":"","table":null},{"a":"1931; బరార్‌లోని అకోలాలో","e":"","table":null},{"a":"న్యాయమూర్తి రామచంద్ర నాయక్","e":"","table":null},{"a":"చతుర్విధోపాయాలు","e":"","table":null},{"a":"హైకోర్టు న్యాయమూర్తులుగా","e":"","table":null},{"a":"వెలుపలికి","e":"","table":null},{"a":"మహాత్మాగాంధీ","e":"","table":null},{"a":"భారత రాజ్యాంగ చట్టం","e":"","table":null},{"a":"దివాన్ బహదూర్ ఆరావముదు అయ్యంగార్","e":"","table":null},{"a":"మాడపాటి హనుమంతరావు","e":"","table":null},{"a":"హైదరాబాద్ ప్రభుత్వ రాజ్యాంగం ఆసఫియా ఛత్రచ్ఛాయలో బాధ్యతాయుత ప్రభుత్వం ఏర్పరచాలని","e":"","table":null},{"a":"వెరగొందింది, భగ్నపరచాలని దీక్షపట్టింది","e":"","table":null},{"a":"బహదూర్ యార్‌జంగ్","e":"","table":null},{"a":"సగం ముస్లింలకీయలని, అంజుమన్ ఇత్తెహాదుల్ ముసల్మీన్‌ను ఏకైక ముస్లిం సంస్థగా","e":"","table":null},{"a":"లేదు","e":"బాధ్యతాయుత ప్రభుత్వానికి ఎదురు తిరిగారు.","table":null},{"a":"విచ్ఛిత్తి అయింది","e":"","table":null},{"a":"ఒక రాజకీయ వేదిక ఉండాలనే అభిప్రాయం","e":"","table":null},{"a":"మైసూరు సంస్థానం","e":"","table":null},{"a":"1938 జనవరి 29","e":"","table":null},{"a":"1938 ఆగస్టు నెల","e":"","table":null},{"a":"1938 ఆగస్టు 23","e":"","table":null},{"a":"(నిషేధం తర్వాత)","e":"","table":null},{"a":"1938 అక్టోబరు 24","e":"","table":null},{"a":"రామకృష్ణ ధూత్, జానార్దనరావు దేశాయి, రావి నారాయణరెడ్డి, శ్రీనివాసరావు బోరీకర్","e":"","table":null},{"a":"స్వర్ణాక్షరాలతో లిఖించదగిన ఘట్టం","e":"","table":null},{"a":"మారిపోయింది","e":"","table":null},{"a":"మైసూరు, తిరువాన్కూరు, రాజ్‌కోట సంస్థానాలు","e":"","table":null},{"a":"ఆర్యసమాజం, హిందూమహాసభ","e":"","table":null},{"a":"త్రిరూప ఉద్యమం","e":"","table":null},{"a":"రెండు నెలలు","e":"","table":null},{"a":"స్వామీ రామానందతీర్థ","e":"","table":null},{"a":"స్వదేశీ ఉద్యమం","e":"","table":null},{"a":"ఉస్మానియా విశ్వవిద్యాలయం ''బి'' హాస్టల్","e":"","table":null},{"a":"వందేమాతరం గీతం రాజకీయాలకు సంబంధించినదని, విద్యార్థులు రాజకీయాలతో సంబంధం పెట్టుకోకూడదని","e":"","table":null},{"a":"మౌలానా నజీరుల్ హసన్ జీలానీ","e":"","table":null},{"a":"22 కోట్ల మంది","e":"","table":null},{"a":"వందేమాతరం చదువువద్దని ఉత్తర్వులు","e":"","table":null},{"a":"హిందూ విద్యార్థులందరినీ","e":"","table":null},{"a":"స్వర్గీయ పి.వి.నరసింహారావు","e":"","table":null},{"a":"అచ్యుతరెడ్డి, నూకల రామచంద్రారెడ్డి, సర్వదేవభట్ల రామనాథం, ఎస్.చెన్నారెడ్డి","e":"","table":null},{"a":"విద్యార్థుల ప్రతినిధివర్గం","e":"","table":null},{"a":"ఆంధ్ర యూనివర్సిటీ, బనారస్ యూనివర్సిటీ","e":"","table":null},{"a":"వైస్ చాన్సలర్ కేదార్","e":"","table":null},{"a":"రెండు మూడు నెలలు","e":"","table":null},{"a":"నాగ్‌పూర్ (సైన్స్), జబల్‌పూర్ (ఆర్ట్స్)","e":"","table":null},{"a":"పండిట్ జవహర్‌లాల్ నెహ్రూ, సుభాష్ చంద్రబోస్","e":"","table":null},{"a":"గాంధీజీ","e":"","table":null},{"a":"పౌరహక్కుల సాధనకోసం","e":"","table":null},{"a":"వందేమాతరం గీతాలాపనను నిషేధించింది","e":"","table":null},{"a":"రెండు మూడు రోజుల తరువాత","e":"","table":null},{"a":"పన్నెండు కొరడా దెబ్బలు","e":"","table":null},{"a":"రామచంద్రరావు","e":"","table":null},{"a":"ఒక్కొక్క కొరడా దెబ్బ (వందేమాతరం అంటూ ఉంటే)","e":"","table":null},{"a":"ఆహారం తీసుకోవడం మానివేసి నిరాహారదీక్ష చేపట్టారు","e":"","table":null},{"a":"ప్రతిరోజు సాయంత్రం పూట ఒక్కసారి వందేమాతరం సామూహికంగా పాడుకోవచ్చని","e":"","table":null},{"a":"''వందేమాతరం రామచంద్రరావు''","e":"","table":null},{"a":"గోవిందరావు నానల్","e":"","table":null},{"a":"కొన్ని హామీలు","e":"","table":null},{"a":"''ఆనందమఠ్''","e":"","table":null},{"a":"బ్రిటిష్ ప్రభుత్వం మీద తిరుగుబాటు చేసిన ఒక సన్యాసుల మరణ కథ","e":"","table":null},{"a":"బంకించంద్ర ఛటర్జీ","e":"","table":null},{"a":"బెంగాల్","e":"","table":null},{"a":"దా. రాజేంద్ర ప్రసాద్","e":"","table":null},{"a":"''జనగణమన'' గీతం","e":"","table":null},{"a":"''జనగణమన'' గీతంతో సమానంగా","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-26-telangana-sayudha-poratam', 'telangana-history-te', 26, 'తెలంగాణా సాయుధ పోరాటం', '[{"a":"1938","e":"","table":null},{"a":"రావి నారాయణరెడ్డి","e":"","table":null},{"a":"-","e":"మొదటి చర్చావేదికలో రావి నారాయణరెడ్డి, మక్దూం మొహియుద్దీన్, రాజ్‌బహదూర్ గౌర్, సయ్యద్ ఇబ్రహీం, ఆలం ఖుంద్మేరి సభ్యులుగా ఉన్నారు.","table":null},{"a":"కాశీనాధరావు వైద్య","e":"","table":null},{"a":"సయ్యద్ ఇబ్రహీం","e":"","table":null},{"a":"హిందూ-ముస్లిం ఐక్యత, కులమత తత్త్వ నిర్మూలన","e":"","table":null},{"a":"కామ్రేడ్స్ అసోసియేషన్","e":"","table":null},{"a":"మహాసభ చీలిక","e":"రెండు వేర్వేరు ఆంధ్ర మహాసభలు ఏర్పడ్డాయి.","table":null},{"a":"హైదరాబాద్ స్టేట్ కాంగ్రెస్","e":"","table":null},{"a":"సెప్టెంబరు 17, 1947","e":"","table":null},{"a":"నిర్బంధ ధాన్య సేకరణ","e":"మార్కెట్ ధర కన్నా తక్కువ ధరకు రైతుల నుండి ధాన్యం సేకరించారు.","table":null},{"a":"కడివెండి","e":"","table":null},{"a":"పద్మజానాయుడు","e":"","table":null},{"a":"70 మంది","e":"","table":null},{"a":"36 మంది","e":"","table":null},{"a":"ప్రభుత్వం, గ్రామ పెత్తందార్లు","e":"","table":null},{"a":"పెత్తందార్లను ఎదిరించడం ద్వారా","e":"","table":null},{"a":"ఆగ్నేయాసియా యువజన మహాసభ","e":"","table":null},{"a":"ప్రపంచ కమ్యూనిస్టు యువజన సంస్థ","e":"","table":null},{"a":"చీనా, బర్మా, మలయా, ఇండోనీషియా","e":"","table":null},{"a":"బి.టి.రణదివే","e":"","table":null},{"a":"సోవియట్ విధానం","e":"","table":null},{"a":"బొంబాయి ప్రావిన్సు గవర్నర్","e":"1857 ప్రథమ స్వాతంత్ర్య పోరాట సమయంలో ఈ హెచ్చరిక చేశారు.","table":null},{"a":"పోలీసు, సైనిక ప్రత్యేక దళాలు","e":"","table":null},{"a":"200 మంది","e":"","table":null},{"a":"22","e":"","table":null},{"a":"మే 4, 1948","e":"","table":null},{"a":"ఎస్.ఏ.దాంగే, అజయ్ ఘోష్, రాజేశ్వరరావు, బసవపున్నయ్య","e":"","table":null},{"a":"సతీంద్రసింగ్","e":"","table":null},{"a":"రణదివే","e":"","table":null},{"a":"ఫతేమైదాన్","e":"","table":null},{"a":"50 వేల మంది","e":"","table":null},{"a":"4000 మంది","e":"","table":null},{"a":"1951","e":"","table":null},{"a":"ఎన్నికల తరుణంలో","e":"","table":null},{"a":"ఆచార్య వినోబాభావే","e":"","table":null},{"a":"ఆంధ్ర నాయకుడు","e":"","table":null},{"a":"పీపుల్స్ డెమోక్రటిక్ ఫ్రంట్ (PDF)","e":"","table":null},{"a":"విస్మయకరమైన విజయాలు","e":"","table":null},{"a":"రాత్రి కమ్యూనిస్టుల అధికారం, పగలు ప్రభుత్వాధికారం","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-27-socialist-party-poratalu', 'telangana-history-te', 27, 'సోషలిస్టు పార్టీ పోరాటాలు', '[{"a":"1934","e":"నాసిక్ జైల్లో నిర్బంధంలో ఉన్న యువకులు ఈ నిర్ణయానికి వచ్చారు.","table":null},{"a":"నాసిక్ జైలు","e":"","table":null},{"a":"1934 మే 17","e":"","table":null},{"a":"పాట్నా, అంజుమన్-ఎ-ఇస్లామియా హాల్","e":"","table":null},{"a":"ఆచార్య నరేంద్రదేవ్","e":"","table":null},{"a":"జైప్రకాశ్ నారాయణ్, యూసఫ్ మెహరలీ తదితరులు","e":"వీరితోపాటు అచ్యుత పట్వర్ధన్, అశోక్ మెహతా, మీనుమాసాని, ఎన్.ఎం.జోషి, ఎన్.జి.గోరే, దంతల్వాలు ఉన్నారు.","table":null},{"a":"రామ్ మనోహర్ లోహియా, పురుషోత్తమదాస్ త్రికందాస్, గంగాశరణ్ సిన్హా తదితరులు","e":"","table":null},{"a":"కమ్యూనిస్టుల శ్రామిక నియంత్రుత్వాన్ని ఎదిరించడం","e":"","table":null},{"a":"వెనుకబడిన వర్గాల ఆర్థికాభివృద్ధికి","e":"","table":null},{"a":"కర్షక, కార్మిక సంక్షేమ పథకాలు","e":"","table":null},{"a":"నష్టపరిహారం లేకుండా స్వాధీనం చేసుకోవడం","e":"","table":null},{"a":"సంస్థానాలు, రాజరికాలు","e":"","table":null},{"a":"రుణ విముక్తి","e":"","table":null},{"a":"బీమా కంపెనీలు, భారీ పరిశ్రమలు","e":"","table":null},{"a":"రైతు సమస్యల పరిష్కారంలో నిర్లక్ష్యం","e":"","table":null},{"a":"సుభాష్ చంద్రబోస్","e":"","table":null},{"a":"1938","e":"","table":null},{"a":"రైతు సమస్యలు","e":"","table":null},{"a":"వ్యష్టి సత్యాగ్రహం","e":"","table":null},{"a":"క్విట్ ఇండియా ఉద్యమం","e":"","table":null},{"a":"1936","e":"","table":null},{"a":"1940","e":"","table":null},{"a":"కమ్యూనిస్టు కరపత్రం","e":"సొంత పార్టీ లేదని, మరో లేబుల్ వద్దని కమ్యూనిస్టులు పంచిన కరపత్రంపై వాదోపవాదాలు జరిగాయి.","table":null},{"a":"లోహియా, అచ్యుత పట్వర్ధన్","e":"","table":null},{"a":"గెరిల్లా పద్ధతి","e":"","table":null},{"a":"ఒకరోజు ఉపవాస వ్రతం","e":"","table":null},{"a":"కాన్పూర్ సమావేశం","e":"","table":null},{"a":"1947 ఫిబ్రవరి","e":"","table":null},{"a":"అశోక్ మెహతా, ఎన్.జి.గోరే","e":"","table":null},{"a":"శ్రీమతి అరుణా అసఫ్ అలీ","e":"","table":null},{"a":"నిజాం ప్రజాభీష్టానికి వ్యతిరేకంగా ప్రవర్తిస్తే గతి పట్టిన బ్రిటిష్ వారికి పట్టిన గతే","e":"","table":null},{"a":"అరెస్టు చేసి జైల్లో పెట్టాలి","e":"","table":null},{"a":"1947 మే 7","e":"","table":null},{"a":"మీర్ జాఫర్","e":"","table":null},{"a":"మహదేవ్ సింగ్","e":"జైప్రకాశ్ నారాయణ్ మహదేవ్ సింగ్ ఇంట్లో నిద్రిస్తుండగా నగర బహిష్కరణ ఉత్తర్వులు అందజేశారు.","table":null},{"a":"బొంబాయి","e":"ప్రత్యేక విమానంలో తరలించారు.","table":null},{"a":"స్వేచ్ఛ","e":"","table":null},{"a":"శివరామశాస్త్రి, జె.ఆర్.గోపాలరావు, రాఘవరెడ్డి తదితరులు","e":"","table":null},{"a":"1947 జులై 3","e":"","table":null},{"a":"పదిహేనువేల మంది","e":"సుల్తాన్‌బజార్ క్లాక్‌టవర్ వద్ద ఊరేగింపు జరిపారు.","table":null},{"a":"హైదరాబాద్ విద్యార్థి దినోత్సవం","e":"","table":null},{"a":"బి.ఎస్.మహదేవ్ సింగ్","e":"","table":null},{"a":"హింద్-కిసాన్ పంచాయత్‌రాజ్, హింద్‌మజ్దూర్ సభ","e":"","table":null},{"a":"ఎస్.బి.గిరి","e":"","table":null},{"a":"11","e":"","table":null},{"a":"హైదరాబాద్, సికింద్రాబాద్ నగరాలు, కరీంనగర్ జిల్లా, కర్ణాటకలోని బీదర్ జిల్లా","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-28-telanganalo-gandhiji-paryatanalu', 'telangana-history-te', 28, 'తెలంగాణాలో గాంధీజీ పర్యటనలు', '[{"a":"1929 ఏప్రిల్","e":"","table":null},{"a":"7 జూన్ 1928","e":"","table":null},{"a":"ఖాదీ ఉద్యమం","e":"","table":null},{"a":"మైసూరు సంస్థానం","e":"","table":null},{"a":"కృష్ణస్వామి ముదిరాజ్","e":"తన ఆంధ్ర వాలంటీరు కార్‌ని వాడి మహాత్మునికి స్వాగతం పలికారు.","table":null},{"a":"నాంపల్లి స్టేషను","e":"","table":null},{"a":"వివేకవర్ధనీ మైదానం","e":"","table":null},{"a":"వామన్ నాయక్","e":"","table":null},{"a":"వామన్ నాయక్, మాడపాటి హనుమంతరావు, మందుముల నరసింగరావు తదితరులు","e":"","table":null},{"a":"రాట్నము, కామధేనువు","e":"","table":null},{"a":"మంచి అవకాశం","e":"మరింత అభివృద్ధి పరిస్తే భారతదేశంలోని ఇతర ప్రజలకు సహాయం అందించే స్థితిలో ఉన్నారని అన్నారు.","table":null},{"a":"మడ్యపానం","e":"","table":null},{"a":"2 వేల రూపాయలు","e":"","table":null},{"a":"100 రూపాయలు","e":"","table":null},{"a":"దరిద్రనారాయణుడు","e":"","table":null},{"a":"ఒక లక్షమంది","e":"","table":null},{"a":"5, 6 మైళ్ళు","e":"","table":null},{"a":"బర్మా","e":"","table":null},{"a":"హిందూమతానికే కళంకం","e":"","table":null},{"a":"హరిజనులు","e":"","table":null},{"a":"12 వేల రూపాయలు","e":"","table":null},{"a":"కృష్ణస్వామి ముదిరాజ్","e":"","table":null},{"a":"చుడీబజార్","e":"","table":null},{"a":"ప్రేం థియేటర్, సుల్తాన్ బజారు","e":"","table":null},{"a":"రాత్రి 9-15 నిమిషాలు","e":"","table":null},{"a":"1934 మార్చి 9","e":"","table":null},{"a":"సరోజినీ నాయుడు","e":"","table":null},{"a":"రావు నారాయణరెడ్డి","e":"","table":null},{"a":"రావు నారాయణరెడ్డి, ఎల్.ఆర్.దాచా, బసంతరావు, కుమారి పద్మజానాయుడు","e":"","table":null},{"a":"వికారాబాద్ స్టేషను","e":"","table":null},{"a":"లింగంపల్లి","e":"","table":null},{"a":"సరోజినీ నాయుడు","e":"","table":null},{"a":"ఖద్దరు నూలు హారం","e":"","table":null},{"a":"గోల్డన్ థ్రెషోల్డ్","e":"","table":null},{"a":"ఆబిడ్స్","e":"","table":null},{"a":"మీరా బెహన్","e":"","table":null},{"a":"రెండణాల చేతికడియం","e":"","table":null},{"a":"లోకరక్షక","e":"","table":null},{"a":"కొత్వాల్ వెంకటరామారెడ్డి","e":"","table":null},{"a":"ఆదిహిందూ విద్యాలయం","e":"","table":null},{"a":"అనుమతించలేదు","e":"గాంధీజీ అలసిపోయి ఉన్నందున కార్యక్రమాలు రద్దయి, ఆ తరువాత జరుగవలసిన కార్యక్రమాలకు ప్రభుత్వం అనుమతించలేదు.","table":null},{"a":"హరిజన సేవక సంఘం","e":"","table":null},{"a":"వామన్ నాయక్","e":"","table":null},{"a":"1630 రూపాయలు","e":"","table":null},{"a":"75 రూపాయలు","e":"","table":null},{"a":"100 రూపాయలు","e":"","table":null},{"a":"150 రూపాయలు","e":"","table":null},{"a":"సికింద్రాబాద్ కర్బలా మైదానం","e":"","table":null},{"a":"బాజీకృష్టారావు","e":"","table":null},{"a":"పనస సూక్తం","e":"","table":null},{"a":"హరిజనులని నేననుకోను","e":"","table":null},{"a":"డా. లతీఫ్ సయ్యద్","e":"","table":null},{"a":"ఆర్.ఎస్. నాయక్","e":"","table":null},{"a":"15 నిమిషాలు","e":"","table":null},{"a":"వామన్ నాయక్, సరోజినీనాయుడు, పద్మజానాయుడు","e":"","table":null},{"a":"225 రూపాయలు","e":"","table":null},{"a":"రావి నారాయణరెడ్డిగారు","e":"","table":null},{"a":"10 వేలవరకు","e":"","table":null},{"a":"మామిడి చెట్టు","e":"","table":null},{"a":"గోల్డన్ థ్రెషోల్డ్","e":"తన జ్ఞాపకార్థం ఈ మొక్కను తీసుకువచ్చి నాటారు.","table":null},{"a":"దక్షిణ భారత హిందీ ప్రచార సభ రజతోత్సవాలు","e":"1946 జనవరి చివరివారంలో ఈ రజతోత్సవాల్లో పాల్గొనడానికి మద్రాసు వెళ్ళవలసి వచ్చింది.","table":null},{"a":"ఖాజీపేట మార్గం","e":"","table":null},{"a":"ఆంధ్ర మహాసభ","e":"","table":null},{"a":"ఎం.ఎస్. రాజలింగం","e":"","table":null},{"a":"గొల్లపూడి సీతారామశాస్త్రి","e":"","table":null},{"a":"ముస్లిం మతోన్మాదులు, కమ్యూనిస్టుల దురాగతాలు","e":"","table":null},{"a":"స్పెషల్ రైలు","e":"","table":null},{"a":"మధిర, మానుకోట, దోర్నకల్","e":"","table":null},{"a":"స్వామి రామానంద తీర్థ","e":"","table":null},{"a":"ప్రత్యేక కార్యకర్తను పంపారు","e":"","table":null},{"a":"గెల్లా కేశవరావు","e":"","table":null},{"a":"సుగ్గుల అక్షయ లింగ గుప్తా","e":"","table":null},{"a":"వెంకటగిరి లెవల్ క్రాసింగ్ గేటు వద్ద","e":"","table":null},{"a":"జమలాపురం కేశవరావు","e":"","table":null},{"a":"15 అడుగులు","e":"","table":null},{"a":"1500 రూపాయలు","e":"","table":null},{"a":"8-30 నిమిషాలు","e":"","table":null},{"a":"కృష్ణబజాజ్, ఉన్నవ రాజగోపాల కృష్ణయ్య, ఎం.ఎస్. రాజలింగం","e":"","table":null},{"a":"వెండి పళ్ళెంలో పోసి","e":"","table":null},{"a":"ఈ వెండి పళ్ళెం కూడా నాదేనా","e":"","table":null},{"a":"ఖాదీ వస్త్రాలు ధరించాలి, రాట్నం వడకాలి","e":"","table":null},{"a":"సుమారు ఏడువందల మంది","e":"","table":null},{"a":"4000 రూపాయలు","e":"","table":null},{"a":"400 మంది","e":"","table":null},{"a":"2000 రూపాయలు","e":"","table":null},{"a":"15 నిమిషాలు","e":"","table":null},{"a":"800 మంది","e":"","table":null},{"a":"700 రూపాయలు","e":"","table":null},{"a":"1946 ఫిబ్రవరి 5","e":"","table":null},{"a":"800 మంది","e":"వరంగల్, హన్మకొండ, విద్యార్థి సంఘాల వాలంటీర్లు.","table":null},{"a":"గూడ్సు స్టేషను పక్కన","e":"","table":null},{"a":"ఉదయం 9 గంటల 20 నిమిషాలు","e":"","table":null},{"a":"మధ్యాహ్నం 12-20 గంటలు","e":"","table":null},{"a":"కొందరు స్త్రీలు బంగారు ఆభరణాలు ఇచ్చారు","e":"","table":null},{"a":"టి. హయగ్రీవాచారి","e":"","table":null},{"a":"ఎం.ఎస్.రాజలింగం, భండారు చంద్రమౌళీశ్వరరావు, ఎస్.శ్రీరాములు నాయుడు, ఎస్.చంద్రమౌళి, బి.రంగనాయకులు","e":"","table":null},{"a":"15,000 రూపాయలు","e":"","table":null},{"a":"5000 రూపాయలు","e":"","table":null},{"a":"మందహాసంతో నుదుటు తిలకం","e":"","table":null},{"a":"12-30 గంటలు","e":"","table":null},{"a":"పవిత్రమైనది","e":"","table":null},{"a":"పది నిమిషాలు","e":"","table":null},{"a":"హయగ్రీవాచారి, రాజలింగం తదితరులు","e":"","table":null},{"a":"స్టేషను మాస్టర్","e":"","table":null},{"a":"బక్కెట్టు అడిగి తీసుకొని నీళ్ళు స్టేషనులోని బాత్‌రూంలో పెట్టించారు","e":"","table":null},{"a":"1946","e":"","table":null},{"a":"నిజాం రాష్ట్రం","e":"","table":null},{"a":"ఆంధ్రులకు","e":"","table":null},{"a":"దేవాలయాలు","e":"","table":null},{"a":"జాతీయ సమైక్యత","e":"","table":null},{"a":"హిందుస్థానీ","e":"","table":null},{"a":"దేవనాగరి, ఉర్దూ లిపులు","e":"","table":null},{"a":"5-2-1946, ఖాజీపేట","e":"","table":null}]') ON CONFLICT(chapter_sl