INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-3-vishnukundinulu', 'telangana-history-te', 3, 'విష్ణుకుండినులు', '[{"a":"మహారాజేంద్రవర్మ కృష్ణానంది","e":"ఇక్ష్వాకుల సామంతుడిగా లేదా మండలికునిగా ఉన్న ఈ శకకర్త విష్ణుకుండిన రాజ్యాన్ని నెలకొల్పాడు.","table":null},{"a":"నల్లగొండ, మహబూబ్‌నగర్ మండలాలు","e":"","table":null},{"a":"మాధవవర్మ","e":"ఈయన వాకాటక రాజకుమార్తెను వివాహం చేసుకొని తన రాజ్యాన్ని సురక్షితపరచుకున్నాడు.","table":null},{"a":"వాకాటక వంశం","e":"","table":null},{"a":"నాలుగవ శతాబ్ది ఉత్తరార్ధం నుండి ఐదవ శతాబ్ది పూర్వార్ధం వరకు","e":"","table":null},{"a":"ఇంద్రపురి (ఇంద్రపాల నగరం)","e":"ఇది మూసీనది ఒడ్డున ఉండేది.","table":null},{"a":"తుమ్మలగూడెం","e":"","table":null},{"a":"నల్లగొండ జిల్లా, రామన్నపేట మండలానికి 6 కి.మీ.","e":"","table":null},{"a":"బౌద్ధం","e":"","table":null},{"a":"వైదిక మతం","e":"","table":null},{"a":"సంస్కృతం","e":"వ్యావహారిక భాషగా తెలుగు వాడుకలో ఉండేది.","table":null},{"a":"పన్నెండుగురు","e":"","table":null},{"a":"260 సంవత్సరాలు","e":"","table":null},{"a":"లంఘించు సింహం","e":"","table":null},{"a":"సాంస్కృతిక చరిత్ర","e":"","table":null},{"a":"వాకాటక చక్రవర్తులు","e":"","table":null},{"a":"కళింగాధిపతులు","e":"","table":null},{"a":"యజ్ఞాలు, విద్యార్థులైన విప్రుల పోషణ, వేదవిద్యల ఆదరణ","e":"","table":null},{"a":"బౌద్ధ, జైనమతాలు","e":"","table":null},{"a":"చక్కని న్యాయ వ్యవస్థ","e":"","table":null},{"a":"సంస్కృత భాష","e":"","table":null},{"a":"ప్రాకృతం","e":"","table":null},{"a":"నౌకాయానం, విదేశవర్తకం","e":"సాంస్కృతిక వ్యాప్తికి, వలస స్థాపనకు ప్రాచ్యదేశాలతో సంబంధాలు ఏర్పడ్డాయి.","table":null},{"a":"స్తూపాలు, చైత్యాలు, విహారాలు, సంఘారామాలు","e":"","table":null},{"a":"విష్ణుకుండినులు","e":"","table":null},{"a":"విష్ణుగ్రహస్వామి ఆలయం","e":"","table":null},{"a":"చిత్రరథస్వామి ఆలయం","e":"","table":null},{"a":"శిలలతో మలచిన ఆలయాలు","e":"","table":null},{"a":"శాలంకాయనులు, బృహత్పలాయనులు, ఆనంద గోత్రీకులు","e":"వీరిలో ఏ ఒక్కరూ రెండు జిల్లాలను మించి పాలించలేదు.","table":null},{"a":"సముద్రతీరం వరకు","e":"","table":null},{"a":"వైదిక మతం","e":"","table":null},{"a":"పూర్తిగా క్షీణించింది","e":"","table":null},{"a":"బౌద్ధ సంస్కృతి నుండి హిందూ సంస్కృతికి మారడం","e":"","table":null},{"a":"విష్ణుకుండినుల యుగం","e":"తరువాత వచ్చిన రాజవంశాల కాలంలో కులాల సంఖ్య పెరుగుతూ వచ్చింది.","table":null},{"a":"లంఘించు సింహం.","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-30-paritala-praja-udyamam', 'telangana-history-te', 30, 'పరిటాల ప్రజా ఉద్యమం', '[{"a":"దౌర్జన్యం, హింసాకాండ లేకుండా","e":"","table":null},{"a":"ఏడు గ్రామాలు","e":"","table":null},{"a":"''ఆన్‌క్లేవ్స్''","e":"","table":null},{"a":"చాలా ఉండేవి","e":"","table":null},{"a":"ఒక చట్టం","e":"ఏ రాష్ట్రానికి సమీపమో నిర్ణయించి బొంబాయిలో కొన్ని, మద్రాసులో కొన్ని కలిపేశారు.","table":null},{"a":"హైదరాబాద్ రాష్ట్రం","e":"","table":null},{"a":"వరంగల్ జిల్లా మధిర తాలూకా, కృష్టాజిల్లా సరిహద్దులు","e":"","table":null},{"a":"కృష్టాజిల్లా","e":"","table":null},{"a":"కమల్ యార్‌జంగ్ జాగీరు గ్రామాలు","e":"","table":null},{"a":"90 వేల కల్దారు రూపాయలు","e":"","table":null},{"a":"జాగీర్దారు ప్రభుత్వం","e":"","table":null},{"a":"పరిటాల, బత్తెనపాడు, గని ఆత్మూరు, మొగులూరు, కొడవటికల్లు, ఉస్తేపల్లి, మల్లవెల్లి","e":"","table":null},{"a":"గాంధీ ఉద్యమం","e":"","table":null},{"a":"లంక సుబ్బయ్యశాస్త్రి","e":"","table":null},{"a":"హత్యచేసి పీడ విరగడ చేసుకున్నారు","e":"","table":null},{"a":"1947 ఆగస్టు 15","e":"","table":null},{"a":"అల్పసంఖ్యాక ప్రజల రక్షణ","e":"","table":null},{"a":"12000 మంది","e":"","table":null},{"a":"విలీనమైనవి","e":"","table":null},{"a":"కృష్టాజిల్లా","e":"","table":null},{"a":"గన్నవరం తాలూకా","e":"","table":null},{"a":"ఏడు గ్రామాలు","e":"","table":null},{"a":"13 గ్రామాలు","e":"","table":null},{"a":"17 గ్రామాలు","e":"","table":null},{"a":"24 గ్రామాలు","e":"","table":null},{"a":"19 గ్రామాలు","e":"","table":null},{"a":"65 గ్రామాలు","e":"","table":null},{"a":"స్టేట్ కాంగ్రెస్ నాయకత్వం","e":"","table":null},{"a":"27 చోట్ల","e":"","table":null},{"a":"80 చోట్ల","e":"","table":null},{"a":"10 చోట్ల","e":"","table":null},{"a":"మహారాణి ఆదిలక్ష్మి దేవమ్మ","e":"","table":null},{"a":"తుంగభద్రానది తీరం","e":"","table":null},{"a":"తుంగభద్ర, కృష్టా నదులు","e":"","table":null},{"a":"సర్దార్ పటేల్","e":"","table":null},{"a":"29-11-1947","e":"","table":null},{"a":"రామేశ్వరరావు","e":"","table"