రు, బట్టలమీద అద్దకాలతో బొమ్మలు వేయించుకునేవారు.","table":null},{"a":"1500 మంది","e":"","table":null},{"a":"ఉదరపోషణ నిమిత్తం గ్రంథరచన చేయలేదు","e":"","table":null},{"a":"మామా","e":"","table":null},{"a":"నిర్వచనోత్తర రామాయణం, మహాభారతంలోని 15 పర్వాలు, వీర హరివంశం","e":"","table":null},{"a":"ప్రతాపరుద్ర యశోభూషణం","e":"","table":null},{"a":"పండితారాధ్య చరిత్ర, బసవపురాణము, వృషాధిప శతకము","e":"శైవమత వ్యాప్తికి తోడ్పడ్డాయి.","table":null},{"a":"ఆంధ్రభాషా భూషణము, కేతన రచించాడు","e":"","table":null},{"a":"ఆంధ్రవాజ్మయ శతకాలలో మొదటిది","e":"","table":null},{"a":"మల్లికార్జున భట్టు, కుమార రుద్రుడు, అయ్యలార్యుడు, భాస్కరుడు, హుళక్కి భాస్కరుడు","e":"ఈ అయిదుగురు కలిసి రచించారు.","table":null},{"a":"మార్కండేయ పురాణం","e":"","table":null},{"a":"కేయూర బాహు చరిత్ర","e":"","table":null},{"a":"కాలాముఖి, కాపాలిక, శైవ, పాశుపతము; పాశుపత శైవమే రాజమతం","e":"","table":null},{"a":"పాల్కురికి సోమనాథుడు","e":"","table":null},{"a":"రంగనాథ రామాయణము","e":"పూర్వరామాయణాన్ని బుద్దరాజు రచించగా, ఉత్తర రామాయణాన్ని విభలదేవుడు, బుద్దరాజు పుత్రులు రచించారు.","table":null},{"a":"క్రీ.శ. 1050 నుండి 1350 వరకు","e":"","table":null},{"a":"స్వర్ణయుగంగా","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-6-padmanayakulu', 'telangana-history-te', 6, 'పద్మనాయకులు', '[{"a":"ముస్లిం సేనావాహిని","e":"","table":null},{"a":"తమిళనాడులోని మధురదాకా","e":"ఎదురులేకుండా సాగింది.","table":null},{"a":"మలబార్ రాష్ట్రంగా","e":"","table":null},{"a":"ఉలుఫ్ఖాన్ నేతృత్వంలో","e":"ఇతను ఖియాసుద్దీన్ తుగ్లక్ కుమారుడు, తరువాత మహమ్మదీబిన్ తుగ్లక్‌గా పేరు మార్చుకున్నాడు.","table":null},{"a":"ఉలుఫ్ఖాన్ నేతృత్వంలోని రాజ్యవిస్తరణ కార్యక్రమం","e":"","table":null},{"a":"మసీదులను","e":"","table":null},{"a":"ఒక్క తాటిమీదికి వచ్చారు","e":"","table":null},{"a":"ప్రోలయ నాయకుడిని","e":"","table":null},{"a":"1325లో","e":"","table":null},{"a":"ప్రవాస ప్రభుత్వం, తరువాత స్వతంత్ర సామ్రాజ్యం","e":"","table":null},{"a":"ప్రోలయనాయకుని స్వాధీనమైంది","e":"","table":null},{"a":"కాపయ నాయకుడు","e":"ఇతడు ప్రోలయ నాయకుడి పినతండ్రి కుమారుడు.","table":null},{"a":"కాపయ నాయకుడే","e":"","table":null},{"a":"రేచర్ల వంశంవారు","e":"","table":null},{"a":"శైవులు, తరువాత వైష్ణవులుగా మారారు","e":"","table":null},{"a":"ముసునూరి పాలకులు","e":"తీరాంధ్రాన్ని పాలించినవారు.","table":{"headers":["రాజ్యం","పాలకులు"],"rows":[["తీరాంధ్రాన్ని పాలించినవారు","ముసునూరి పాలకులు"],["వరంగల్‌ను స్వాధీనపరచుకున్నవాడు","కాపయ నాయకుడు"],["ప్రోలయ వేమారెడ్డి స్థాపించిన రాజ్యం","రెడ్డిరాజ్యం"],["పద్మనాయకులు స్థాపించిన రాజ్యాలు","రాచకొండ, దేవరకొండ రాజ్యాలు"],["హరిహర బుక్కరాయలు స్థాపించిన సామ్రాజ్యం","విజయనగర సామ్రాజ్యం"],["స్థానిక గవర్నరు తిరుగుబాటు జరిపి దక్కనులో స్థాపించిన రాజ్యం","బహమనీ రాజ్యం"]],"unit":"1335-36 నాటి దక్షిణాపథ రాజ్యాలు"}},{"a":"77 మంది నాయకులు","e":"","table":null},{"a":"గోదావరి తీరంలోగల భద్రాచలం దగ్గర రేకపల్లికి","e":"","table":null},{"a":"క్రీ.శ. 1330 ప్రాంతంలో","e":"","table":null},{"a":"కాపయ నాయకత్వం","e":"","table":null},{"a":"ఓరుగల్లు కోటను ముట్టడించి మహమ్మదీయులను పారదోలి స్వాధీనం చేసుకున్నాడు","e":"","table":null},{"a":"ఓరుగల్లుకు","e":"","table":null},{"a":"ఆంధ్ర సురత్రాణ, ఆంధ్రదేశాధీశ్వర, కాకతీయ స్థాపనాచార్య","e":"","table":null},{"a":"ఒక ఒప్పందానికి","e":"","table":null},{"a":"ఒకరి భూభాగాలలో వేరొకరు జోక్యం చేసుకోనవద్దు","e":"","table":null},{"a":"చక్రవర్తిత్వాన్ని","e":"","table":null},{"a":"అతని కొన్ని ప్రాంతాలను ఆక్రమించుకున్నాడు","e":"","table":null},{"a":"క్షీణించింది","e":"","table":null},{"a":"1367-68లో","e":"","table":null},{"a":"వరుసగా తెలంగాణా దుర్గాలను తన స్వాధీనంలోకి తెచ్చుకున్నాడు","e":"","table":null},{"a":"కాకతీయరాజులకు","e":"","table":null},{"a":"పద్మనాయకుల అభ్యున్నతి","e":"","table":null},{"a":"నల్లగొండ జిల్లాలోని ఆమనగల్లు","e":"","table":null},{"a":"రాచకొండ, దేవరకొండలకు","e":"ఈ రెండు చోట్లా బలిష్టమైన దుర్గాలను నిర్మించుకున్నారు.","table":null},{"a":"నల్లగొండ జిల్లా నారాయణపురం మండలంలో","e":"","table":null},{"a":"ధర్మరక్షణకు","e":"కాకతీయుల పతనం తరువాత వరంగల్ తదితర ఆంధ్రదేశ ప్రాంతాలు ముస్లింల వశమైనందున.","table":null},{"a":"అన్ని మత సంప్రదాయాలకు చెందినవారు","e":"","table":null},{"a":"సాహిత్యానికి, సంగీతానికి, నాట్యశాస్త్ర రంగానికి","e":"","table":null},{"a":"శాలక్య అయ్యలార్యుడు, భాస్కర రామాయణం పూర్తి చేశాడు","e":"","table":null},{"a":"గౌరన, పోతన","e":"","table":null},{"a":"సర్వజ్ఞ సింగభూపాలుడు","e":"","table":null},{"a":"శ్రీనాథుడు","e":"","table":null},{"a":"హిందూ సంఘం నీరసించింది","e":"","table":null},{"a":"శ్రీరాముడు ఆదర్శప్రభువు, రామరాజ్యం ఆదర్శరాజ్యం","e":"","table":null},{"a":"భాగవతాంధ్రీకరణ","e":"పోతనచేతిలో తెలుగు తల్లి రాణించింది.","table":null},{"a":"తెనుగు తీగలు","e":"సహజమాధుర్యం సార్థకం చేసుకున్నది.","table":null},{"a":"150 సంవత్సరాలు","e":"సమర్థమైన, స్థిరమైన పాలనను అందించలేకపోయారు.","table":null},{"a":"బహమనీసుల్తాన్లతో, ఢిల్లీ సుల్తాన్లతో వైరం, విజయనగర గజపతుల ప్రాబల్యం పెరగడం","e":"","table":null},{"a":"1475","e":"","table":null},{"a":"ప్రధాన పాత్రను","e":"","table":null},{"a":"అనసోమసముద్రం, రాయసముద్రం, నాగసముద్రం","e":"","table":null},{"a":"రెడ్డి రాజులతో","e":"","table":null},{"a":"భూములు","e":"","table":null},{"a":"స్వయంగా కవులు","e":"","table":null},{"a":"రసార్ణవ సుధాకరము, రత్నపాంచాలిక, చమత్కార చంద్రిక, అమర పద పారిజాతము, లక్షణదీపిక, హరిశ్చంద్రోపాఖ్యానము","e":"రసార్ణవ సుధాకరము నాట్యాలంకార శాస్త్రగ్రంథం, రత్నపాంచాలిక సంస్కృత నాటకం, చమత్కార చంద్రిక అలంకారశాస్త్ర గ్రంథం, అమర పద పారిజాతము అమరకోశానికి వ్యాఖ్యానం.","table":null},{"a":"సింహాసన ద్వాత్రింశిక, నవనాథ చరిత్ర, భాగవతము, భోగినీ దండకము","e":"","table":null},{"a":"విశిష్ట స్థానాన్ని","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-7-hindumata-punaruddharana-bhakti-udyamam', 'telangana-history-te', 7, 'హిందూమత పునరుద్ధరణ- భక్తి ఉద్యమం', '[{"a":"బౌద్ధమతం","e":"","table":null},{"a":"క్రీస్తుపూర్వం 4వ శతాబ్దం నుండి క్రీస్తు తరువాత 6-7 శతాబ్దాల వరకు","e":"","table":null},{"a":"మరి ఏ ఇతర మత కట్టడాలు లేవు","e":"","table":null},{"a":"ఫణిక్సర్","e":"ఇతను చరిత్రకారుడు.","table":null},{"a":"శివ-విష్ణువులు","e":"","table":null},{"a":"భక్తి ఉద్యమానికి","e":"","table":null},{"a":"రాజకీయ పరిస్థితి","e":"","table":null},{"a":"ప్రజల బింకం, బిగువు వీటలు","e":"","table":null},{"a":"భక్తి యోగం","e":"","table":null},{"a":"పన్నెండవ శతాబ్దంలో, ఆంధ్ర, కర్ణాటక దేశాలలో","e":"","table":null},{"a":"బసవేశ్వరుడు","e":"","table":null},{"a":"శివుడే","e":"","table":null},{"a":"28 శైవ ఆగమాలు","e":"","table":null},{"a":"చైతన్య ప్రదాతలు","e":"","table":null},{"a":"పండితారాధ్యుడు","e":"","table":null},{"a":"తెలుగుదేశంలోనే ఎక్కువగా కనబడుతుంది","e":"","table":null},{"a":"నన్నయభట్టు","e":"","table":null},{"a":"ప్రాకృతం సంపూర్ణంగా నశించి సంస్కృతం పండితభాషగా మాత్రమే మిగలడం","e":"","table":null},{"a":"శంకరాచార్యులు","e":"","table":null},{"a":"క్రీ.శ. 790 ప్రాంతంలో కేరళలోని నంబూద్రి కుటుంబంలో","e":"","table":null},{"a":"ముప్పయి రెండు సంవత్సరాలు","e":"","table":null},{"a":"పూరి, ద్వారక, బదరి, శృంగేరీలలో","e":"","table":null},{"a":"ఉపనిషత్తులకు, భగవద్గీతకు, బ్రహ్మసూత్రాలకు","e":"","table":null},{"a":"నాలాయిరం","e":"అదే తిరువాయ్ మొడి.","table":null},{"a":"పన్నిద్దరాళ్వారుల స్తోత్రాలను","e":"ఆ నాలుగువేల స్తోత్రాలను సేకరించాడు.","table":null},{"a":"సన్నగిల్లింది","e":"","table":null},{"a":"రంగనాథాచార్య అనే నాథముని","e":"","table":null},{"a":"న్యాయతత్వం అనే గ్రంథం","e":"ప్రపత్తి అనే సిద్ధాంతాన్ని అందులో ప్రతిపాదించారు.","table":null},{"a":"యామునాచార్యులు","e":"","table":null},{"a":"ద్రావిడదేశంలో","e":"","table":null},{"a":"భాగవతోత్తములు","e":"","table":null},{"a":"1018లో","e":"","table":null},{"a":"అద్వైత మతాన్ని ఖండించి విశిష్టాద్వైతమనే వైష్ణవ సిద్ధాంతాన్ని నెలకొల్పాడు","e":"","table":null},{"a":"శైవ మతాభిమాని","e":"","table":null},{"a":"శ్రీరంగం","e":"","table":null},{"a":"భగవంతునిలో ఐక్యం కాకుండా ఆయన సన్నిధిలోనే ఉండటమే మోక్షమని","e":"","table":null},{"a":"నింబార్కుడు","e":"ఈయన రామానుజులకు సమకాలికుడు, బళ్ళారి జిల్లాలో జన్మించాడు.","table":null},{"a":"రాధాకృష్ణులను","e":"","table":null},{"a":"ఉడిపిలో","e":"","table":null},{"a":"నారాయణుడొక్కడే","e":"","table":null},{"a":"వేదాలే","e":"","table":null},{"a":"వడగలై, తెంగలై","e":"","table":null},{"a":"వేదాలకు","e":"రెండవ తెగకు పిళ్ళైలోకాచార్యులు నాయకులు, తెంగలై వైష్ణవులు ప్రబంధాలకు ప్రాముఖ్యమిచ్చారు.","table":null},{"a":"బౌద్ధ నిర్మాణం","e":"","table":null},{"a":"బౌద్ధం, జైనం","e":"తెలుగుసీమలో వెల్లివిరిసిన సాక్ష్యం ఉండేది కాదు.","table":null},{"a":"ఆంధ్రమహాభారతం ప్రథమాంధ్ర కావ్యం కావడం, తూర్పు చాళుక్యులు నూతన సామ్రాజ్య నిర్మాతలు కావడం","e":"","table":null},{"a":"పంచమవేదమైన భారత సంహిత","e":"దీని ఉద్దేశం ప్రజాస్వామ్యంలో వేదమతం పునఃస్థాపన చేయడం.","table":null},{"a":"శైవమతం","e":"వీరశైవంగా పైబడి శివుడొక్కడే దైవమనే భావం, మార్మిక పద్ధతి ఆరాధనలు బహుళ ప్రచారంలోకి వచ్చాయి.","table":null},{"a":"సోమయాజి చేపట్టాడు","e":"మహాభారతంలో హరిహర రూపంగా ఈ భావన ఆయనకు దర్శనమయింది.","table":null},{"a":"బమ్మెర పోతన","e":"","table":null},{"a":"భక్తిరసపూర్ణమైన మహోత్కృష్ట గ్రంథం","e":"","table":null},{"a":"వరంగల్ వాడు","e":"","table":null},{"a":"మరొకటి లేదు","e":"","table":null},{"a":"దోహా, చప్పయ్, ముస్సుగనవి","e":"","table":null},{"a":"ద్విపద, మంజరి, జాజిరి, చందమామలు, కోయిల, చిలుక, తుమ్మెద పదాలు","e":"రావి, సువ్వి, గొబ్బి, ఉయ్యాల, జోల, జోజో, తందనాలు, చాంగు బళాలు కూడా ఈ కోవలోనివే.","table":null},{"a":"తిరునామాలు మంగళహారతులు, కీర్తనలు","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-8-bahamani-sultanulu', 'telangana-history-te', 8, 'బహమనీ సుల్తానులు', '[{"a":"ఢిల్లీ సుల్తానుల సామ్రాజ్యతత్వానికి","e":"","table":null},{"a":"1336లో హంపీలో","e":"","table":null},{"a":"1347లో గుల్బర్గాలో","e":"గుల్బర్గా వెనుకటి నిజాంరాష్ట్రంలోని ఒక జిల్లా.","table":null},{"a":"మహమ్మద్ బిన్ తుగ్లక్‌మీద","e":"","table":null},{"a":"హసన్ అలీ అనే యువకునిపై","e":"","table":null},{"a":"మొజఫర్ అల్లాఉద్దీన్ అహమ్మద్ హసన్ గంగూ","e":"1347 ఆగస్టు 3వ తేదీన స్థాపించాడు.","table":null},{"a":"యావత్తు దక్షిణాపథం స్వతంత్రమైంది","e":"","table":null},{"a":"1347-58","e":"","table":null},{"a":"హస్నాబాద్‌గా","e":"","table":null},{"a":"ఆంధ్రదేశాధీశ్వరుడైన ముసునూరి కాపయ నాయకుడు","e":"","table":null},{"a":"కాపయ నాయకుడే","e":"","table":null},{"a":"హైరానా పడిపోయాడు","e":"ఒకవైపు రెడ్డిరాజులు, మరొకవైపు పద్మనాయకుల మధ్య నలిగిపోతున్న కాపయనాయకునికి హసన్ చర్యలు మరిన్ని ఇబ్బందులు కలిగించాయి.","table":null},{"a":"పెక్కు ఏనుగులు, ద్రవ్యరాసి","e":"","table":null},{"a":"దారిలో కనిపించిన గ్రామాలన్నిటినీ దోచుకున్నాడు, దేవాలయాలను పడగొట్టించాడు","e":"","table":null},{"a":"బీదరు, మాళ్ఖేడ్‌లను","e":"","table":null},{"a":"1358లో","e":"","table":null},{"a":"పైన గంగా నుండి దక్షిణాన తుంగభద్ర వరకూ, పశ్చిమాన దౌలతాబాద్ నుండి తూర్పున భువనగిరి వరకూ","e":"","table":null},{"a":"గుల్బర్గా, దౌలతాబాద్, బీదరు, బీరారు","e":"","table":null},{"a":"మొదటి మహమ్మద్‌షా","e":"ఇతను పరాక్రమవంతుడేగాని మహాక్రూరుడు.","table":null},{"a":"జబర్దస్తీ సంధి","e":"","table":null},{"a":"నాలుగు కోణాల మంటలలో","e":"","table":null},{"a":"ఢిల్లీశ్వరుడైన ఫిరోజ్ తుగ్లక్‌కు","e":"కాని స్వమతాభిమానంతో తుగ్లక్ అతనికి న్యాయం చేకూర్చలేదు.","table":null},{"a":"33 లక్షల నగదు, 300 ఏనుగులు, 200 గుర్రాలు","e":"","table":null},{"a":"కృష్ణా-తుంగభద్ర నదుల మధ్య ప్రాంతాన్ని","e":"","table":null},{"a":"ప్రొఫెసర్ షేర్వానీ","e":"","table":null},{"a":"1375లో","e":"","table":null},{"a":"ముజాయిద్‌షా","e":"","table":null},{"a":"రెండు సార్లు ఓడిపోయాడు","e":"","table":null},{"a":"దావూద్ అనేవాడు","e":"ముజాయిద్‌కు సంతానం లేదు.","table":null},{"a":"ఒక వర్గం దావూద్‌ని, మరొకవర్గం అల్లాఉద్దీన్ కనిష్టపుత్రుడిని","e":"","table":null},{"a":"పరాజయం లభించింది","e":"నమాజు చదువుతున్నప్పుడు ఒక బానిస దావూద్‌ని హత్య చేశాడు.","table":null},{"a":"35 రోజులు","e":"","table":null},{"a":"రెండవ మహమ్మద్‌షా","e":"","table":null},{"a":"1378లో ప్రారంభమై 1397లో ముగిసింది","e":"","table":null},{"a":"శాంతిప్రియుడు, దైవభక్తి, పాపభీతి కలవాడు","e":"ప్రభుత్వ ఆస్తిని తన ధర్మకర్తగా భావించేవాడు.","table":null},{"a":"కరువు","e":"పదివేల ఎడ్లపై మాళ్వా, గుజరాత్ ప్రాంతాలనుంచి ధాన్యం తెప్పించే ఏర్పాటు చేశాడు.","table":null},{"a":"సైఫ్ ఉద్దీన్ అనే ప్రధాని","e":"ఇతను అయిదుగురు సుల్తానుల కాలంలో ప్రధానిగా పనిచేశాడు.","table":null},{"a":"గుల్బర్గా, బీదరు, ఎలచ్‌పూర్, ఖందహార్, దౌలతాబాద్","e":"ఇవి సెక్యులర్ పాఠశాలలు కావు; వాటిలో ప్రవేశం ముస్లిం ప్రజలకు మాత్రమే.","table":null},{"a":"19 సంవత్సరాల 5 నెలల 21 రోజులు","e":"","table":null},{"a":"ఒక నెల 22 రోజులు","e":"","table":null},{"a":"7 రోజులు మాత్రమే","e":"","table":null},{"a":"ఫిరోజ్‌షాకు","e":"","table":null},{"a":"నెరజాణలను","e":"","table":null},{"a":"ముద్గల్‌ను","e":"","table":null},{"a":"రాయల కుమారుని","e":"","table":null},{"a":"ఫిరోజ్‌షాకు","e":"","table":null},{"a":"మంచం పట్టాడు","e":"","table":null},{"a":"25 సంవత్సరాలు, 1422లో మరణించాడు","e":"","table":null},{"a":"1422 నుంచి 1433 వరకు","e":"","table":null},{"a":"కొల్పేయిన రాజ్యవిభాగాన్ని","e":"ఈ యుద్ధకాలంలో 20వేలమంది హిందువులు, ముస్లిం సిపాయిలు ఊచకోతకు గురైనారు.","table":null},{"a":"బీదరుకు","e":"","table":null},{"a":"23 సంవత్సరాలు","e":"కొంకణ దేశాన్ని జయించాడు.","table":null},{"a":"అతని కూతురిని","e":"","table":null},{"a":"అనేక పాఠశాలలు, వైద్యశాలలు","e":"మత్తుపదార్థాలపై నిషేధాజ్ఞలు జారీచేశాడు.","table":null},{"a":"గొలుసులు","e":"","table":null},{"a":"క్రూరుడు","e":"","table":null},{"a":"అనేక క్రూర చర్యలు","e":"","table":null},{"a":"ఊచకోత కోయించాడు","e":"","table":null},{"a":"ఏనుగుల కాళ్ళకు కట్టించి పురవీధుల్లో ఈడ్చుకుపోయేవాడు","e":"సలసలగా నూనెలో పడద్రోయించేవాడు, ఆకలిగొన్న పులులకు ఆహారంగా ఇచ్చేవాడు.","table":null},{"a":"బలికావలసి వచ్చింది","e":"","table":null},{"a":"హోబాషి ఉంపుడు కత్తె బలంగా నెత్తిమీద ముష్టిఘాతాలు తగిలించి","e":"","table":null},{"a":"మూడు సంవత్సరాల ఆరు నెలలు","e":"","table":null},{"a":"ఎనిమిదేళ్ళ బాలుడు","e":"కొద్దికాలం తరువాత అతని సోదరుడైన మూడో మహమ్మద్ 1463లో గద్దె నెక్కాడు.","table":null},{"a":"ఒకడు","e":"","table":null},{"a":"వజీర్లుగా","e":"","table":null},{"a":"ఇరాన్ నుంచి","e":"","table":null},{"a":"అమీర్ పదవి","e":"","table":null},{"a":"మలక్-ఉల్-తుజార్","e":"","table":null},{"a":"ప్రధాని పదవి","e":"","table":null},{"a":"స్వామిభక్తి పరాయణుడుగానే మిగిలిపోయాడు","e":"","table":null},{"a":"విదేశీ అమీర్లు","e":"","table":null},{"a":"రెండు లక్షల సైన్యానికి","e":"","table":null},{"a":"సంస్కరణలపై","e":"పరిపాలనా యంత్రాంగంలో అనేక మార్పులు తీసుకువచ్చాడు, భూములను సర్వే చేయించాడు.","table":null},{"a":"అనేక పాఠశాలలు","e":"రాజమండి, కొండవీడులను ఆక్రమించుకున్నాడు.","table":null},{"a":"ఒరిస్సా రాజు","e":"దాన్ని మహమ్మద్‌షా తిప్పికొట్టి ఒరిస్సా రాజులకు తెలంగాణాలో ఏమాత్రం హక్కులేదని ఒక పత్రం రాయించుకున్నాడు.","table":null},{"a":"600 సంవత్సరాలు","e":"","table":null},{"a":"మూడువేల గ్రంథాలను","e":"","table":null},{"a":"సుల్తాన్‌ను పదభ్రష్టుని చేయడానికి పన్నాగాలు చేస్తున్నాడని","e":"","table":null},{"a":"హత్య చేయించాడు","e":"","table":null},{"a":"పునాదులు కదిలిపోయాయి","e":"అధికారాన్ని స్వార్థపరులైన అమీర్లు తిరిగి స్వాధీనపరచుకున్నారు.","table":null},{"a":"కరీముల్లా","e":"ఇతడు మూడు సంవత్సరాలు నామమాత్రపు ప్రభువుగా ఉండి 1527లో చనిపోయాడు.","table":null},{"a":"1527లో","e":"","table":null},{"a":"స్వతంత్రులైనారు","e":"","table":null},{"a":"బీదరులో బరీద్‌షాహీ, గోల్కొండలో కుతుబ్‌షాహీ, బీజాపూర్‌లో ఆదిల్‌షాహీ, అహమ్మద్‌నగర్‌లో నిజాంషాహీ, బీరారులో ఇమాద్‌షాహీ","e":"","table":{"headers":["స్థానం","రాజ్యం"],"rows":[["బీదరు","బరీద్‌షాహీ"],["గోల్కొండ","కుతుబ్‌షాహీ"],["బీజాపూర్","ఆదిల్‌షాహీ"],["అహమ్మద్‌నగర్","నిజాంషాహీ"],["బీరారు","ఇమాద్‌షాహీ"]],"unit":"బహమనీ అనంతర షాహీ రాజ్యాలు"}},{"a":"182 సంవత్సరాలు","e":"అందులో అయిదుగురు హత్యకు గురయ్యారు, ఇద్దరు విషయ లోలురై మరణించారు, ముగ్గురు పదవీభ్రష్టులైనారు, ఇద్దరు అంధులు కావింపబడ్డారు.","table":null},{"a":"ఆర్థిక, రాజకీయ కారణాలతో","e":"","table":null},{"a":"మతాన్ని","e":"","table":null},{"a":"ఆక్రమించలేకపోయారు","e":"విజయనగర రాయలు బహమనీసుల్తాన్లు నడిపిన దండయాత్రలను తిప్పికొట్టి తమ ఆత్మగౌరవాన్ని, స్వాతంత్ర్యాన్ని నిలబెట్టుకున్నారు.","table":null},{"a":"సూఫీలు","e":"","table":null},{"a":"సోదరభావం","e":"","table":null},{"a":"ప్రేమతో భగవంతునికి ఆత్మార్పణం కావించుకోవడం","e":"","table":null},{"a":"భగవంతునిపై నిజమైన ప్రేమ ప్రదర్శించినవారే","e":"","table":null},{"a":"ముఖ్యమైనవి కావు","e":"","table":null},{"a":"ఇతర మతాలను","e":"","table":null},{"a":"భగవంతుని దగ్గరకు","e":"","table":null},{"a":"మానవత్వమే","e":"","table":null},{"a":"ఫిరోజ్‌షా కాలంలో","e":"","table":null},{"a":"బహుముఖంగా విస్తరిల్లి వేళ్ళు తన్నుకుంది","e":"","table":null},{"a":"పంచాంగం లెక్కల ప్రకారం","e":"","table":null},{"a":"ఒక సంతుగా భావించి","e":"","table":null},{"a":"గుల్బర్గాకు చెందిన లింగాయత్ జంగము","e":"","table":null},{"a":"పండరీపురం సంప్రదాయం","e":"","table":null},{"a":"అన్యధర్మస్థులైన పాలకులతో","e":"","table":null},{"a":"గొప్ప భక్తుడు","e":"","table":null},{"a":"ఒక కొత్త చైతన్యం, జీవకళ","e":"","table":null},{"a":"సమానులేనని","e":"","table":null},{"a":"''నాద'' సంప్రదాయం","e":"","table":null},{"a":"యోగులు","e":"","table":null},{"a":"దత్తాత్రేయ సంప్రదాయం","e":"","table":null},{"a":"ముస్లింలు","e":"వారు ''షాహీఫకీర్లు''గా ప్రఖ్యాతులు.","table":null},{"a":"ఉర్దూ భాషను","e":"ఆ రోజులలో ఈ భాషను ''హిందవీ'' అనేవారు.","table":null},{"a":"ప్రయత్నాలేవీ జరగలేదు","e":"","table":null},{"a":"ఓరుగల్లును పాలించిన కాపయ నాయకుడు","e":"","table":null},{"a":"ఈ ఆశ కొద్ది కాలంలోనే భగ్నమైంది","e":"పిమ్మట ఓరుగల్లు రాజ్యం బహమనీల వశమైంది.","table":null},{"a":"హిందువులు","e":"","table":null},{"a":"జోక్యం","e":"","table":null},{"a":"తమ ఇష్టానుసారం","e":"","table":null},{"a":"వరి అన్నం, పప్పులు, పెరుగు, మజ్జిగ, ఆకుకూరలు","e":"జొన్నలు, సజ్జలు కూడా ఉపయోగించేవారు.","table":null},{"a":"తాంబూల చర్వణం","e":"","table":null},{"a":"శాకాహారులు, మధుపాన విసర్జితులు","e":"రెడ్లు, వెలమలు, మరాఠీలు మొదలైన పాలకవర్గం వారు మాంసాహారులు.","table":null},{"a":"పరదా నియమం","e":"వారిలో బాల్య వివాహాలు ఆచరణలో ఉండేవి, సతీసహగమనం పాటించేవారు.","table":null},{"a":"వృద్ధిలోకి","e":"","table":null},{"a":"నాణ్యతలో మెరుగైనవి, ఆకారంలో పెద్దవి","e":"","table":null},{"a":"కత్తులు, బల్లేలు, బాకులు, ధనుర్బాణాలు","e":"","table":null},{"a":"బహమనీలు","e":"","table":null},{"a":"మక్తబ్‌లు","e":"","table":null},{"a":"ముస్లిం రాజుల శకం","e":"","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('chapter-9-kutubshahi-navabulu', 'telangana-history-te', 9, 'కుతుబ్‌షాహీ నవాబులు', '[{"a":"గోల్కొండ","e":"పదహారవ శతాబ్ది నుంచి పదిహేడవ శతాబ్ది చివరివరకు గోల్కొండ రాజధానిగా దక్షిణపాలన సాగించారు.","table":null},{"a":"సుల్తాన్ కులీ","e":"ఇతను ఇరాన్‌లోని అమ్దాన్ రాజవంశానికి చెందినవాడు.","table":null},{"a":"బహమనీ కొలువు","e":"మహమ్మద్‌షా బహమనీ కొలువులో తన ఉదాత్త గుణసంపదతో త్వరలోనే ప్రముఖస్థానం పొందాడు.","table":null},{"a":"కుతుబుల్ ముల్క్","e":"","table":null},{"a":"కుతుబుల్ ముల్క్","e":"","table":null},{"a":"గోల్కొండ-వరంగల్ మధ్య విభాగం","e":"","table":null},{"a":"ఐదు","e":"","table":{"headers":["క్రమ సంఖ్య","రాజ్యం పేరు"],"rows":[["1","అహమద్ నగర్"],["2","బీజాపూర్"],["3","బీరారు"],["4","బీదరు"],["5","గోల్కొండ"]],"unit":"బహమనీ రాజ్య విభజన (1500)"}},{"a":"1512","e":"","table":null},{"a":"వరంగల్ నుంచి రాజమహేంద్రం వరకు","e":"బహమనీ కాలంలో వరంగల్ పరిసరాలకే పరిమితమైన రాజ్యాన్ని ఇలా విస్తరించాడు.","table":null},{"a":"గోల్కొండ కోట","e":"","table":null},{"a":"హైదర్ కులీ","e":"తండ్రి ఉండగానే చనిపోయాడు.","table":null},{"a":"జమ్షీద్ కులీ (యార్ కులీ)","e":"మూడవ కుమారుడైన ఇతను పరిపాలనా విషయాలు తెలిసినవాడు కానీ క్రూరుడు, దుర్మార్గుడు.","table":null},{"a":"మీర్ మహమ్మద్ హందానీ","e":"జమ్షీద్ కులీ ఆదేశంతో మజ్జీద్ సఫాలో నమాజు చేసుకుంటున్న శతవృద్ధుడైన సుల్తాన్ కులీని చంపాడు.","table":null},{"a":"జమ్షీద్ కులీ కుతుబ్‌షా","e":"అనుజుడైన కుతుబుద్దీన్‌ను కారాగారంలో పడద్రోసి సింహాసనం అధిష్ఠించాడు.","table":null},{"a":"1543-50","e":"","table":null},{"a":"అలీ బరీద్","e":"ఈ ప్రయత్నం విఫలమైంది, గోల్కొండ సైనికులు బరీద్ సైన్యాన్ని బీదరు వరకు తరిమికొట్టారు.","table":null},{"a":"విజయనగరం","e":"రామరాయలు ఇబ్రహీం కులీని ఆప్యాయంగా ఆహ్వానించి జాగీర్లిచ్చి సత్కరించాడు.","table":null},{"a":"తెలుగు సాహిత్య సంస్కృతుల ప్రభావం","e":"","table":null},{"a":"క్రూరమైనది, నిరంకుశమైనది","e":"సామాన్యమైన నేరాలకు కూడా కఠినాతి కఠినమైన శిక్షలు విధించి పరమ క్రూరుడనిపించుకున్నాడు.","table":null},{"a":"కవి","e":"కవి పండితులను ఆదరించాడు.","table":null},{"a":"1550లో క్షయ వ్యాధితో","e":"","table":null},{"a":"రాణి బిల్కిస్‌జమాన్","e":"జమ్షీద్ తనయుడు సుభాన్ కులీ సప్తవార ప్రాయం కావడంతో రాణి రాజ్యపాలన సాగించింది.","table":null},{"a":"సైఫ్‌ఖాన్","e":"ఇతని పరిపాలన వ్యవహారాలు నచ్చని సర్దార్లు జగదేవుడిని రాజుగా ప్రకటించారు.","table":null},{"a":"జగదేవుడు","e":"దౌలత్ కులీని బంధించి జగదేవుడిని సర్దార్లు సుల్తానుగా ప్రకటించారు.","table":null},{"a":"ఇబ్రహీం కులీ","e":"సైఫ్‌ఖాన్ దుష్పరిపాలనతో విసిగిపోయిన ప్రజలు ఇబ్రహీం కులీని రప్పించారు.","table":null},{"a":"1550","e":"విజయనగర రాజు వద్దగల సెలవు తీసుకుని గోల్కొండకు బయలుదేరాడు.","table":null},{"a":"ఇబ్రహీం కులీ","e":"","table":null},{"a":"నిజాంషా (అహమద్‌నగర్ రాజు)","e":"వీరిద్దరు బీజాపూర్ రాజ్యభాగమైన కల్యాణిపై 1562లో దండెత్తారు.","table":null},{"a":"1564 డిసెంబరు","e":"","table":null},{"a":"రామరాయలు","e":"ఇతని శిరస్సును ఖండించి ముస్లిం సేన విజయ ధంకా మోగించింది.","table":null},{"a":"ఇబ్రహీం కులీ కుతుబ్‌షా","e":"","table":null},{"a":"అహమద్‌నగర్ రాజ్యం","e":"","table":null},{"a":"రాజమహేంద్రవరం, కాశింకోట, వీరఘట్టం","e":"తీరాంధ్రదేశాన్ని జయించాలనే కోరికతో ఈ ప్రాంతాలపై దండెత్తాడు.","table":null},{"a":"వినుకొండ, కొచ్చర్లకోట, కంభం, కొండవీడు","e":"","table":null},{"a":"పెద్దవ్యాపార కూడలిగా","e":"1550 నాటికి గోల్కొండ పట్టణం పెద్దవ్యాపార కూడలిగా మారింది.","table":null},{"a":"1580","e":"","table":null},{"a":"1580-1612","e":"","table":null},{"a":"మూడవ కుమారుడు","e":"","table":null},{"a":"1591లో మహమ్మద్ కులీ","e":"మొహర్రం తరువాత మూసీకి దక్షిణాన పురానాపూల్ బ్రిడ్జి పక్కన శంఖుస్థాపన చేశాడు.","table":null},{"a":"మీర్ మోమిన్","e":"ఇతను తన ప్రధానమంత్రి.","table":null},{"a":"ప్లేగు వ్యాధి నివారణ","e":"అప్పటి విస్తరిస్తున్న ప్లేగు వ్యాధికి వ్యాధి నిరోధాన్ని కనుగొన్నందుకు గుర్తుగా నిర్మించినట్లు చరిత్ర చెబుతుంది.","table":null},{"a":"77 సంవత్సరాలు","e":"","table":null},{"a":"మసూద్ బేగ్","e":"అక్బర్ చక్రవర్తి భారతదేశమంతటినీ మొగల్ పాలనలోకి తీసుకురావడానికి ప్రయత్నించాడు.","table":null},{"a":"1605లో, జహాంగీర్","e":"","table":null},{"a":"దక్షిణ ప్రాంతం (మచిలీపట్నం, నిజాంపట్నం, పులికాట్)","e":"డచ్ కంపెనీ ఈ ప్రాంతాల్లో స్థావరాలను ఏర్పరచుకుంది, తరువాత బ్రిటిష్‌వారు ప్రవేశించారు.","table":null},{"a":"1612-1626","e":"","table":null},{"a":"సుల్తాన్ మహమ్మద్ (సోదరుడి కుమారుడు)","e":"కుమార్తె పేరు హయత్ బక్షీ బేగం.","table":null},{"a":"1612","e":"","table":null},{"a":"సుల్తాన్ మహమ్మద్ (అల్లుడు)","e":"","table":null},{"a":"విద్యావంతుడు","e":"స్వయంగా పారశీక భాషలో కవిత్వం చెప్పేవాడు, కవిపండితులను ఆదరించాడు.","table":null},{"a":"ఉర్దూ, పారసీ, తెలుగు","e":"","table":null},{"a":"మక్కామసీదు","e":"","table":null},{"a":"1626","e":"","table":null},{"a":"1626-1672","e":"","table":null},{"a":"12 ఏళ్లు","e":"అతని తల్లి హయత్ బక్షీ బేగం రాజ్యభారం వహించింది.","table":null},{"a":"రెండు లక్షలు","e":"","table":null},{"a":"కోహినూర్ వజ్రం","e":"","table":null},{"a":"మీర్‌జుమ్లా తిరుగుబాటు","e":"ప్రధాని మీర్‌జుమ్లా మొగలులతో కలిసిపోయాడు, అతని ఆస్తిని అబ్దుల్లా వశపరచుకుని కొడుకును బంధించాడు.","table":null},{"a":"ధనమిచ్చి, కూతురిని ఔరంగజేబు కొడుకుకిచ్చి పెళ్లి జరిపి సంధి కుదుర్చుకున్నాడు","e":"","table":null},{"a":"1672-1687","e":"","table":null},{"a":"అబుల్‌హసన్","e":"","table":null},{"a":"అబుల్‌హసన్","e":"ఔరంగజేబుతో చేసుకున్న సంధి ప్రకారం రాజ్యం కుమారునికి దక్కాల్సి ఉన్నా, సయ్యద్ అహమ్మద్ దుష్ప్రవర్తనను తండ్రి భరించలేక జైల్లో పెట్టడంతో అబుల్‌హసన్‌కు రాజ్యం దక్కింది.","table":null},{"a":"మాదన్న","e":"ఏడాది: 1674. ఇతనికి సూర్యప్రకాశరావు అనే బిరుదునిచ్చారు.","table":null},{"a":"300 సంవత్సరాల్లో","e":"","table":null},{"a":"రెవిన్యూమంత్రి","e":"","table":null},{"a":"కొండవీడు దుర్గం","e":"","table":null},{"a":"1686 మార్చి 21","e":"మొగల్ సైన్యం దండెత్తి వస్తున్నా అబుల్‌హసన్ తానీషా భయపడలేదు.","table":null},{"a":"శత్రుధాటికి నిలబడలేకపోయాయి","e":"","table":null},{"a":"ఎనిమిది నెలలు","e":"","table":null},{"a":"అబ్దుల్లా అనేవాడు","e":"మొగల్ సైనికులు ఇతనికి లంచమిచ్చి తమవైపు తిప్పుకున్నారు.","table":null},{"a":"అబ్దుల్ రజాక్‌లారీ","e":"","table":null},{"a":"ఏడు నెలల పదిహేను రోజులు","e":"ఫిబ్రవరి 7న ప్రారంభమై భయంకరంగా సాగింది.","table":null},{"a":"అబ్దుల్లాఖాన్","e":"","table":null},{"a":"దౌలతాబాద్ కోట","e":"","table":null},{"a":"1696","e":"","table":null},{"a":"37 ఏళ్లు","e":"","table":null},{"a":"యోగిగా, రాజ్యపాలనలో, బందీగా","e":"రాకపూర్వం 15 సంవత్సరాలు యోగిగా, 15 సంవత్సరాలు రాజ్యపాలన, 15 సంవత్సరాలు బందీగా జీవించాడు.","table":null},{"a":"మత సహనం కలిగినవారు","e":"మత పక్షపాతంతో రాజ్యాన్ని పాలించడానికి వీరు వ్యతిరేకులు.","table":null},{"a":"షియా మతస్థులు, సూఫీభక్తులు","e":"","table":null},{"a":"హిందూ దేవాలయాలు","e":"","table":null},{"a":"గోపన్న (కంచర్లగోపన్న)","e":"ఈ అపరాధానికి 14 సంవత్సరాలు జైలు శిక్ష అనుభవించాడు.","table":null},{"a":"భద్రగిరి రాముడు (ఆలోచనగా)","e":"గోపరాజుకు ఒకటే మార్గం కనబడింది - భద్రాచల శ్రీరామాలయం పునర్నిర్మాణం చేయడం.","table":null},{"a":"కీర్తనలు (దాశరథి శతకం/రామదాసు కీర్తనలు)","e":"రాముని కీర్తించి కీర్తనలు పాడినాడు, కానీ పోతరాజుకు లభించిన కవితా పటిమ దొరకలేదు.","table":null},{"a":"ధర్మారావు","e":"సైనిక ప్రధానోద్యోగిగా ధర్మారావును, సందాల పరిపాలకునిగా గణపతిరావును నియమించాడు.","table":null},{"a":"నాయక జాతి (హిందువులు)","e":"","table":null},{"a":"చిత్రభారతము","e":"ఇతను కుతుబ్‌షాహీ వంశ మూలపురుషుడైన సుల్తాన్ కులీ కాలంలో రచించాడు.","table":null},{"a":"ఇబ్రహీం కుతుబ్‌షా","e":"గంగాధర కవి తన తపతీ సంవరణోపాఖ్యానాన్ని ఇబ్రహీంకు అంకితమిచ్చాడు.","table":null},{"a":"ఇబ్రహీం కుతుబ్‌షా","e":"","table":null},{"a":"ఉర్దూ, పారసీ","e":"ఇతని దివాన్‌లు 1800 పేజీలు, కానీ తెలుగు కవిత లభ్యం కాలేదు.","table":null},{"a":"యాతీనామా","e":"దాని ఉర్దూ అనువాదం పేరు సబ్రస్.","table":null},{"a":"సింగరాచార్యుడు","e":"రామకృష్ణ విజయమనే ద్వర్ధి కావ్యాన్ని, నలయాదవ రాఘవ పాండవీయం అనే నాలుగర్థాల కావ్యాన్ని రచించాడు.","table":null},{"a":"సారంగ తిమ్మయ్య","e":"","table":null},{"a":"కాదు","e":"మక్కామసీదు పూర్తికావడానికి 77 సంవత్సరాలు పట్టింది.","table":null},{"a":"మంగళవరం","e":"చాళుక్య యుగంలో గోల్కొండ ప్రాంతాన్ని మంగళవరం అనేవారు.","table":null},{"a":"మట్టి దుర్గం","e":"దీనిపై గొల్లలు గోవులను మేపేవారు, అందుకే గొల్లకొండ అని పేరు వచ్చిందని కొందరి అభిప్రాయం.","table":null},{"a":"సుల్తాన్ కులీ, క్రీ.శ. 1496","e":"సుబేదారు అయినప్పటి నుంచి రాతికోటగా మరమ్మతు చేయించాడు.","table":null},{"a":"మండుతున్న లోహాన్ని శత్రువులపైకి పోయడం","e":"రాతిగుమ్మం మీద నుంచి మరిగే నూనె, కరుగుతున్న లోహాన్ని పోసేవారు.","table":null},{"a":"కర్టెయిన్సీ వాల్","e":"","table":null},{"a":"వైబ్రేషన్","e":"చప్పట్ల ద్వారా శత్రువుల రాకను తెలియచేసేవారు, దర్బారు హాల్‌లో ప్రవేశిస్తే ఏయిర్ కండిషన్ హాల్‌లో ప్రవేశించినట్లు ఉంటుంది.","table":null},{"a":"మచిలీపట్నం","e":"ఆనాడు బొంబాయి రేవుకుగల ప్రాముఖ్యం ఆ రోజుల్లో మచిలీపట్నానికి లభించేది.","table":null},{"a":"అద్దకపు గుడ్డలు, ఉక్కు, ఇనుము, వజ్రాలు, తేయాకు","e":"ఏనుగు నగిషీలతో తయారు చేసిన కుర్చీలు, బల్లలు కూడా ఎగుమతి అయ్యేవి.","table":null},{"a":"కాదు","e":"ఆ కాలంలో ఈ గనులను సందర్శించిన విలియం మైథోల్డ్ అనే ఆంగ్లేయుడు వాపోయాడు.","table":null},{"a":"వజ్రపు గనులు","e":"","table":null},{"a":"30 వేలమంది","e":"","table":null},{"a":"కోటి ప్రభలతో","e":"","table":null},{"a":"సారాయి విక్రయం","e":"","table":null},{"a":"వైశ్య గృహాలు","e":"","table":null},{"a":"మాదన్న","e":"","table":null},{"a":"మహమ్మద్ కులీ కుతుబ్‌షా","e":"","table":null},{"a":"మొహర్రం (పీరీల పండుగ)","e":"హిందువులు కూడా పీరీలకు దట్టీలు కట్టేవారు.","table":null}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_number, title=excluded.title, answers_json=excluded.answers_json;
